for a,b in pairs: cmp_pad("ab",a,b)
# consecutive match across words
for a,b in [("afoo","a foo"),("afoo","a/foo"),("afoo","a_foo"),("afoo","axfoo")]:
    cmp_pad("foo",a,b)
