import subprocess, os
def winner2(pat,a,b,extra=[]):
    env={k:v for k,v in os.environ.items() if not k.startswith("FZF_")}
    outs=[]
    for inp in [f"{a}\n{b}\n", f"{b}\n{a}\n"]:
        p=subprocess.run(["./executable"]+extra+["--filter="+pat],input=inp.encode(),capture_output=True,env=env)
        outs.append(p.stdout.decode().split("\n"))
    # split gives trailing ''
    def first(out): return out[0] if out else None
    if len(outs[0])<2 or len(outs[1])<2 or outs[0][0]=="" or outs[0][1]=="":
        # if a or b is empty string this is ambiguous, avoid such cases
        if not (len(outs[0])>=2 and len(outs[1])>=2):
            return "nomatch"
    f0,f1=outs[0][0],outs[1][0]
    if f0==f1:
        return "A" if f0==a else "B"
    else:
        return "TIE"
