import subprocess,os
def T(pre,post): return "x"*pre+"foo"+"y"*post  # use y for post to distinguish in names but x/y both lower letters same class
items=[(pre,post) for pre in range(1,7) for post in range(1,7)]
inp="".join(T(*a)+"\n" for a in items)
env={k:v for k,v in os.environ.items() if not k.startswith("FZF_")}
for crit in ["end","begin","index","length"]:
    p=subprocess.run(["./executable",f"--tiebreak={crit}","--filter=foo"],input=inp.encode(),capture_output=True,env=env)
    out=p.stdout.decode().splitlines()
    def parse(s):
        pre=len(s)-len(s.lstrip('x')); post=len(s)-len(s.rstrip('y')) if False else len(s.rsplit('foo',1)[1]); return (pre,post)
    print(crit,[parse(s) for s in out])
PY"}

