def Aitem(P,E): return pad("z"+P+"ab"+E+"x")
def Bitem(k): return pad(" c"+"x"*k+" d")
for P,E in [("_","_"),(" "," "),("/","/"),("-","-"),(" ","_"),("_"," "),("/","_"),("-","_")]:
    A=Aitem(P,E); ties=[]
    for k in range(0,30):
        r=winner2("'ab' | cd",A,Bitem(k),["--tiebreak=index"])
        if r=="TIE": ties.append(k)
    print(P,E,"ties k",ties,"S=59-k",[59-k for k in ties])
