import sys; sys.path.insert(0,'/tmp/probe')
from pair2 import winner2
def pad(s,t=90): return s+"y"*(t-len(s))
# OR alt cde score =85-k as before, B has letters c d e only. For boundary pattern containing c (abc), B text has no a/b so boundary alt won't match (needs a b c substring; B has c but no ab).
# A text for pattern abc contains c but no d/e after, OR alt cde won't match. good.
def Bitem(k): return pad(" cd"+"x"*k+" e")
for pattext in ["a","ab","abc","abcd"]:
    # for abcd, B alt cde could match in A using c d (from abcd) then e? no e after. safe.
    for P,E in [("_","_"),(" "," "),("/","/"),(" ","_"),("_"," ")]:
        A=pad("z"+P+pattext+E+"x")
        q=f"'{pattext}' | cde"
        ties=[]
        for k in range(0,60):
            if winner2(q,A,Bitem(k),["--tiebreak=index"])=="TIE": ties.append(k)
        print(pattext,repr(P),repr(E),"ties",ties,"S",[85-k for k in ties])
PY"}

