import subprocess, time, os, shlex, atexit
class Tm:
    def __init__(self, name="fzftest", w=80,h=24):
        self.name=name; self.w=w; self.h=h
        subprocess.run(["tmux","kill-session","-t",name],capture_output=True)
    def start(self, cmd):
        subprocess.run(["tmux","kill-session","-t",self.name],capture_output=True)
        # cmd is shell string run via sh -c inside tmux, then keep pane with sleep
        full = cmd + "; echo __EXIT:$?; sleep 1000"
        subprocess.run(["tmux","new-session","-d","-s",self.name,"-x",str(self.w),"-y",str(self.h),full],check=True)
        time.sleep(0.4)
    def keys(self, *ks, wait=0.25):
        for k in ks:
            subprocess.run(["tmux","send-keys","-t",self.name,k])
            time.sleep(wait)
    def type(self, s, wait=0.05):
        subprocess.run(["tmux","send-keys","-t",self.name,"-l",s]); time.sleep(wait+0.15)
    def cap(self, esc=False):
        a=["tmux","capture-pane","-t",self.name,"-p"]
        if esc: a.append("-e")
        p=subprocess.run(a,capture_output=True,text=True)
        return p.stdout
    def show(self, esc=False):
        print(self.cap(esc))
    def kill(self):
        subprocess.run(["tmux","kill-session","-t",self.name],capture_output=True)
def go(cmd, actions=None,w=80,h=24):
    t=Tm(w=w,h=h); t.start(cmd)
    if actions: actions(t)
    return t
