{"command":"cat > algo.go <<'GO'
package main

import (
	"strings"
	"unicode"
)

const (
	scoreMatch        = 16
	scoreGapStart     = -3
	scoreGapExtension = -1
	bonusConsecutive  = 4
	bonusFirstCharMultiplier = 2
)

type charClass int

const (
	classWhite charClass = iota
	classNonWord
	classDelimiter
	classLower
	classUpper
	classLetter
	classNumber
)

type scoringScheme struct {
	bonusWhite     int
	bonusDelimiter int
	bonusNonWord   int
	bonusCamel     int
	delimiters     string
}

var (
	schemeDefaultScoring = scoringScheme{bonusWhite: 10, bonusDelimiter: 9, bonusNonWord: 8, bonusCamel: 7, delimiters: "/,:;|"}
	schemePathScoring    = scoringScheme{bonusWhite: 8, bonusDelimiter: 9, bonusNonWord: 8, bonusCamel: 7, delimiters: "/"}
	schemeHistoryScoring = scoringScheme{bonusWhite: 8, bonusDelimiter: 8, bonusNonWord: 8, bonusCamel: 7, delimiters: "/,:;|"}
)

func scoringFor(name string) scoringScheme {
	switch strings.ToLower(name) {
	case "path":
		return schemePathScoring
	case "history":
		return schemeHistoryScoring
	default:
		return schemeDefaultScoring
	}
}

func charClassOf(r rune, sc scoringScheme) charClass {
	if unicode.IsSpace(r) {
		return classWhite
	}
	if strings.ContainsRune(sc.delimiters, r) {
		return classDelimiter
	}
	if unicode.IsLower(r) {
		return classLower
	}
	if unicode.IsUpper(r) {
		return classUpper
	}
	if unicode.IsLetter(r) {
		return classLetter
	}
	if unicode.IsNumber(r) {
		return classNumber
	}
	return classNonWord
}

func isAlnumClass(c charClass) bool {
	return c == classLower || c == classUpper || c == classLetter || c == classNumber
}

func bonusFor(prev, cur charClass, sc scoringScheme) int {
	switch cur {
	case classWhite:
		return sc.bonusWhite
	case classNonWord:
		return sc.bonusNonWord
	case classDelimiter:
		switch prev {
		case classWhite:
			return sc.bonusWhite
		case classDelimiter:
			return sc.bonusDelimiter
		default:
			return sc.bonusNonWord
		}
	}
	// Alphanumeric-ish current character.
	switch prev {
	case classWhite:
		return sc.bonusWhite
	case classDelimiter:
		return sc.bonusDelimiter
	case classNonWord:
		return sc.bonusNonWord
	}
	if prev == classLower && cur == classUpper {
		return sc.bonusCamel
	}
	if prev != classNumber && cur == classNumber {
		return sc.bonusCamel
	}
	return 0
}

func bonusArray(text []rune, sc scoringScheme) []int {
	bonus := make([]int, len(text))
	prev := classWhite
	for i, r := range text {
		cur := charClassOf(r, sc)
		bonus[i] = bonusFor(prev, cur, sc)
		prev = cur
	}
	return bonus
}

// lowerTextRune is the case conversion applied to candidate text while
// matching. It deliberately differs from Go's full simple lower-casing for
// a few categories (for example title-case letters), matching the behavior
// observed from the reference executable.
func lowerTextRune(r rune) rune {
	if r >= 'A' && r <= 'Z' {
		return r + 32
	}
	if r < 128 {
		return r
	}
	if unicode.IsUpper(r) {
		return unicode.ToLower(r)
	}
	return r
}

func lowerPatternRunes(rs []rune) []rune {
	return []rune(strings.ToLower(string(rs)))
}

func patternRunesForCase(rs []rune, caseSensitive bool) []rune {
	if caseSensitive {
		out := make([]rune, len(rs))
		copy(out, rs)
		return out
	}
	return lowerPatternRunes(rs)
}

func normalizeTextRune(t, pattern rune, normalize bool) rune {
	if normalize && pattern < 128 {
		if mapped, ok := normalizeMap[t]; ok {
			return mapped
		}
	}
	return t
}

func equalRune(textRune, patternRune rune, caseSensitive, normalize bool) bool {
	t := textRune
	if !caseSensitive {
		t = lowerTextRune(t)
	}
	t = normalizeTextRune(t, patternRune, normalize)
	return t == patternRune
}

// scoreAlignment scores a concrete alignment (positions of every pattern
// rune) under the scoring rules used by fuzzy and exact matches.
func scoreAlignment(text, pattern []rune, positions []int, sc scoringScheme) int {
	if len(positions) == 0 {
		return 0
	}
	bonus := bonusArray(text, sc)
	score := 0
	runStart := positions[0]
	for i, pos := range positions {
		score += scoreMatch
		if i == 0 {
			score += bonusFirstCharMultiplier * bonus[pos]
			continue
		}
		prevPos := positions[i-1]
		if pos == prevPos+1 {
			b := bonus[pos]
			if bonus[runStart] > b {
				b = bonus[runStart]
			}
			if bonusConsecutive > b {
				b = bonusConsecutive
			}
			score += b
		} else {
			runStart = pos
			gap := pos - prevPos - 1
			score += scoreGapStart + (gap-1)*scoreGapExtension
			score += bonus[pos]
		}
	}
	return score
}

type matchResult struct {
	score     int
	begin     int // rune offset in the segment
	end       int // exclusive rune offset in the segment
	positions []int
	ok        bool
}

// subsequence check (also used for inverse fuzzy terms)
func fuzzySubsequence(text, pattern []rune, caseSensitive, normalize bool) bool {
	j := 0
	for _, tr := range text {
		if j < len(pattern) && equalRune(tr, pattern[j], caseSensitive, normalize) {
			j++
		}
	}
	return j == len(pattern)
}

type dpState struct {
	score   int
	valid   bool
	prevPos int
	prevRun int // run length of previous state (for i>0)
}

// fuzzyMatchForward finds the best-scoring alignment scanning forward.
func fuzzyMatchForward(text, pattern []rune, caseSensitive, normalize bool, sc scoringScheme) matchResult {
	n := len(text)
	m := len(pattern)
	if m == 0 {
		return matchResult{score: 0, ok: true}
	}
	if m > n {
		return matchResult{}
	}
	// Quick subsequence rejection.
	if !fuzzySubsequence(text, pattern, caseSensitive, normalize) {
		return matchResult{}
	}
	bonus := bonusArray(text, sc)
	// rows[i][j][run] (run is 1-based length of consecutive run ending at j)
	type cell struct {
		states []dpState // index by run-1
	}
	rows := make([][]cell, m)
	for i := range rows {
		rows[i] = make([]cell, n)
		for j := range rows[i] {
			rows[i][j].states = make([]dpState, i+1)
		}
	}
	for i := 0; i < m; i++ {
		// For non-consecutive transitions we need, for each j, the best
		// previous state at positions <= j-2 maximizing score+pos
		// (gap penalty = (j-pos-1)+2).  Maintain incrementally.
		type pref struct {
			key   int // score+pos
			score int
			pos   int
			run   int
			valid bool
		}
		var bestPref pref
		prefAt := make([]pref, n)
		if i > 0 {
			for j := 0; j < n; j++ {
				// candidate ending at j-2 becomes available for this j
				k := j - 2
				if k >= 0 {
					for runIdx, st := range rows[i-1][k].states {
						if !st.valid {
							continue
						}
						key := st.score + k
						if !bestPref.valid || key > bestPref.key {
							bestPref = pref{key: key, score: st.score, pos: k, run: runIdx + 1, valid: true}
						}
					}
				}
				prefAt[j] = bestPref
			}
		}
		for j := 0; j < n; j++ {
			if !equalRune(text[j], pattern[i], caseSensitive, normalize) {
				continue
			}
			if i == 0 {
				rows[i][j].states[0] = dpState{score: scoreMatch + bonusFirstCharMultiplier*bonus[j], valid: true, prevPos: -1}
				continue
			}
			// Non-consecutive: run length 1.
			if pr := prefAt[j]; pr.valid {
				gap := j - pr.pos - 1
				s := pr.score + scoreMatch + bonus[j] + scoreGapStart + (gap-1)*scoreGapExtension
				rows[i][j].states[0] = dpState{score: s, valid: true, prevPos: pr.pos, prevRun: pr.run}
			}
			// Consecutive from j-1.
			if j > 0 {
				for runIdx, st := range rows[i-1][j-1].states {
					if !st.valid {
						continue
					}
					run := runIdx + 1
					runStart := j - run
					if runStart < 0 {
						continue
					}
					b := bonus[j]
					if bonus[runStart] > b {
						b = bonus[runStart]
					}
					if bonusConsecutive > b {
						b = bonusConsecutive
					}
					s := st.score + scoreMatch + b
					newRun := run + 1
					cur := &rows[i][j].states[newRun-1]
					if !cur.valid || s > cur.score {
						*cur = dpState{score: s, valid: true, prevPos: j - 1, prevRun: run}
					}
				}
			}
		}
	}
	// Choose best final state: scan positions left to right, strict >.
	bestScore := 0
	bestPos := -1
	bestRun := 0
	found := false
	for j := 0; j < n; j++ {
		for runIdx, st := range rows[m-1][j].states {
			if !st.valid {
				continue
			}
			if !found || st.score > bestScore {
				found = true
				bestScore = st.score
				bestPos = j
				bestRun = runIdx + 1
			}
		}
	}
	if !found {
		return matchResult{}
	}
	positions := make([]int, m)
	pos := bestPos
	run := bestRun
	for i := m - 1; i >= 0; i-- {
		positions[i] = pos
		st := rows[i][pos].states[run-1]
		pos = st.prevPos
		run = st.prevRun
	}
	return matchResult{score: bestScore, begin: positions[0], end: positions[m-1] + 1, positions: positions, ok: true}
}

func reverseRunes(rs []rune) []rune {
	out := make([]rune, len(rs))
	for i, r := range rs {
		out[len(rs)-1-i] = r
	}
	return out
}

func fuzzyMatch(text, pattern []rune, caseSensitive, normalize, forward bool, sc scoringScheme) matchResult {
	if forward {
		return fuzzyMatchForward(text, pattern, caseSensitive, normalize, sc)
	}
	// Backward: reverse both strings and run the forward algorithm.
	rt := reverseRunes(text)
	rp := reverseRunes(pattern)
	res := fuzzyMatchForward(rt, rp, caseSensitive, normalize, sc)
	if !res.ok {
		return res
	}
	n := len(text)
	positions := make([]int, len(res.positions))
	for i, p := range res.positions {
		positions[len(res.positions)-1-i] = n - 1 - p
	}
	return matchResult{score: res.score, begin: positions[0], end: positions[len(positions)-1] + 1, positions: positions, ok: true}
}

// fuzzyMatchV1 is an approximation of the faster V1 algorithm: greedily
// determine a match window, then greedily match within it and score that
// alignment.
func fuzzyMatchV1(text, pattern []rune, caseSensitive, normalize, forward bool, sc scoringScheme) matchResult {
	if len(pattern) == 0 {
		return matchResult{ok: true}
	}
	if !forward {
		// Scan from the end for the last window, then greedily match
		// forward within the window (mirrors the forward path below).
		rt := reverseRunes(text)
		rp := reverseRunes(pattern)
		res := fuzzyMatchV1Forward(rt, rp, caseSensitive, normalize, sc)
		if !res.ok {
			return res
		}
		n := len(text)
		positions := make([]int, len(res.positions))
		for i, p := range res.positions {
			positions[len(res.positions)-1-i] = n - 1 - p
		}
		return matchResult{score: res.score, begin: positions[0], end: positions[len(positions)-1] + 1, positions: positions, ok: true}
	}
	return fuzzyMatchV1Forward(text, pattern, caseSensitive, normalize, sc)
}

func fuzzyMatchV1Forward(text, pattern []rune, caseSensitive, normalize bool, sc scoringScheme) matchResult {
	n := len(text)
	m := len(pattern)
	// Forward greedy to find end.
	j := 0
	end := -1
	for i := 0; i < n; i++ {
		if j < m && equalRune(text[i], pattern[j], caseSensitive, normalize) {
			j++
			if j == m {
				end = i + 1
				break
			}
		}
	}
	if end < 0 {
		return matchResult{}
	}
	// Backward greedy from end to find start.
	j = m - 1
	start := -1
	for i := end - 1; i >= 0; i-- {
		if j >= 0 && equalRune(text[i], pattern[j], caseSensitive, normalize) {
			j--
			if j < 0 {
				start = i
				break
			}
		}
	}
	if start < 0 {
		return matchResult{}
	}
	// Greedy match within [start,end).
	positions := make([]int, 0, m)
	j = 0
	for i := start; i < end && j < m; i++ {
		if equalRune(text[i], pattern[j], caseSensitive, normalize) {
			positions = append(positions, i)
			j++
		}
	}
	if j != m {
		return matchResult{}
	}
	score := scoreAlignment(text, pattern, positions, sc)
	return matchResult{score: score, begin: positions[0], end: positions[m-1] + 1, positions: positions, ok: true}
}

func trimLeftSpaceRunes(text []rune) int {
	i := 0
	for i < len(text) && unicode.IsSpace(text[i]) {
		i++
	}
	return i
}

func trimRightSpaceRunes(text []rune) int {
	i := len(text)
	for i > 0 && unicode.IsSpace(text[i-1]) {
		i--
	}
	return i
}

func equalAt(text []rune, start int, pattern []rune, caseSensitive, normalize bool) bool {
	if start < 0 || start+len(pattern) > len(text) {
		return false
	}
	for i, pr := range pattern {
		if !equalRune(text[start+i], pr, caseSensitive, normalize) {
			return false
		}
	}
	return true
}

func consecutivePositions(start, m int) []int {
	pos := make([]int, m)
	for i := range pos {
		pos[i] = start + i
	}
	return pos
}

func exactMatch(text, pattern []rune, caseSensitive, normalize, forward bool, sc scoringScheme) matchResult {
	m := len(pattern)
	if m == 0 {
		return matchResult{ok: true}
	}
	best := matchResult{}
	for start := 0; start+m <= len(text); start++ {
		if !equalAt(text, start, pattern, caseSensitive, normalize) {
			continue
		}
		pos := consecutivePositions(start, m)
		s := scoreAlignment(text, pattern, pos, sc)
		if !best.ok || s > best.score || (!forward && s == best.score) {
			best = matchResult{score: s, begin: start, end: start + m, positions: pos, ok: true}
		}
	}
	return best
}

func prefixMatch(text, pattern []rune, caseSensitive, normalize bool, sc scoringScheme) matchResult {
	start := 0
	if len(pattern) == 0 || !unicode.IsSpace(pattern[0]) {
		start = trimLeftSpaceRunes(text)
	}
	if !equalAt(text, start, pattern, caseSensitive, normalize) {
		return matchResult{}
	}
	pos := consecutivePositions(start, len(pattern))
	return matchResult{score: scoreAlignment(text, pattern, pos, sc), begin: start, end: start + len(pattern), positions: pos, ok: true}
}

func suffixMatch(text, pattern []rune, caseSensitive, normalize bool, sc scoringScheme) matchResult {
	end := len(text)
	if len(pattern) == 0 || !unicode.IsSpace(pattern[len(pattern)-1]) {
		end = trimRightSpaceRunes(text)
	}
	start := end - len(pattern)
	if !equalAt(text, start, pattern, caseSensitive, normalize) {
		return matchResult{}
	}
	pos := consecutivePositions(start, len(pattern))
	return matchResult{score: scoreAlignment(text, pattern, pos, sc), begin: start, end: end, positions: pos, ok: true}
}

func equalMatch(text, pattern []rune, caseSensitive, normalize bool, sc scoringScheme) matchResult {
	start := 0
	end := len(text)
	if len(pattern) == 0 {
		return matchResult{ok: true}
	}
	if !unicode.IsSpace(pattern[0]) {
		start = trimLeftSpaceRunes(text)
	}
	if !unicode.IsSpace(pattern[len(pattern)-1]) {
		end = trimRightSpaceRunes(text)
	}
	if end-start != len(pattern) || !equalAt(text, start, pattern, caseSensitive, normalize) {
		return matchResult{}
	}
	pos := consecutivePositions(start, len(pattern))
	return matchResult{score: scoreAlignment(text, pattern, pos, sc), begin: start, end: end, positions: pos, ok: true}
}

func boundaryScore(text []rune, start, m int, sc scoringScheme) int {
	bonus := bonusArray(text, sc)
	bp := bonus[start]
	strongP := !(start > 0 && text[start-1] == '_')
	end := start + m
	strongE := !(end < len(text) && text[end] == '_')
	var f int
	switch {
	case strongP && strongE:
		f = 20 + bp
	case strongP && !strongE:
		f = 27
	case !strongP && strongE:
		f = 26
	default:
		f = 25
	}
	return scoreMatch*m + 10*(m-1) + f
}

func boundaryMatch(text, pattern []rune, caseSensitive, normalize, forward bool, sc scoringScheme) matchResult {
	m := len(pattern)
	if m == 0 {
		return matchResult{ok: true}
	}
	best := matchResult{}
	for start := 0; start+m <= len(text); start++ {
		if !equalAt(text, start, pattern, caseSensitive, normalize) {
			continue
		}
		if start > 0 && isAlnumClass(charClassOf(text[start-1], sc)) {
			continue
		}
		end := start + m
		if end < len(text) && isAlnumClass(charClassOf(text[end], sc)) {
			continue
		}
		pos := consecutivePositions(start, m)
		s := boundaryScore(text, start, m, sc)
		if !best.ok || s > best.score || (!forward && s == best.score) {
			best = matchResult{score: s, begin: start, end: end, positions: pos, ok: true}
		}
	}
	return best
}
