// ---------- Delimiter ----------

type delimiter struct {
	awk     bool
	literal *string
	regex   *regexp.Regexp
}

func awkDelimiter() delimiter { return delimiter{awk: true} }

func parseDelimiter(s string) delimiter {
	s2 := strings.ReplaceAll(s, "\\t", "\t")
	if utf8.RuneCountInString(s2) == 1 || s2 == regexp.QuoteMeta(s2) {
		lit := s2
		return delimiter{literal: &lit}
	}
	if re, err := regexp.Compile(s2); err == nil {
		return delimiter{regex: re}
	}
	lit := s2
	return delimiter{literal: &lit}
}

type token struct {
	b0, b1       int // byte range including trailing delimiter
	r0, r1       int // rune range
	delimB       int // byte length of trailing delimiter
}

func byteToRuneOffsets(s string) map[int]int {
	m := make(map[int]int)
	ri := 0
	for bi := range s {
		m[bi] = ri
		ri++
	}
	m[len(s)] = ri
	return m
}

func tokenize(s string, d delimiter) []token {
	if d.awk {
		return tokenizeAwk(s)
	}
	off := byteToRuneOffsets(s)
	conv := func(b int) int {
		if r, ok := off[b]; ok {
			return r
		}
		return utf8.RuneCountInString(s[:b])
	}
	mk := func(b0, b1, delimB int) token {
		return token{b0: b0, b1: b1, r0: conv(b0), r1: conv(b1), delimB: delimB}
	}
	var toks []token
	if d.literal != nil {
		lit := *d.literal
		if lit == "" {
			if len(s) == 0 {
				return []token{mk(0, 0, 0)}
			}
			for _, part := range strings.SplitAfter(s, "") {
				// SplitAfter with empty separator splits after each UTF-8 sequence.
				// This loop is only for counting; construct tokens by rune boundaries below.
				_ = part
				break
			}
			starts := []int{}
			for bi := range s {
				starts = append(starts, bi)
			}
			starts = append(starts, len(s))
			for i := 0; i+1 < len(starts); i++ {
				toks = append(toks, mk(starts[i], starts[i+1], 0))
			}
			return toks
		}
		start := 0
		for {
			idx := strings.Index(s[start:], lit)
			if idx < 0 {
				break
			}
			end := start + idx + len(lit)
			toks = append(toks, mk(start, end, len(lit)))
			start = end
		}
		toks = append(toks, mk(start, len(s), 0))
		return toks
	}
	// Regex delimiter.
	matches := d.regex.FindAllStringIndex(s, -1)
	start := 0
	for _, m := range matches {
		toks = append(toks, mk(start, m[1], m[1]-m[0]))
		start = m[1]
	}
	if start < len(s) {
		toks = append(toks, mk(start, len(s), 0))
	}
	return toks
}

func tokenizeAwk(s string) []token {
	// Fields are separated by runs of spaces/tabs.  Leading separators are
	// skipped; the separator following a field belongs to that field's token.
	type runePos struct{ b, r int; ch rune }
	var positions []runePos
	ri := 0
	for bi, ch := range s {
		positions = append(positions, runePos{bi, ri, ch})
		ri++
	}
	endB, endR := len(s), ri
	isSep := func(ch rune) bool { return ch == ' ' || ch == '\t' }
	var toks []token
	i := 0
	for i < len(positions) && isSep(positions[i].ch) {
		i++
	}
	for i < len(positions) {
		start := positions[i]
		for i < len(positions) && !isSep(positions[i].ch) {
			i++
		}
		// separator run
		sepStartB, sepStartR := endB, endR
		if i < len(positions) {
			sepStartB, sepStartR = positions[i].b, positions[i].r
		}
		for i < len(positions) && isSep(positions[i].ch) {
			i++
		}
		tokEndB, tokEndR := endB, endR
		if i < len(positions) {
			tokEndB, tokEndR = positions[i].b, positions[i].r
		}
		_ = sepStartR
		toks = append(toks, token{b0: start.b, b1: tokEndB, r0: start.r, r1: tokEndR, delimB: tokEndB - sepStartB})
	}
	return toks
}

// ---------- Field ranges ----------

type fieldRange struct {
	begin int // as written, 0 = omitted
	end   int
}

func parseFieldInt(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	digits := s
	if strings.HasPrefix(digits, "-") {
		digits = digits[1:]
	}
	if digits == "" {
		return 0, false
	}
	for _, c := range digits {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, false
	}
	return n, true
}

func parseRangeComponent(part string) (fieldRange, bool) {
	if part == "" {
		return fieldRange{}, false
	}
	if !strings.Contains(part, "..") {
		n, ok := parseFieldInt(part)
		if !ok || n == 0 {
			return fieldRange{}, false
		}
		return fieldRange{begin: n, end: n}, true
	}
	pieces := strings.Split(part, "..")
	if len(pieces) != 2 {
		return fieldRange{}, false
	}
	var r fieldRange
	if pieces[0] != "" {
		n, ok := parseFieldInt(pieces[0])
		if !ok || n == 0 {
			return fieldRange{}, false
		}
		r.begin = n
	}
	if pieces[1] != "" {
		n, ok := parseFieldInt(pieces[1])
		if !ok || n == 0 {
			return fieldRange{}, false
		}
		r.end = n
	}
	// A negative begin cannot be combined with a positive end.
	if r.begin < 0 && r.end > 0 {
		return fieldRange{}, false
	}
	return r, true
}

func parseRangeList(s string) ([]fieldRange, error) {
	if s == "" {
		return nil, fmt.Errorf("invalid format: %s", s)
	}
	parts := strings.Split(s, ",")
	ranges := make([]fieldRange, 0, len(parts))
	for _, p := range parts {
		r, ok := parseRangeComponent(p)
		if !ok {
			return nil, fmt.Errorf("invalid format: %s", s)
		}
		ranges = append(ranges, r)
	}
	return ranges, nil
}

// resolve a range against num tokens: returns 0-based inclusive indices.
func resolveRange(r fieldRange, num int) (int, int, bool) {
	if num <= 0 {
		return 0, 0, false
	}
	var b, e int // 1-based
	if r.begin == 0 {
		b = 1
	} else if r.begin < 0 {
		b = num + r.begin + 1
	} else {
		b = r.begin
	}
	if r.end == 0 {
		e = num
	} else if r.end < 0 {
		e = num + r.end + 1
	} else {
		e = r.end
	}
	if b < 1 {
		b = 1
	}
	if e > num {
		e = num
	}
	if b > e || b > num || e < 1 {
		return 0, 0, false
	}
	return b - 1, e - 1, true
}

// ---------- with-nth / accept-nth specification ----------

type templatePiece struct {
	literal  string
	isIndex  bool // {n}
	ranges   []fieldRange
	invalid  bool // placeholder whose range list failed to parse
	isHolder bool
}

type nthSpec struct {
	ranges     []fieldRange
	isTemplate bool
	pieces     []templatePiece
	orig       string
}

var placeholderRe = regexp.MustCompile(`\{n\}|\{[-0-9.,]+\}`)

func parseNthSpec(s string) (*nthSpec, error) {
	isRangeChars := s != ""
	if isRangeChars {
		for _, c := range s {
			if !(c == '-' || c == '.' || c == ',' || (c >= '0' && c <= '9')) {
				isRangeChars = false
				break
			}
		}
	}
	if isRangeChars {
		ranges, err := parseRangeList(s)
		if err != nil {
			return nil, err
		}
		return &nthSpec{ranges: ranges, orig: s}, nil
	}
	locs := placeholderRe.FindAllStringIndex(s, -1)
	if len(locs) == 0 {
		return nil, fmt.Errorf("template should include at least 1 placeholder: %s", s)
	}
	spec := &nthSpec{isTemplate: true, orig: s}
	last := 0
	for _, loc := range locs {
		if loc[0] > last {
			spec.pieces = append(spec.pieces, templatePiece{literal: s[last:loc[0]]})
		}
		content := s[loc[0]+1 : loc[1]-1]
		if content == "n" {
			spec.pieces = append(spec.pieces, templatePiece{isHolder: true, isIndex: true})
		} else {
			ranges, err := parseRangeList(content)
			if err != nil {
				spec.pieces = append(spec.pieces, templatePiece{isHolder: true, invalid: true})
			} else {
				spec.pieces = append(spec.pieces, templatePiece{isHolder: true, ranges: ranges})
			}
		}
		last = loc[1]
	}
	if last < len(s) {
		spec.pieces = append(spec.pieces, templatePiece{literal: s[last:]})
	}
	return spec, nil
}

func joinTokenRefs(s string, toks []token, refs []int) string {
	if len(refs) == 0 {
		return ""
	}
	var b strings.Builder
	for _, idx := range refs {
		t := toks[idx]
		b.WriteString(s[t.b0:t.b1])
	}
	out := b.String()
	// Strip the delimiter of the last non-empty referenced token.
	for i := len(refs) - 1; i >= 0; i-- {
		t := toks[refs[i]]
		if t.b1 == t.b0 {
			continue
		}
		if t.delimB > 0 && len(out) >= t.delimB {
			out = out[:len(out)-t.delimB]
		}
		break
	}
	return out
}

func refsForRanges(toks []token, ranges []fieldRange) []int {
	var refs []int
	for _, r := range ranges {
		b, e, ok := resolveRange(r, len(toks))
		if !ok {
			continue
		}
		for i := b; i <= e; i++ {
			refs = append(refs, i)
		}
	}
	return refs
}

// transformBySpec applies a with-nth/accept-nth specification to a line.
func transformBySpec(s string, index int, d delimiter, spec *nthSpec) string {
	if spec == nil {
		return s
	}
	toks := tokenize(s, d)
	if !spec.isTemplate {
		return joinTokenRefs(s, toks, refsForRanges(toks, spec.ranges))
	}
	var b strings.Builder
	for _, piece := range spec.pieces {
		if !piece.isHolder {
			b.WriteString(piece.literal)
			continue
		}
		if piece.isIndex {
			b.WriteString(strconv.Itoa(index))
			continue
		}
		if piece.invalid {
			continue
		}
		b.WriteString(joinTokenRefs(s, toks, refsForRanges(toks, piece.ranges)))
	}
	return b.String()
}

// ---------- Terms and patterns ----------

type termType int

const (
	termFuzzy termType = iota
	termExact
	termPrefix
	termSuffix
	termEqual
	termBoundary
)

type caseMode int

const (
	caseSmart caseMode = iota
	caseIgnore
	caseRespect
)

type term struct {
	typ           termType
	inverse       bool
	text          []rune // original term text after special stripping
	pattern       []rune // case-adjusted pattern runes
	caseSensitive bool
}

func makeTerm(typ termType, inverse bool, textStr string, cm caseMode) term {
	text := []rune(textStr)
	sensitive := false
	switch cm {
	case caseRespect:
		sensitive = true
	case caseIgnore:
		sensitive = false
	default: // smart
		sensitive = strings.ToLower(textStr) != textStr
	}
	return term{typ: typ, inverse: inverse, text: text, pattern: patternRunesForCase(text, sensitive), caseSensitive: sensitive}
}

// parseTerm parses one extended-search token.  The second return value is
// false when the token reduces to an empty term and should be discarded.
func parseTermToken(token string, fuzzy bool, cm caseMode) (term, bool) {
	typ := termExact
	if fuzzy {
		typ = termFuzzy
	}
	inverse := false
	textStr := token
	if strings.HasPrefix(textStr, "!") {
		inverse = true
		typ = termExact
		textStr = textStr[1:]
	}
	if len(textStr) >= 3 && strings.HasPrefix(textStr, "'") && strings.HasSuffix(textStr, "'") {
		typ = termBoundary
		textStr = textStr[1 : len(textStr)-1]
	} else if strings.HasPrefix(textStr, "'") {
		if typ == termExact {
			typ = termFuzzy
		} else {
			typ = termExact
		}
		textStr = textStr[1:]
		if strings.HasSuffix(textStr, "$") {
			textStr = textStr[:len(textStr)-1]
		}
	} else if strings.HasPrefix(textStr, "^") {
		textStr = textStr[1:]
		if strings.HasSuffix(textStr, "$") {
			typ = termEqual
			textStr = textStr[:len(textStr)-1]
		} else {
			typ = termPrefix
		}
	} else if strings.HasSuffix(textStr, "$") && len(textStr) > 1 {
		typ = termSuffix
		textStr = textStr[:len(textStr)-1]
	}
	if textStr == "" {
		return term{}, false
	}
	return makeTerm(typ, inverse, textStr, cm), true
}

func tokenizeExtendedQuery(q string) []string {
	var tokens []string
	var buf []rune
	inToken := false
	runes := []rune(q)
	flush := func() {
		if inToken {
			tokens = append(tokens, string(buf))
			buf = nil
			inToken = false
		}
	}
	for i := 0; i < len(runes); i++ {
		r := runes[i]
		if r == '\\' && i+1 < len(runes) && runes[i+1] == ' ' {
			buf = append(buf, ' ')
			inToken = true
			i++
			continue
		}
		if r == ' ' {
			flush()
			continue
		}
		if r == '\t' {
			buf = append(buf, ' ')
			inToken = true
			continue
		}
		buf = append(buf, r)
		inToken = true
	}
	flush()
	return tokens
}

type pattern struct {
	sets     [][]term
	sortable bool
	forward  bool
	algoV1   bool
	isEmpty  bool
	text     string // original query
}

func buildPattern(query string, cm caseMode, fuzzy, extended, forward, algoV1 bool) *pattern {
	p := &pattern{forward: forward, algoV1: algoV1, text: query}
	if !extended {
		if query == "" {
			p.isEmpty = true
			return p
		}
		typ := termExact
		if fuzzy {
			typ = termFuzzy
		}
		t := makeTerm(typ, false, query, cm)
		p.sets = [][]term{{t}}
		p.sortable = true
		return p
	}
	tokens := tokenizeExtendedQuery(query)
	// Parse terms first ( discarding empty ones) while retaining "|" markers.
	type tokOrTerm struct {
		isBar bool
		t     term
	}
	var items []tokOrTerm
	for _, tok := range tokens {
		if tok == "|" {
			items = append(items, tokOrTerm{isBar: true})
			continue
		}
		if t, ok := parseTermToken(tok, fuzzy, cm); ok {
			items = append(items, tokOrTerm{t: t})
		}
	}
	// Group into OR sets.  A "|" item is an operator only when a set is in
	// progress and we are not already waiting for the OR operand; otherwise
	// it is a literal term.
	var current []term
	orPending := false
	flushSet := func() {
		if len(current) > 0 {
			p.sets = append(p.sets, current)
			current = nil
		}
	}
	for _, it := range items {
		if it.isBar && len(current) > 0 && !orPending {
			orPending = true
			continue
		}
		var t term
		if it.isBar {
			// Literal "|" term.
			t = makeTerm(termFuzzyOrExact(fuzzy), false, "|", cm)
		} else {
			t = it.t
		}
		if orPending {
			current = append(current, t)
			orPending = false
		} else {
			flushSet()
			current = []term{t}
		}
	}
	flushSet()
	if len(p.sets) == 0 {
		p.isEmpty = true
	}
	for _, set := range p.sets {
		for _, t := range set {
			if !t.inverse {
				p.sortable = true
			}
		}
	}
	return p
}

func termFuzzyOrExact(fuzzy bool) termType {
	if fuzzy {
		return termFuzzy
	}
	return termExact
}

// ---------- Matching ----------

type segment struct {
	runes  []rune
	offset int // rune offset in the (transformed) search text
}

type offsetRange struct {
	begin int
	end   int
}

type itemMatch struct {
	score   int
	offsets []offsetRange
	ok      bool
}

func (t term) matchSegment(text []rune, normalize, algoV1, forward bool, sc scoringScheme) matchResult {
	switch t.typ {
	case termFuzzy:
		if algoV1 {
			return fuzzyMatchV1(text, t.pattern, t.caseSensitive, normalize, forward, sc)
		}
		return fuzzyMatch(text, t.pattern, t.caseSensitive, normalize, forward, sc)
	case termExact:
		return exactMatch(text, t.pattern, t.caseSensitive, normalize, forward, sc)
	case termPrefix:
		return prefixMatch(text, t.pattern, t.caseSensitive, normalize, sc)
	case termSuffix:
		return suffixMatch(text, t.pattern, t.caseSensitive, normalize, sc)
	case termEqual:
		return equalMatch(text, t.pattern, t.caseSensitive, normalize, sc)
	case termBoundary:
		return boundaryMatch(text, t.pattern, t.caseSensitive, normalize, forward, sc)
	}
	return matchResult{}
}

// matchSegments attempts the term (ignoring its inverse flag) in each
// segment in order; returns (result, found).
func (t term) matchSegments(segments []segment, normalize, algoV1, forward bool, sc scoringScheme) (matchResult, int, bool) {
	for idx, seg := range segments {
		res := t.matchSegment(seg.runes, normalize, algoV1, forward, sc)
		if res.ok {
			return res, idx, true
		}
	}
	return matchResult{}, 0, false
}

func (p *pattern) match(segments []segment, normalize bool, sc scoringScheme) itemMatch {
	if p.isEmpty {
		return itemMatch{ok: true}
	}
	total := 0
	var offsets []offsetRange
	for _, set := range p.sets {
		setMatched := false
		var setRes matchResult
		var setSeg segment
		havePositive := false
		for _, t := range set {
			res, segIdx, found := t.matchSegments(segments, normalize, p.algoV1, p.forward, sc)
			if t.inverse {
				if !found {
					setMatched = true
				}
				continue
			}
			if found {
				setMatched = true
				havePositive = true
				setRes = res
				setSeg = segments[segIdx]
				break
			}
		}
		if !setMatched {
			return itemMatch{}
		}
		if havePositive {
			total += setRes.score
			offsets = append(offsets, offsetRange{begin: setSeg.offset + setRes.begin, end: setSeg.offset + setRes.end})
		}
	}
	return itemMatch{score: total, offsets: offsets, ok: true}
}

func segmentsForText(text string, d delimiter, nth []fieldRange) []segment {
	textRunes := []rune(text)
	if len(nth) == 0 {
		return []segment{{runes: textRunes, offset: 0}}
	}
	toks := tokenize(text, d)
	var segs []segment
	for _, r := range nth {
		b, e, ok := resolveRange(r, len(toks))
		if !ok {
			continue
		}
		startR := toks[b].r0
		endR := toks[e].r1
		if startR > len(textRunes) {
			startR = len(textRunes)
		}
		if endR > len(textRunes) {
			endR = len(textRunes)
		}
		segs = append(segs, segment{runes: textRunes[startR:endR], offset: startR})
	}
	return segs
}

