package main

import (
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"
)

type sortCriterion int

const (
	critLength sortCriterion = iota
	critChunk
	critPathname
	critBegin
	critEnd
	critIndex
)

func parseTiebreakValue(s string, current []sortCriterion) ([]sortCriterion, error) {
	_ = current
	parts := strings.Split(s, ",")
	var out []sortCriterion
	seen := map[sortCriterion]string{}
	for i, part := range parts {
		var c sortCriterion
		switch part {
		case "length":
			c = critLength
		case "chunk":
			c = critChunk
		case "pathname":
			c = critPathname
		case "begin":
			c = critBegin
		case "end":
			c = critEnd
		case "index":
			c = critIndex
			if i != len(parts)-1 {
				return nil, errString("index should be the last criterion")
			}
		default:
			return nil, errString("invalid sort criterion: " + part)
		}
		if prev, dup := seen[c]; dup {
			_ = prev
			return nil, errString("duplicate sort criteria: " + part)
		}
		seen[c] = part
		out = append(out, c)
	}
	// "index" position errors take precedence as they are encountered above,
	// matching the reference for e.g. length,index,begin.
	hasIndex := len(out) > 0 && out[len(out)-1] == critIndex
	if !hasIndex {
		out = append(out, critIndex)
	}
	return out, nil
}

type errString string

func (e errString) Error() string { return string(e) }

type item struct {
	orig       string // output base text (ANSI stripped when --ansi)
	rawOrig    string // line as read (before ANSI stripping)
	text       string // display/search text (with-nth applied to orig)
	index      int
	ansiColors []ansiSpan // for display when --ansi (filled later)
}

func trimmedTextRunes(s string) []rune {
	rs := []rune(s)
	start := 0
	for start < len(rs) && unicode.IsSpace(rs[start]) {
		start++
	}
	end := len(rs)
	for end > start && unicode.IsSpace(rs[end-1]) {
		end--
	}
	return rs[start:end]
}

func (it *item) trimmedLen() int {
	return len(trimmedTextRunes(it.text))
}

type result struct {
	item    *item
	score   int
	offsets []offsetRange
}

func (r *result) minBegin() (int, bool) {
	if len(r.offsets) == 0 {
		return 0, false
	}
	m := r.offsets[0].begin
	for _, o := range r.offsets[1:] {
		if o.begin < m {
			m = o.begin
		}
	}
	return m, true
}

func (r *result) maxEnd() (int, bool) {
	if len(r.offsets) == 0 {
		return 0, false
	}
	m := r.offsets[0].end
	for _, o := range r.offsets[1:] {
		if o.end > m {
			m = o.end
		}
	}
	return m, true
}

func (r *result) chunkLen() int {
	begin, ok1 := r.minBegin()
	end, ok2 := r.maxEnd()
	if !ok1 || !ok2 {
		return int(^uint(0) >> 1)
	}
	rs := trimmedTextRunes(r.item.text)
	if begin > len(rs) {
