package main

import "unicode/utf8"

type ansiSpan struct {
	pos  int    // rune index in stripped text
	code string // full escape sequence for SGR (CSI ... m), or "" for reset marker
}

func stripAnsi(s string) (string, []ansiSpan) {
	var out []byte
	var spans []ansiSpan
	runeCount := 0
	appendByte := func(b byte) {
		out = append(out, b)
		// Count runes when a UTF-8 leading byte is appended (invalid bytes count as one).
		if b&0xC0 != 0x80 {
			runeCount++
		}
	}
	i := 0
	for i < len(s) {
		if s[i] != 0x1b {
			appendByte(s[i])
			i++
			continue
		}
		// ESC at end: drop.
		if i+1 >= len(s) {
			break
		}
		next := s[i+1]
		switch {
		case next == '[': // CSI
			j := i + 2
			for j < len(s) && s[j] >= 0x30 && s[j] <= 0x3f {
				j++
			}
			for j < len(s) && s[j] >= 0x20 && s[j] <= 0x2f {
				j++
			}
			if j >= len(s) {
				// Incomplete sequence: ESC and '[' are dropped, parameters remain.
				for k := i + 2; k < len(s); k++ {
					appendByte(s[k])
				}
				i = len(s)
				continue
			}
			if s[j] >= 0x40 && s[j] <= 0x7e {
				if s[j] == 'm' {
					spans = append(spans, ansiSpan{pos: runeCount, code: s[i : j+1]})
				}
				i = j + 1
				continue
			}
			// Malformed byte inside CSI: drop ESC and '[' and continue at that byte.
			for k := i + 2; k < j; k++ {
				appendByte(s[k])
			}
			i = j
		case next == ']': // OSC, terminated by BEL or ESC \
			j := i + 2
			for j < len(s) {
				if s[j] == 0x07 {
					j++
					break
				}
				if s[j] == 0x1b && j+1 < len(s) && s[j+1] == '\\' {
					j += 2
					break
				}
				j++
			}
			i = j
		case next == '(' || next == ')' || next == '*' || next == '+' || next == '-' || next == '.' || next == '#':
			// Character set / designation sequences: ESC, intermediate, final.
			if i+2 < len(s) {
				i += 3
			} else {
				i = len(s)
			}
		default:
			// Two-byte escape sequence (or an intermediate plus a final byte).
			if next >= 0x20 && next <= 0x2f {
				if i+2 < len(s) {
					i += 3
				} else {
					i = len(s)
				}
			} else {
				i += 2
			}
		}
	}
	// Recompute rune positions reliably for spans: positions above are counted
	// at append time using leading bytes, which is correct for UTF-8 text.
	_ = utf8.RuneCountInString
	return string(out), spans
}
