package main

import (
	"fmt"
	"strings"
)

type action struct {
	name string
	arg  string
}

type parsedBinding struct {
	keys    []string
	actions []action
	raw     string
}

// Minimal early implementation; refined in a later pass.
func parseAndAddBind(o *options, spec string) error {
	if strings.TrimSpace(spec) == "" {
		return fmt.Errorf("key name required")
	}
	// Split bindings by commas that are not inside parentheses.
	parts := splitBindTopLevel(spec)
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			return fmt.Errorf("key name required")
		}
		colon := indexBindColon(part)
		if colon < 0 {
			return fmt.Errorf("bind action not specified: %s", part)
		}
		keyPart := strings.TrimSpace(part[:colon])
		actPart := strings.TrimSpace(part[colon+1:])
		if keyPart == "" {
			return fmt.Errorf("key name required")
		}
		if actPart == "" {
			return fmt.Errorf("bind action not specified: %s", part)
		}
		keys := strings.Split(keyPart, ",")
		// NOTE: keyPart cannot contain commas separating bindings because
		// the top-level split above is approximate; full parsing in bind
		// refinement will handle KEY1,KEY2:ACTION forms.
		_ = keys
		o.bindings = append(o.bindings, parsedBinding{keys: []string{keyPart}, actions: []action{{name: actPart}}, raw: part})
		o.bindSpecs = append(o.bindSpecs, part)
	}
	return nil
}

func splitBindTopLevel(s string) []string {
	var out []string
	depth := 0
	start := 0
	for i, r := range s {
		switch r {
		case '(':
			depth++
		case ')':
			if depth > 0 {
				depth--
			}
		case ',':
			if depth == 0 {
				// A comma may separate bindings or multiple keys before a
				// colon.  This early splitter is replaced by the full
				// binding parser later; treat every top-level comma as a
				// separator only if the preceding segment contains a colon.
				if strings.Contains(s[start:i], ":") {
					out = append(out, s[start:i])
					start = i + 1
				}
			}
		}
	}
	out = append(out, s[start:])
	return out
}

func indexBindColon(s string) int {
	depth := 0
	for i, r := range s {
		switch r {
		case '(':
			depth++
		case ')':
			if depth > 0 {
				depth--
			}
		case ':':
			if depth == 0 {
				return i
			}
		}
	}
	return -1
}
