// ---------- value parsing helpers ----------

func atoiErr(v string) (int, error) {
	n, err := strconv.Atoi(v)
	if err != nil {
		return 0, fmt.Errorf("not a valid integer: %s", v)
	}
	return n, nil
}

// parseIntMsg parses an integer; any Atoi failure yields msg.
func parseIntMsg(v, msg string) (int, error) {
	n, err := strconv.Atoi(v)
	if err != nil {
		return 0, fmt.Errorf("%s", msg)
	}
	return n, nil
}

func parseSize(v, name string, maxPercent float64) (sizeSpec, error) {
	if strings.HasSuffix(v, "%") {
		numStr := strings.TrimSuffix(v, "%")
		f, err := strconv.ParseFloat(numStr, 64)
		if err != nil {
			return sizeSpec{}, fmt.Errorf("not a valid number: %s", numStr)
		}
		if f < 0 {
			return sizeSpec{}, fmt.Errorf("%s must be non-negative", name)
		}
		if f > maxPercent {
			return sizeSpec{}, fmt.Errorf("%s too large (max: %v%%)", name, formatMax(maxPercent))
		}
		return sizeSpec{num: f, percent: true}, nil
	}
	if strings.Contains(v, ".") {
		return sizeSpec{}, fmt.Errorf("%s (without %%) must be a non-negative integer", name)
	}
	n, err := atoiErr(v)
	if err != nil {
		return sizeSpec{}, err
	}
	if n < 0 {
		return sizeSpec{}, fmt.Errorf("%s must be non-negative", name)
	}
	return sizeSpec{num: float64(n)}, nil
}

func formatMax(f float64) string {
	if f == float64(int64(f)) {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func parseHeight(v string) (sizeSpec, error) {
	auto := false
	if strings.HasPrefix(v, "~") {
		auto = true
		v = v[1:]
	}
	neg := false
	if strings.HasPrefix(v, "-") {
		if auto {
			return sizeSpec{}, fmt.Errorf("negative(-) height is not compatible with adaptive(~) height")
		}
		neg = true
		v = v[1:]
	}
	sz, err := parseSize(v, "height", 100)
	if err != nil {
		return sz, err
	}
	sz.auto = auto
	if neg {
		sz.num = -sz.num
	}
	return sz, nil
}

func parseMargins(v, name string) ([4]sizeSpec, error) {
	var out [4]sizeSpec
	parts := strings.Split(v, ",")
	if len(parts) > 4 {
		return out, fmt.Errorf("invalid %s: %s", name, v)
	}
	sizes := make([]sizeSpec, len(parts))
	for i, p := range parts {
		sz, err := parseSize(p, name, 49)
		if err != nil {
			return out, err
		}
		sizes[i] = sz
	}
	switch len(sizes) {
	case 1:
		out = [4]sizeSpec{sizes[0], sizes[0], sizes[0], sizes[0]}
	case 2:
		out = [4]sizeSpec{sizes[0], sizes[1], sizes[0], sizes[1]}
	case 3:
		out = [4]sizeSpec{sizes[0], sizes[1], sizes[2], sizes[1]}
	case 4:
		copy(out[:], sizes)
	}
	return out, nil
}

const borderStyleErr = "invalid border style (expected: rounded|sharp|bold|block|thinblock|double|horizontal|vertical|top|bottom|left|right|none)"

func parseBorderStyle(v string) (borderStyle, error) {
	switch v {
	case "none":
		return borderNoneStyle, nil
	case "rounded":
		return borderRounded, nil
	case "sharp":
		return borderSharp, nil
	case "bold":
		return borderBold, nil
	case "block":
		return borderBlock, nil
	case "thinblock":
		return borderThinBlock, nil
	case "double":
		return borderDouble, nil
	case "horizontal":
		return borderHorizontal, nil
	case "vertical":
		return borderVertical, nil
	case "top":
		return borderTop, nil
	case "bottom":
		return borderBottom, nil
	case "left":
		return borderLeft, nil
	case "right":
		return borderRight, nil
	case "line":
		return borderLine, nil
	}
	return borderNoneStyle, fmt.Errorf("%s", borderStyleErr)
}

func parseLabelPos(v string) (labelPos, error) {
	lp := labelPos{isSet: true}
	for _, tok := range strings.Split(v, ":") {
		switch {
		case strings.EqualFold(tok, "center"):
			lp.pos = 0
		case tok == "bottom":
			lp.bottom = true
		case tok == "top":
			lp.bottom = false
		default:
			n, err := atoiErr(tok)
			if err != nil {
				return lp, err
			}
			lp.pos = n
		}
	}
	return lp, nil
}

func (o *options) applyStyle(name string) error {
	if name == "full" || strings.HasPrefix(name, "full:") {
		style := borderRounded
		if strings.HasPrefix(name, "full:") {
			rest := name[len("full:"):]
			if rest != "" {
				s, err := parseBorderStyle(rest)
				if err != nil {
					return err
				}
				style = s
			}
		}
		o.stylePreset = "full"
		o.border = borderConfig{}
		o.listBorder = borderConfig{style: style, present: true}
		o.inputBorder = borderConfig{style: style, present: true}
		if o.previewSet || true {
			// Preview border is set via preview window default handling in
			// the full preset; keep the preview window's border style in
			// sync when it was not separately configured.
			o.previewWindow.border = style
			o.previewWindow.borderSet = true
		}
		o.headerBorder = borderConfig{}
		o.info = infoRight
		// no separator handling is via info style right
		return nil
	}
	if strings.EqualFold(name, "default") {
		o.stylePreset = "default"
		o.border = borderConfig{}
		o.listBorder = borderConfig{}
		o.inputBorder = borderConfig{}
		o.headerBorder = borderConfig{}
		o.footerBorder = borderConfig{}
		o.info = infoDefault
		o.noSeparator = false
		return nil
	}
	if strings.EqualFold(name, "minimal") {
		o.stylePreset = "minimal"
		o.border = borderConfig{}
		o.listBorder = borderConfig{}
		o.inputBorder = borderConfig{}
		o.headerBorder = borderConfig{}
		o.footerBorder = borderConfig{}
		o.info = infoDefault
		o.noSeparator = true
		return nil
	}
	return fmt.Errorf("unsupported style preset: %s", name)
}

func parseListen(v string, unsafe bool, hasVal bool) (listenConfig, error) {
	lc := listenConfig{present: true, unsafe: unsafe, hasVal: hasVal}
	if !hasVal {
		lc.port = 0
		return lc, nil
	}
	if strings.HasSuffix(v, ".sock") {
		lc.socket = v
		return lc, nil
	}
	// [ADDR:]PORT
	host := ""
	portStr := v
	if idx := strings.LastIndex(v, ":"); idx >= 0 {
		host = v[:idx]
		portStr = v[idx+1:]
	}
	// Validate host loosely: reject whitespace/colons beyond IPv6 brackets.
	port, err := strconv.Atoi(portStr)
	if err != nil || port < 0 || port > 65535 || strings.ContainsAny(v, " \t") {
		return lc, fmt.Errorf("invalid listen port: %s", v)
	}
	// Reject non-numeric extra characters (Atoi covered portStr) and odd hosts.
	if strings.Contains(host, ":") && !(strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]")) {
		// Allow plain IPv6 without brackets? The reference splits at the
		// last colon, so an unbracketed IPv6 host is accepted by us too.
	}
	lc.addr = host
	lc.port = port
	return lc, nil
}

func parseTmux(v string, hasVal bool) (tmuxConfig, error) {
	tc := tmuxConfig{present: true, position: "center", width: sizeSpec{num: 50, percent: true}, height: sizeSpec{num: 50, percent: true}}
	if !hasVal {
		return tc, nil
	}
	orig := v
	invalid := func() (tmuxConfig, error) {
		return tc, fmt.Errorf("invalid tmux option: %s (expected: [center|top|bottom|left|right][,SIZE[%%]][,SIZE[%%][,border-native]])", orig)
	}
	if v == "" {
		return invalid()
	}
	parts := strings.Split(v, ",")
	idx := 0
	if len(parts) > 0 {
		switch parts[0] {
		case "center", "top", "bottom", "left", "right":
			tc.position = parts[0]
			idx = 1
		}
	}
	var sizes []sizeSpec
	for ; idx < len(parts); idx++ {
		p := parts[idx]
		if p == "border-native" {
			if tc.borderNative || idx != len(parts)-1 {
				return invalid()
			}
			tc.borderNative = true
			continue
		}
		sz, err := parseSize(p, "tmux", 100)
		if err != nil {
			return invalid()
		}
		sizes = append(sizes, sz)
		if len(sizes) > 2 {
			return invalid()
		}
	}
	switch tc.position {
	case "center":
		if len(sizes) == 1 {
			tc.width, tc.height = sizes[0], sizes[0]
		} else if len(sizes) == 2 {
			tc.width, tc.height = sizes[0], sizes[1]
		}
	case "left", "right":
		if len(sizes) == 1 {
			tc.width = sizes[0]
			tc.height = sizeSpec{num: 100, percent: true}
		} else if len(sizes) == 2 {
			tc.width, tc.height = sizes[0], sizes[1]
		}
	case "top", "bottom":
		if len(sizes) == 1 {
			tc.height = sizes[0]
			tc.width = sizeSpec{num: 100, percent: true}
		} else if len(sizes) == 2 {
			tc.width, tc.height = sizes[0], sizes[1]
		}
	}
	return tc, nil
}

// ---------- argument iterator ----------

type argIter struct {
	args []string
	i    int
}

func splitLongArg(arg string) (name, val string, hasVal bool) {
	if idx := strings.Index(arg, "="); idx >= 0 {
		return arg[:idx], arg[idx+1:], true
	}
	return arg, "", false
}

func (it *argIter) nextRequired(hasVal bool, val string, msg string) (string, error) {
	if hasVal {
		return val, nil
	}
	if it.i+1 >= len(it.args) {
		return "", fmt.Errorf("%s", msg)
	}
	it.i++
	return it.args[it.i], nil
}

func ensureNoVal(name, val string, hasVal bool) error {
	if hasVal {
		return fmt.Errorf("unexpected value for %s: %s", name, val)
	}
	return nil
}

// optionalValue returns (value, present).
func (it *argIter) optionalValue(hasVal bool, val string, intOnly bool) (string, bool) {
	if hasVal {
		return val, true
	}
	if it.i+1 < len(it.args) {
		next := it.args[it.i+1]
		if next != "" {
			if intOnly {
				if next[0] >= '0' && next[0] <= '9' {
					it.i++
					return next, true
				}
			} else if next[0] != '-' && next[0] != '+' {
				it.i++
				return next, true
			}
		}
	}
	return "", false
}

func parseOptions(args []string, o *options) error {
	it := &argIter{args: args}
	for ; it.i < len(args); it.i++ {
		arg := args[it.i]
		if arg == "--" {
			continue
		}
		if !strings.HasPrefix(arg, "--") {
			if err := parseShortOrUnknown(arg, it, o); err != nil {
				return err
			}
			continue
		}
		name, val, hasVal := splitLongArg(arg)
		if err := parseLong(name, val, hasVal, it, o); err != nil {
			return err
		}
	}
	return nil
}

func parseShortOrUnknown(arg string, it *argIter, o *options) error {
	// Short options with attached values.
	for _, pre := range []string{"-d", "-n", "-q", "-f"} {
		if strings.HasPrefix(arg, pre) && arg != pre {
			val := arg[len(pre):]
			switch pre {
			case "-d":
				return setDelimiter(o, val)
			case "-n":
				return setNth(o, val)
			case "-q":
				o.query = val
				return nil
			case "-f":
				v := val
				o.filter = &v
				return nil
			}
		}
	}
	if strings.HasPrefix(arg, "-m") && arg != "-m" {
		n, err := atoiErr(arg[2:])
		if err != nil {
			return err
		}
		o.multi = n
		return nil
	}
	switch arg {
	case "-e":
		o.fuzzy = false
	case "+e":
		o.fuzzy = true
	case "-x":
		o.extended = true
	case "+x":
		o.extended = false
	case "-i":
		o.caseMode = caseIgnore
	case "+i":
		o.caseMode = caseRespect
	case "-s":
		o.sort = true
	case "+s":
		o.sort = false
	case "-m":
		o.multi = -1
	case "+m":
		o.multi = 0
	case "+c":
		o.clearOnExit = false
	case "-0":
		o.exit0 = true
	case "+0":
		o.exit0 = false
	case "-1":
		o.select1 = true
	case "+1":
		o.select1 = false
	case "+2":
		// Accepted by the reference; no observable effect found in
		// non-interactive probing.
		_ = o
	case "-h":
		o.special = specialHelp
	case "-d":
		v, err := it.nextRequired(false, "", "delimiter required")
		if err != nil {
			return err
		}
		return setDelimiter(o, v)
	case "-n":
		v, err := it.nextRequired(false, "", "nth expression required")
		if err != nil {
			return err
		}
		return setNth(o, v)
	case "-q":
		v, err := it.nextRequired(false, "", "query string required")
		if err != nil {
			return err
		}
		o.query = v
	case "-f":
		v, err := it.nextRequired(false, "", "query string required")
		if err != nil {
			return err
		}
		o.filter = &v
	default:
		return fmt.Errorf("unknown option: %s", arg)
	}
	return nil
}

func setDelimiter(o *options, v string) error {
	o.delim = parseDelimiter(v)
	o.delimSet = true
	return nil
}

func setNth(o *options, v string) error {
	ranges, err := parseRangeList(v)
	if err != nil {
		return err
	}
	o.nth = ranges
	o.nthStr = v
	return nil
}

func boolOpt(it *argIter, name, val string, hasVal bool) error {
	return ensureNoVal(name, val, hasVal)
}
GO
gofmt -w options.go
"}

