func parseSize(v, name string, maxPercent float64) (sizeSpec, error) {
	if strings.HasSuffix(v, "%") {
		numStr := strings.TrimSuffix(v, "%")
		f, err := strconv.ParseFloat(numStr, 64)
		if err != nil {
			return sizeSpec{}, fmt.Errorf("not a valid number: %s", numStr)
