}

var ansiColorNames = map[string]int{
	"black": 0, "red": 1, "green": 2, "yellow": 3, "blue": 4, "magenta": 5, "cyan": 6, "white": 7,
	"bright-black": 8, "gray": 8, "grey": 8, "bright-red": 9, "bright-green": 10,
	"bright-yellow": 11, "bright-blue": 12, "bright-magenta": 13, "bright-cyan": 14, "bright-white": 15,
}

func parseANSIColor(tok string) (colorValue, bool) {
	if tok == "-1" {
		return colorValue{kind: colorDefault, code: -1}, true
	}
	if code, ok := ansiColorNames[tok]; ok {
		return colorValue{kind: colorANSI, code: code}, true
	}
	if strings.HasPrefix(tok, "#") {
		if len(tok) != 7 {
			return colorValue{}, false
		}
		n, err := strconv.ParseUint(tok[1:], 16, 32)
		if err != nil {
			return colorValue{}, false
		}
		return colorValue{kind: colorRGB, r: int(n >> 16 & 0xff), g: int(n >> 8 & 0xff), b: int(n & 0xff)}, true
	}
	if n, err := strconv.Atoi(tok); err == nil {
		if n >= 0 && n <= 255 {
			return colorValue{kind: colorANSI, code: n}, true
		}
		return colorValue{}, false
	}
	return colorValue{}, false
}

func applyColorSpec(t *theme, spec string) error {
	invalid := func() error { return fmt.Errorf("invalid color specification: %s", spec) }
	entries := strings.FieldsFunc(spec, func(r rune) bool {
		return r == ',' || r == ' ' || r == '\t' || r == '\n' || r == '\r'
	})
	for _, entry := range entries {
		switch entry {
		case "dark", "light", "base16", "bw":
			t.base = entry
			continue
		case "16":
			t.base = "base16"
			continue
		}
		parts := strings.Split(entry, ":")
		if len(parts) < 2 {
			return invalid()
		}
		name, ok := colorNames[parts[0]]
		if !ok {
			return invalid()
		}
		var cs colorSpec
		// Start from existing spec for this name if present, so separate
		// entries can add attributes; a "regular" token resets attributes.
		if existing, ok := t.colors[name]; ok {
			cs = existing
		}
		seenAny := false
		for _, tok := range parts[1:] {
			if tok == "" {
				continue
			}
			seenAny = true
			switch tok {
			case "regular":
				cs.attrs = 0
				cs.underline = 0
			case "strip":
				cs.attrs |= attrStrip
			case "bold":
				cs.attrs |= attrBold
			case "dim":
				cs.attrs |= attrDim
			case "italic":
				cs.attrs |= attrItalic
			case "reverse":
				cs.attrs |= attrReverse
			case "strikethrough":
				cs.attrs |= attrStrikethrough
			case "underline":
				cs.underline = 1
			case "underline-double":
				cs.underline = 2
			case "underline-curly":
				cs.underline = 3
			case "underline-dotted":
				cs.underline = 4
			case "underline-dashed":
				cs.underline = 5
			default:
				cv, ok := parseANSIColor(tok)
				if !ok {
					return invalid()
				}
				cs.color = cv
				cs.hasColor = true
				cs.attrs &^= attrStrip
			}
		}
		if !seenAny {
			// "name:" with an empty remainder: treat as default color.
			cs.color = colorValue{kind: colorDefault, code: -1}
			cs.hasColor = true
		}
		t.colors[name] = cs
	}
	return nil
}
