package main

import (
	"os"
	"strings"
)

type historyState struct {
	path  string
	lines []string
	// Index into lines for prev/next navigation; len(lines) means "current".
	pos int
	// Query saved when navigation started (fzf returns to it past newest).
	saved string
	savedSet bool
}

func loadHistory(path string) (*historyState, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			f, cerr := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
			if cerr != nil {
				return nil, cerr
			}
			_ = f.Close()
			data = nil
		} else {
			return nil, err
		}
	}
	var lines []string
	if len(data) > 0 {
		text := strings.ReplaceAll(string(data), "\r\n", "\n")
		lines = strings.Split(text, "\n")
		if lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
	}
	return &historyState{path: path, lines: lines, pos: len(lines)}, nil
}

func (h *historyState) append(query string, max int) {
	if h == nil || query == "" {
		return
	}
	lines := append(append([]string{}, h.lines...), query)
	if max > 0 && len(lines) > max {
		lines = lines[len(lines)-max:]
	}
	_ = os.WriteFile(h.path, []byte(strings.Join(lines, "\n")+"\n"), 0600)
	h.lines = lines
}
