const previewWindowErrSuffix = ""

func splitTopLevelCommas(s string) []string {
	var out []string
	depth := 0
	start := 0
	for i, r := range s {
		switch r {
		case '(':
			depth++
		case ')':
			if depth > 0 {
				depth--
			}
		case ',':
			if depth == 0 {
				out = append(out, s[start:i])
				start = i + 1
			}
		}
	}
	out = append(out, s[start:])
	return out
}

func parsePreviewWindowValue(v string, cur previewWindow) (previewWindow, error) {
	orig := v
	invalid := func() (previewWindow, error) {
		return cur, fmt.Errorf("invalid preview window layout: %s", orig)
	}
	if v == "" {
		return invalid()
	}
	// Alternative layout form ends with ",<NEGATIVE?(ALT)" -- represented as a
	// top-level token starting with '<'.
	base := cur
	base.alt = nil
	base.altThreshold = 0
	layout := base.previewLayout
