	if v == "" {
		return invalid()
	}
	// Alternative layout form ends with ",<NEGATIVE?(ALT)" -- represented as a
	// top-level token starting with '<'.
	base := cur
	base.alt = nil
	base.altThreshold = 0
	layout := base.previewLayout
	// A fresh --preview-window resets to defaults before applying tokens?
	// fzf parses it over the current defaults; use the current layout as a
	// starting point when only some attributes are given.
	toks := splitTopLevelCommas(v)
	for _, tok := range toks {
		if tok == "" {
			continue
		}
		if strings.HasPrefix(tok, "<") {
			// <THRESHOLD(ALTERNATIVE)
			open := strings.Index(tok, "(")
			if open < 0 || !strings.HasSuffix(tok, ")") {
				return invalid()
			}
			threshStr := tok[1:open]
			thresh, err := strconv.Atoi(threshStr)
			if err != nil {
				return invalid()
			}
			altStr := tok[open+1 : len(tok)-1]
			altCur := previewWindow{previewLayout: layout}
			altParsed, err := parsePreviewWindowValue(altStr, altCur)
			if err != nil {
				return invalid()
			}
			altLayout := altParsed.previewLayout
			base.alt = &altLayout
			base.altThreshold = thresh
			continue
		}
		switch tok {
		case "right":
			layout.position = previewRight
		case "left":
			layout.position = previewLeft
		case "up", "top":
			layout.position = previewUp
		case "down", "bottom":
			layout.position = previewDown
		case "wrap":
			layout.wrap = true
		case "nowrap":
			layout.wrap = false
		case "cycle":
			layout.cycle = true
		case "nocycle":
			layout.cycle = false
		case "follow":
			layout.follow = true
		case "nofollow":
			layout.follow = false
		case "info":
			layout.info = true
		case "noinfo":
			layout.info = false
		case "hidden":
			layout.hidden = true
		case "nohidden":
			layout.hidden = false
		case "default":
			layout = defaultPreviewWindow().previewLayout
		default:
			if strings.HasPrefix(tok, "border-") {
				st, err := parseBorderStyle(strings.TrimPrefix(tok, "border-"))
				if err != nil {
					return invalid()
				}
				layout.border = st
				layout.borderSet = true
			} else if strings.HasPrefix(tok, "+") {
				// Scroll expression; validate roughly: +SCROLL[OFFSETS][/DENOM]
				if !validScrollExpr(tok) {
					return invalid()
				}
				layout.scroll = tok
			} else if strings.HasPrefix(tok, "~") {
				n, err := strconv.Atoi(tok[1:])
				if err != nil || n < 0 {
					return invalid()
				}
				layout.headerLines = n
			} else {
				// Size token.
				sz, err := parseSize(tok, "preview window", 100)
				if err != nil {
					return invalid()
				}
				layout.size = sz
			}
		}
	}
	base.previewLayout = layout
	return base, nil
}

func validScrollExpr(s string) bool {
	// +EXPR where EXPR is a sequence of +N/-N/{...} optionally /DENOM,
	// or a plain number/placeholder.  Keep validation permissive: reject
	// only characters that can never appear.
	if len(s) < 2 {
		return false
	}
	for _, r := range s {
		if (r >= '0' && r <= '9') || strings.ContainsRune("+-/{}.,", r) {
			continue
		}
		return false
	}
	return true
}
