		if err != nil { return err }
		o.query = v
	case "--select-1":
		if err := noVal(); err != nil { return err }
		o.select1 = true
	case "--no-select-1":
		if err := noVal(); err != nil { return err }
		o.select1 = false
	case "--exit-0":
		if err := noVal(); err != nil { return err }
		o.exit0 = true
	case "--no-exit-0":
		if err := noVal(); err != nil { return err }
		o.exit0 = false
	case "--filter":
		v, err := req("query string required")
		if err != nil { return err }
		o.filter = &v
	case "--print-query":
		if err := noVal(); err != nil { return err }
		o.printQuery = true
	case "--no-print-query":
		if err := noVal(); err != nil { return err }
		o.printQuery = false
	case "--expect":
		v, err := req("key names required")
		if err != nil { return err }
		if v == "" {
			return fmt.Errorf("key names required")
		}
		if o.expect == nil {
			o.expect = map[string]bool{}
		}
		for _, k := range strings.Split(v, ",") {
			canon, err := canonicalKeyName(k)
			if err != nil { return err }
			o.expect[canon] = true
		}
		o.expectSet = true
	case "--no-expect":
		if err := noVal(); err != nil { return err }
		o.expect = nil
		o.expectSet = false
	case "--no-clear":
		if err := noVal(); err != nil { return err }
		o.clearOnExit = false
	case "--clear":
		if err := noVal(); err != nil { return err }
		o.clearOnExit = true
	// ----- BIND -----
	case "--bind":
		v, err := req("bind expression required")
		if err != nil { return err }
		return parseAndAddBind(o, v)
	// ----- ADVANCED -----
	case "--with-shell":
		v, err := req("shell command and flags required")
		if err != nil { return err }
		o.withShell = v
		o.withShellSet = true
	case "--listen", "--listen-unsafe":
		unsafe := name == "--listen-unsafe"
		v, present := optVal(false)
		lc, err := parseListen(v, unsafe, present)
		if err != nil { return err }
		o.listen = lc
	case "--no-listen":
		if err := noVal(); err != nil { return err }
		o.listen = listenConfig{}
	case "--no-listen-unsafe":
		if err := noVal(); err != nil { return err }
		o.listen = listenConfig{}
	// ----- WALKER -----
	case "--walker":
		v, err := req("walker options required [file][,dir][,follow][,hidden]")
		if err != nil { return err }
		return setWalker(o, v)
	case "--walker-root":
		return setWalkerRoot(o, val, hasVal, it)
	case "--walker-skip":
		v, err := req("directory names to ignore required")
		if err != nil { return err }
		if v == "" {
			o.walkerSkip = nil
		} else {
			o.walkerSkip = strings.Split(v, ",")
		}
	// ----- HISTORY -----
	case "--history":
		v, err := req("history file path required")
		if err != nil { return err }
		// The reference opens/loads the file at this point.
		st, herr := loadHistory(v)
		if herr != nil {
			return fmt.Errorf("invalid history file: %s", herr.Error())
		}
		o.historyFile = v
		o.historySet = true
		o.history = st
	case "--no-history":
		if err := noVal(); err != nil { return err }
		o.historyFile = ""
		o.historySet = false
		o.history = nil
	case "--history-size":
		v, err := req("history max size required")
		if err != nil { return err }
		n, err := parseIntMsg(v, "history max size required")
		if err != nil { return err }
		if n <= 0 { return fmt.Errorf("history max must be a positive integer") }
		o.historySize = n
	// ----- SHELL INTEGRATION / HELP -----
	case "--bash":
		if err := noVal(); err != nil { return err }
		o.special = specialBash
	case "--zsh":
		if err := noVal(); err != nil { return err }
		o.special = specialZsh
	case "--fish":
		if err := noVal(); err != nil { return err }
		o.special = specialFish
	case "--version":
		if err := noVal(); err != nil { return err }
		o.special = specialVersion
	case "--help":
		if err := noVal(); err != nil { return err }
		o.special = specialHelp
	case "--man":
		if err := noVal(); err != nil { return err }
		o.special = specialMan
	// ----- OTHERS -----
	case "--no-mouse":
		if err := noVal(); err != nil { return err }
		o.mouse = false
	case "--no-unicode":
		if err := noVal(); err != nil { return err }
		o.unicode = false
	case "--unicode":
		if err := noVal(); err != nil { return err }
		o.unicode = true
	case "--ambidouble":
		if err := noVal(); err != nil { return err }
		o.ambidouble = true
	case "--no-ambidouble":
		if err := noVal(); err != nil { return err }
		o.ambidouble = false
	default:
		return fmt.Errorf("unknown option: %s", name)
	}
	return nil
}

func parseFreeze(req func(string) (string, error), dest *int) error {
	v, err := req("number of fields required")
	if err != nil { return err }
	n, err := parseIntMsg(v, "number of fields required")
	if err != nil { return err }
	if n < 0 {
		return fmt.Errorf("number of fields to freeze must be a non-negative integer")
	}
	*dest = n
	return nil
}

func setBorderOpt(cfg *borderConfig, val string, hasVal bool, it *argIter, allowLine bool) error {
	v, present := it.optionalValue(hasVal, val, false)
	if !present {
		*cfg = borderConfig{style: borderRounded, present: true}
		return nil
	}
	st, err := parseBorderStyle(v)
	if err != nil { return err }
	if st == borderLine && !allowLine {
		return fmt.Errorf("list border cannot be 'line'")
	}
	*cfg = borderConfig{style: st, present: true}
	if st == borderNoneStyle {
		cfg.present = true
	}
	return nil
}

func setPreviewBorder(o *options, val string, hasVal bool, it *argIter) error {
	v, present := it.optionalValue(hasVal, val, false)
	if !present {
		o.previewWindow.border = borderRounded
		o.previewWindow.borderSet = true
		return nil
	}
	st, err := parseBorderStyle(v)
	if err != nil { return err }
	o.previewWindow.border = st
	o.previewWindow.borderSet = true
	return nil
}

func setInfo(o *options, v string) error {
	const msg = "invalid info style (expected: default|right|hidden|inline[-right][:PREFIX])"
	switch {
	case v == "default":
		o.info = infoDefault
	case v == "right":
		o.info = infoRight
	case v == "hidden":
		o.info = infoHidden
	case v == "inline":
		o.info = infoInline
		o.infoPrefix = ""
	case strings.HasPrefix(v, "inline:"):
		o.info = infoInline
		o.infoPrefix = v[len("inline:"):]
	case v == "inline-right":
		o.info = infoInlineRight
		o.infoPrefix = ""
	case strings.HasPrefix(v, "inline-right:"):
		o.info = infoInlineRight
		o.infoPrefix = v[len("inline-right:"):]
	default:
		return fmt.Errorf("%s", msg)
	}
	return nil
}

func setWalker(o *options, v string) error {
	if strings.TrimSpace(v) == "" {
		return fmt.Errorf("at least one of 'file' or 'dir' should be specified")
	}
	o.walkerFile, o.walkerDir, o.walkerFollow, o.walkerHidden = false, false, false, false
	for _, part := range strings.Split(v, ",") {
		switch part {
		case "file":
			o.walkerFile = true
		case "dir":
			o.walkerDir = true
		case "follow":
			o.walkerFollow = true
		case "hidden":
			o.walkerHidden = true
		default:
			return fmt.Errorf("invalid walker option: %s", part)
		}
	}
	if !o.walkerFile && !o.walkerDir {
		return fmt.Errorf("at least one of 'file' or 'dir' should be specified")
	}
	return nil
}

func setWalkerRoot(o *options, val string, hasVal bool, it *argIter) error {
	var roots []string
	if hasVal {
		roots = append(roots, val)
	}
	// Consume following arguments that are existing directories.
	for it.i+1 < len(it.args) {
		next := it.args[it.i+1]
		if st, err := os.Stat(next); err == nil && st.IsDir() {
			it.i++
			roots = append(roots, next)
			continue
		}
		break
	}
	if len(roots) == 0 {
		return fmt.Errorf("no directory specified")
	}
	if !o.walkerRootsSet {
		o.walkerRoots = roots
		o.walkerRootsSet = true
	} else {
		o.walkerRoots = append(o.walkerRoots, roots...)
	}
	return nil
}

