var eventNames = []string{
	"start", "load", "resize", "result", "change", "focus", "multi", "one", "zero",
	"backward-eof", "jump", "jump-cancel", "click-header", "click-footer",
}

var eventNameSet = func() map[string]bool {
	m := map[string]bool{}
	for _, e := range eventNames {
		m[e] = true
	}
	return m
}()

func isEventName(s string) bool {
	return eventNameSet[strings.ToLower(s)]
}

// canonicalKeyName validates a key or event name used in --expect / --bind
// and returns the name fzf prints / matches internally.
func canonicalKeyName(s string) (string, error) {
	// Any single character.
	if r := []rune(s); len(r) == 1 {
		if r[0] == ' ' {
			return "space", nil
		}
		return s, nil
	}
	lower := strings.ToLower(s)
	// alt-<single character> is case-sensitive in the character.
	if strings.HasPrefix(lower, "alt-") {
		rest := s[4:]
		if r := []rune(rest); len(r) == 1 {
			return "alt-" + rest, nil
		}
	}
	// Synonyms for the base key suffix after any modifiers.
	normalize := func(name string) string {
		// Split modifiers from the base by the last '-' that is not part of
		// known multi-word bases; handle common synonyms by suffix swaps.
		replacements := []struct{ from, to string }{
			{"return", "enter"},
			{"ctrl-m", "enter"},
			{"bspace", "backspace"},
			{"bs", "backspace"},
			{"btab", "shift-tab"},
			{"del", "delete"},
			{"pgup", "page-up"},
			{"pgdn", "page-down"},
			{"ctrl-6", "ctrl-^"},
			{"ctrl-_", "ctrl-/"},
		}
		for _, r := range replacements {
			if name == r.from {
				return r.to
			}
			if strings.HasSuffix(name, "-"+r.from) {
				return name[:len(name)-len(r.from)] + r.to
			}
		}
		return name
	}
	name := normalize(lower)
	// ctrl-alt-h == ctrl-alt-backspace on non-Windows.
	if name == "ctrl-alt-h" {
		name = "ctrl-alt-backspace"
	}
	if validKeyNames[name] || eventNameSet[name] {
		return name, nil
	}
	return "", fmt.Errorf("unsupported key: %s", s)
}

var validKeyNames = buildValidKeyNames()

func buildValidKeyNames() map[string]bool {
	m := map[string]bool{}
	add := func(s string) { m[s] = true }
	plain := []string{
		"enter", "space", "backspace", "tab", "shift-tab", "esc", "delete",
		"up", "down", "left", "right", "home", "end", "insert", "page-up", "page-down",
		"left-click", "right-click", "double-click", "scroll-up", "scroll-down",
		"preview-scroll-up", "preview-scroll-down",
		"shift-left-click", "shift-right-click", "shift-scroll-up", "shift-scroll-down",
	}
	for _, p := range plain {
		add(p)
	}
	for i := 1; i <= 12; i++ {
		add(fmt.Sprintf("f%d", i))
	}
	for c := 'a'; c <= 'z'; c++ {
		add("ctrl-" + string(c))
		add("ctrl-alt-" + string(c))
	}
	for _, s := range []string{"ctrl-space", "ctrl-delete", "ctrl-\\", "ctrl-]", "ctrl-^", "ctrl-/"} {
		add(s)
	}
	nav := []string{"up", "down", "left", "right", "home", "end", "delete", "page-up", "page-down"}
	// alt- navigation and special keys
	for _, n := range append(append([]string{}, nav...), "backspace", "enter", "space") {
		add("alt-" + n)
	}
	for _, prefix := range []string{"ctrl", "shift", "alt-shift", "ctrl-alt", "ctrl-shift", "ctrl-alt-shift"} {
		for _, n := range nav {
			add(prefix + "-" + n)
		}
	}
	// Backspace is a valid base only for these modifier combos in the list.
	add("ctrl-backspace")
	add("ctrl-alt-backspace")
	add("alt-backspace")
	return m
}
