package main

import (
	"bufio"
	"io"
	"strings"
)

// readRawItems reads all items from r, separated by \n or \0 (read0).
// A trailing separator does not produce an extra empty item; data ending
// without a separator yields a final item.  Empty input yields no items.
func readRawItems(r io.Reader, read0 bool) []string {
	data, _ := io.ReadAll(r)
	if len(data) == 0 {
		return nil
	}
	sep := byte('\n')
	if read0 {
		sep = 0
	}
	parts := strings.Split(string(data), string([]byte{sep}))
	// Split returns a trailing "" when data ends with the separator (and
	// also for genuine final empty items if there are two separators in a
	// row at the end, e.g. "a\n\n" -> ["a","",""] of which the last is the
	// terminator artifact while the middle "" is a real item).  Dropping
	// exactly one trailing artifact handles both.
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	return parts
}

// streamItems invokes fn for every complete item as it arrives; used in
// interactive mode to show items before EOF.  It returns the leftover
// handling by calling fn for a final unterminated item at EOF.
func streamItems(r io.Reader, read0 bool, fn func(string)) {
	br := bufio.NewReaderSize(r, 64*1024)
	sep := byte('\n')
	if read0 {
		sep = 0
	}
	var buf []byte
	for {
		b, err := br.ReadBytes(sep)
		if len(b) > 0 {
			terminated := b[len(b)-1] == sep
			piece := b
			if terminated {
				piece = b[:len(b)-1]
			}
			buf = append(buf, piece...)
			if terminated {
				fn(string(buf))
				buf = nil
			}
		}
		if err != nil {
			if len(buf) > 0 {
				fn(string(buf))
			}
			return
		}
	}
}

func buildItems(rawLines []string, o *options) []*item {
	var items []*item
	idx := 0
	remainingHeader := o.headerLines
	// With --tail we still assign ordinal indices to every line first.
	type pending struct {
		raw string
		idx int
	}
	var pend []pending
	for _, raw := range rawLines {
		if remainingHeader > 0 {
			remainingHeader--
			continue
		}
		pend = append(pend, pending{raw: raw, idx: idx})
		idx++
	}
	if o.tail > 0 && len(pend) > o.tail {
		pend = pend[len(pend)-o.tail:]
	}
	for _, p := range pend {
		orig := p.raw
		var spans []ansiSpan
		if o.ansi {
			orig, spans = stripAnsi(p.raw)
		}
		text := orig
		if o.withNth != nil {
			text = transformBySpec(orig, p.idx, o.delim, o.withNth)
		}
		items = append(items, &item{orig: orig, rawOrig: p.raw, text: text, index: p.idx, ansiColors: spans})
	}
	return items
