func (o *options) transformForOutput(it *item) string {
	if o.acceptNth == nil {
		return it.orig
	}
	return transformBySpec(it.orig, it.index, o.delim, o.acceptNth)
}

func (o *options) matchItem(it *item, p *pattern) itemMatch {
	segs := segmentsForText(it.text, o.delim, o.nth)
	return p.match(segs, !o.literal, scoringFor(o.scheme))
}

func (o *options) buildPatternFor(query string) *pattern {
	forward := true
	for _, c := range o.criteria {
		if c == critEnd {
			forward = false
		}
	}
	return buildPattern(query, o.caseMode, o.fuzzy, o.extended, forward, o.algoV1)
}

func (o *options) filterItems(items []*item, p *pattern, forceSortForTac bool) []*result {
	// Traversal order: forward normally, reversed with --tac.
	ordered := make([]*item, len(items))
	copy(ordered, items)
	if o.tac {
		for i, j := 0, len(ordered)-1; i < j; i, j = i+1, j-1 {
			ordered[i], ordered[j] = ordered[j], ordered[i]
		}
