	var results []*result
	for _, it := range ordered {
		m := o.matchItem(it, p)
		if m.ok {
			results = append(results, &result{item: it, score: m.score, offsets: m.offsets})
		}
	}
	doSort := o.sort && p.sortable
	if o.tac && p.sortable && forceSortForTac {
		doSort = true
	}
	if !p.sortable {
		doSort = false
	}
	if doSort {
		// Sorting is stable with the implicit index criterion making the
		// order deterministic; the input slice order for tac is reversed
		// but the index criterion itself accounts for tac, so sort the
		// results in their original item order to let index keys decide.
		sortResults(results, o.criteria, o.tac)
	}
	return results
}
