//go:embed assets/help.txt
var helpText string

//go:embed assets/bash.txt
var bashScript string

//go:embed assets/zsh.txt
var zshScript string

//go:embed assets/fish.txt
var fishScript string

//go:embed man/man1/fzf.1
var manPage []byte

const versionString = "0.68.0 (89eaa04a)\n"

func main() {
	os.Exit(run())
}

func exitError(msg string) int {
	fmt.Fprintln(os.Stderr, msg)
	return 2
}

func parseOptsSource(args []string, o *options, prefix string) (int, bool) {
	if err := parseOptions(args, o); err != nil {
		fmt.Fprintf(os.Stderr, "%s%s\n", prefix, err.Error())
		return 2, false
	}
	return 0, true
}

func run() int {
	o := defaultOptions()
	// 1. Options file.
	if path, ok := os.LookupEnv("FZF_DEFAULT_OPTS_FILE"); ok && path != "" {
		data, err := os.ReadFile(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "$FZF_DEFAULT_OPTS_FILE: %s\n", err.Error())
			return 2
		}
		args, err := parseShellWords(string(data))
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: %s\n", path, err.Error())
			return 2
		}
		if code, ok := parseOptsSource(args, o, path+": "); !ok {
			return code
		}
	}
	// 2. $FZF_DEFAULT_OPTS
	if val, ok := os.LookupEnv("FZF_DEFAULT_OPTS"); ok && val != "" {
		args, err := parseShellWords(val)
		if err != nil {
			fmt.Fprintf(os.Stderr, "$FZF_DEFAULT_OPTS: %s\n", err.Error())
			return 2
		}
		if code, ok := parseOptsSource(args, o, "$FZF_DEFAULT_OPTS: "); !ok {
			return code
		}
	}
	// 3. Command line.
	if code, ok := parseOptsSource(os.Args[1:], o, ""); !ok {
		return code
	}
	switch o.special {
	case specialVersion:
		fmt.Fprint(os.Stdout, versionString)
		return 0
	case specialHelp:
		fmt.Fprint(os.Stdout, helpText)
		return 0
	case specialBash:
		fmt.Fprint(os.Stdout, bashScript)
		return 0
	case specialZsh:
		fmt.Fprint(os.Stdout, zshScript)
		return 0
	case specialFish:
		fmt.Fprint(os.Stdout, fishScript)
		return 0
	case specialMan:
		return printManPage()
	}

	stdinIsTTY := isTerminalFD(int(os.Stdin.Fd()))
	applyAutoScheme(o, stdinIsTTY)

	if o.filter != nil {
		return runFilter(o, stdinIsTTY)
	}
	return runInteractive(o, stdinIsTTY)
}

func applyAutoScheme(o *options, stdinIsTTY bool) {
	if !stdinIsTTY || o.schemeSet {
		return
	}
	// Only when the input comes from the walker / default command and no
	// reload/transform action is bound to `start`.
	for _, b := range o.bindings {
		for _, k := range b.keys {
			if strings.EqualFold(k, "start") {
				for _, a := range b.actions {
					if strings.HasPrefix(a.name, "reload") || strings.HasPrefix(a.name, "transform") || strings.HasPrefix(a.name, "bg-transform") {
						return
					}
				}
			}
		}
	}
	o.scheme = "path"
}

var executableName = "fzf"

func printManPage() int {
	f, err := os.CreateTemp("", "fzf-temp-")
	if err != nil {
		_, _ = os.Stdout.Write(manPage)
		return 0
	}
	name := f.Name()
	defer os.Remove(name)
	if _, err := f.Write(manPage); err != nil {
		_ = f.Close()
		_, _ = os.Stdout.Write(manPage)
		return 0
	}
	_ = f.Close()
	cmd := exec.Command("man", name)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	// The reference discards man's stderr and falls back to printing the
	// raw page when man fails for any reason.
	if err := cmd.Run(); err != nil {
		_, _ = os.Stdout.Write(manPage)
	}
	return 0
}

func outputSeparator(o *options) string {
	if o.print0 {
		return "\x00"
	}
	return "\n"
}

func printAcceptOutput(o *options, query string, includeExpect bool, expectKey string, selected []*item) {
	sep := outputSeparator(o)
	var b strings.Builder
	if o.printQuery {
		b.WriteString(query)
		b.WriteString(sep)
	}
	if includeExpect && o.expectSet {
		b.WriteString(expectKey)
		b.WriteString(sep)
	}
	for _, it := range selected {
		b.WriteString(o.transformForOutput(it))
		b.WriteString(sep)
	}
	fmt.Fprint(os.Stdout, b.String())
}

func runFilter(o *options, stdinIsTTY bool) int {
	raw := readAllInput(o, stdinIsTTY)
	items := buildItems(raw, o)
	p := o.buildPatternFor(*o.filter)
	results := o.filterItems(items, p, true)
	sep := outputSeparator(o)
	if o.printQuery {
		fmt.Fprint(os.Stdout, *o.filter+sep)
	}
	for _, r := range results {
		fmt.Fprint(os.Stdout, o.transformForOutput(r.item)+sep)
	}
	if len(results) == 0 {
		return 1
	}
	return 0
}
