package main

import (
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"unsafe"
)

func isTerminalFD(fd int) bool {
	var termios [64]byte
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5401) /* TCGETS */, uintptr(unsafe.Pointer(&termios[0])), 0, 0, 0)
	return errno == 0
}

func readAllInput(o *options, stdinIsTTY bool) []string {
	ch, wait := startInput(o, stdinIsTTY)
	var out []string
	for s := range ch {
		out = append(out, s)
	}
	if wait != nil {
		wait()
	}
	return out
}

// startInput starts producing raw item strings on a channel.  The returned
// wait function (if any) waits for an external command to finish.
func startInput(o *options, stdinIsTTY bool) (chan string, func()) {
	ch := make(chan string, 1024)
	if !stdinIsTTY {
		go func() {
			streamItems(os.Stdin, o.read0, func(s string) { ch <- s })
			close(ch)
		}()
		return ch, nil
	}
	if cmdStr, ok := os.LookupEnv("FZF_DEFAULT_COMMAND"); ok && cmdStr != "" {
		cmd := shellCommand(cmdStr, o)
		stdout, err := cmd.StdoutPipe()
		if err != nil {
			close(ch)
			return ch, nil
		}
		cmd.Stderr = os.Stderr
		if err := cmd.Start(); err != nil {
			close(ch)
			return ch, nil
		}
		go func() {
			streamItems(stdout, o.read0, func(s string) { ch <- s })
			close(ch)
		}()
		return ch, func() { _ = cmd.Wait() }
	}
	// Built-in walker.
	go func() {
		walkInputs(o, func(s string) { ch <- s })
		close(ch)
	}()
	return ch, nil
}

func shellCommand(command string, o *options) *exec.Cmd {
	var cmd *exec.Cmd
	if o != nil && o.withShellSet {
		parts, err := parseShellWords(o.withShell)
		if err == nil && len(parts) > 0 {
			args := append(append([]string{}, parts[1:]...), command)
			cmd = exec.Command(parts[0], args...)
		}
		}
	if cmd == nil {
		shell := os.Getenv("SHELL")
		if shell == "" {
			shell = "sh"
		}
		cmd = exec.Command(shell, "-c", command)
	}
	return cmd
}

func runShellCommand(command string, o *options, env []string, stdin io.Reader) ([]byte, error) {
	cmd := shellCommand(command, o)
	if env != nil {
		cmd.Env = env
	}
	if stdin != nil {
		cmd.Stdin = stdin
	}
	return cmd.Output()
}

func walkInputs(o *options, emit func(string)) {
	roots := o.walkerRoots
	if len(roots) == 0 {
		roots = []string{"."}
	}
	skip := map[string]bool{}
	for _, s := range o.walkerSkip {
		skip[s] = true
	}
	for _, root := range roots {
		walkDir(root, root, o, skip, emit)
	}
}

func walkDir(root, dir string, o *options, skip map[string]bool, emit func(string)) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	// os.ReadDir returns entries sorted by filename.
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
	for _, e := range entries {
		name := e.Name()
		if !o.walkerHidden && strings.HasPrefix(name, ".") {
			continue
		}
		path := filepath.Join(dir, name)
		display := path
		if root == "." {
			display = strings.TrimPrefix(path, "./")
		}
		isDir := false
		if e.IsDir() {
			isDir = true
		} else if e.Type()&os.ModeSymlink != 0 {
			if st, err := os.Stat(path); err == nil && st.IsDir() {
				isDir = true
			}
		}
		if isDir {
			if skip[name] {
				continue
			}
			if o.walkerDir {
				emit(display)
			}
			// Follow symlinked directories only with follow.
			if e.Type()&os.ModeSymlink != 0 && !o.walkerFollow {
				continue
			}
			walkDir(root, path, o, skip, emit)
		} else {
			if o.walkerFile {
				emit(display)
			}
		}
	}
}
