def bonus_array(text):
    # classes simplified for ascii in tests: space white, /,:;| delim, nonword, lower, upper, digit
    def cls(ch):
        if ch in ' \t': return 'W'
        if ch in '/,:;|': return 'D'
        if ch.islower(): return 'l'
        if ch.isupper(): return 'U'
        if ch.isalpha(): return 'L'
        if ch.isdigit(): return 'n'
        return 'N'
    B=[]; prev='W'
    for ch in text:
        cur=cls(ch)
        if cur=='W': b=10
        elif cur=='N': b=8
        elif cur=='D':
            b=10 if prev=='W' else 9 if prev=='D' else 8
        else:
            if prev=='W': b=10
            elif prev=='D': b=9
            elif prev=='N': b=8
            elif prev=='l' and cur=='U': b=7
            elif cur=='n' and prev!='n': b=7
            else: b=0
        B.append(b); prev=cur
    return B

def score(text,pat, variant=1):
