import pathlib
p=pathlib.Path("algo.go"); s=p.read_text()
start=s.index("func fuzzyMatchV1(text, pattern []rune")
end=s.index("func trimLeftSpaceRunes")
new=r'''func fuzzyMatchV1(text, pattern []rune, caseSensitive, normalize, forward bool, sc scoringScheme) matchResult {
	if len(pattern) == 0 {
		return matchResult{ok: true}
	}
	n := len(text)
	m := len(pattern)
	if m > n {
		return matchResult{}
	}
	var start, end int
	if forward {
		// Forward greedy scan to find the first completion, then a
		// backward scan to shrink the window from the left.
		j := 0
		end = -1
		for i := 0; i < n; i++ {
			if j < m && equalRune(text[i], pattern[j], caseSensitive, normalize) {
				j++
				if j == m {
					end = i + 1
					break
				}
			}
		}
		if end < 0 {
			return matchResult{}
		}
		j = m - 1
		start = -1
		for i := end - 1; i >= 0; i-- {
			if j >= 0 && equalRune(text[i], pattern[j], caseSensitive, normalize) {
				j--
				if j < 0 {
					start = i
					break
				}
			}
		}
		if start < 0 {
			return matchResult{}
		}
		// Greedy forward positions inside the window.
		positions := make([]int, 0, m)
		j = 0
		for i := start; i < end && j < m; i++ {
			if equalRune(text[i], pattern[j], caseSensitive, normalize) {
				positions = append(positions, i)
				j++
			}
		}
		if j != m {
			return matchResult{}
		}
		return matchResult{score: scoreAlignment(text, pattern, positions, sc), begin: positions[0], end: positions[m-1] + 1, positions: positions, ok: true}
	}
	// Backward: greedy scan from the end to find the last match window,
	// then a forward scan to shrink it from the right.
	j := m - 1
	start = -1
	for i := n - 1; i >= 0; i-- {
		if j >= 0 && equalRune(text[i], pattern[j], caseSensitive, normalize) {
			j--
			if j < 0 {
				start = i
				break
			}
		}
	}
	if start < 0 {
		return matchResult{}
	}
	j = 0
	end = -1
	for i := start; i < n; i++ {
		if j < m && equalRune(text[i], pattern[j], caseSensitive, normalize) {
			j++
			if j == m {
				end = i + 1
				break
			}
		}
	}
	if end < 0 {
		return matchResult{}
	}
	// Greedy backward positions inside the window.
	positions := make([]int, m)
	j = m - 1
	for i := end - 1; i >= start && j >= 0; i-- {
		if equalRune(text[i], pattern[j], caseSensitive, normalize) {
			positions[j] = i
			j--
		}
	}
	if j >= 0 {
		return matchResult{}
	}
	return matchResult{score: scoreAlignment(text, pattern, positions, sc), begin: positions[0], end: positions[m-1] + 1, positions: positions, ok: true}
}

'''
s=s[:start]+new+s[end:]
p.write_text(s)
