	start := 0
	for i, r := range s {
		switch r {
		case '(':
			depth++
		case ')':
			if depth > 0 {
				depth--
			}
		case ',', ':':
			if depth == 0 {
				out = append(out, s[start:i])
				start = i + 1
			}
		}
	}
	out = append(out, s[start:])
	return out
}

func parsePreviewWindowValue(v string, cur previewWindow) (previewWindow, error) {
	return parsePreviewWindowInner(v, cur, true)
}

func parsePreviewWindowInner(v string, cur previewWindow, allowAlt bool) (previewWindow, error) {
	base := cur
	if allowAlt {
		// A new --preview-window value replaces previous alternatives when
		// it specifies new ones; tokens below append to this empty list.
		// Keep alternatives only if this value specifies any (handled by
		// only resetting when a '<' token is first seen).
	}
	layout := base.previewLayout
	var alts []previewAlternative
	altsSeen := false
	toks := splitPreviewTokens(v)
	for _, tok := range toks {
		if tok == "" {
			continue
		}
		if strings.HasPrefix(tok, "<") {
			if !allowAlt {
				return cur, invalidPreviewOpt(tok)
			}
			open := strings.Index(tok, "(")
			if open < 0 || !strings.HasSuffix(tok, ")") {
				return cur, invalidPreviewOpt(tok)
			}
			threshStr := tok[1:open]
			thresh, err := strconv.Atoi(threshStr)
			if err != nil || thresh <= 0 {
				return cur, invalidPreviewOpt(tok)
			}
			altStr := tok[open+1 : len(tok)-1]
			if altStr == "" {
				return cur, invalidPreviewOpt(tok)
			}
			// Reject stray parentheses inside the alternative body.
			if strings.ContainsAny(altStr, "()") {
				// The reference reports the stray token for a doubled
				// closing paren and the whole token for a nested
				// alternative; approximate with the whole token except
				// for a pure extra ')' body.
				if strings.HasPrefix(altStr, "(") {
					return cur, invalidPreviewOpt(")")
				}
				return cur, invalidPreviewOpt(tok)
			}
			altCur := previewWindow{previewLayout: layout}
			altParsed, err := parsePreviewWindowInner(altStr, altCur, false)
			if err != nil {
				return cur, err
			}
			if !altsSeen {
				alts = nil
				altsSeen = true
			}
			alts = append(alts, previewAlternative{threshold: thresh, layout: altParsed.previewLayout})
			continue
		}
		switch tok {
		case "right":
			layout.position = previewRight
		case "left":
			layout.position = previewLeft
		case "up", "top":
			layout.position = previewUp
		case "down", "bottom":
			layout.position = previewDown
		case "wrap":
			layout.wrap = true
		case "nowrap":
			layout.wrap = false
		case "cycle":
			layout.cycle = true
		case "nocycle":
			layout.cycle = false
		case "follow":
			layout.follow = true
		case "nofollow":
			layout.follow = false
		case "info":
			layout.info = true
		case "noinfo":
			layout.info = false
		case "hidden":
			layout.hidden = true
		case "nohidden":
			layout.hidden = false
		case "border":
			layout.border = borderRounded
			layout.borderSet = true
		case "default":
			layout = defaultPreviewWindow().previewLayout
		default:
			if strings.HasPrefix(tok, "border-") {
				st, err := parseBorderStyle(strings.TrimPrefix(tok, "border-"))
				if err != nil {
					return cur, invalidPreviewOpt(tok)
				}
				layout.border = st
				layout.borderSet = true
			} else if strings.HasPrefix(tok, "+") {
				if !validScrollExpr(tok) {
					return cur, invalidPreviewOpt(tok)
				}
				layout.scroll = tok
			} else if strings.HasPrefix(tok, "~") {
				rest := tok[1:]
				n, err := strconv.Atoi(rest)
				if rest == "" || err != nil || n < 0 {
					return cur, invalidPreviewOpt(tok)
				}
				layout.headerLines = n
			} else if isPreviewSizeToken(tok) {
				sz, err := parsePreviewSize(tok)
				if err != nil {
					return cur, err
				}
				layout.size = sz
			} else {
				return cur, invalidPreviewOpt(tok)
			}
		}
	}
	base.previewLayout = layout
	if altsSeen {
		base.alts = alts
	}
	return base, nil
}

func isPreviewSizeToken(tok string) bool {
	if strings.HasSuffix(tok, "%") {
		num := tok[:len(tok)-1]
		if num == "" {
			return false
		}
		for _, c := range num {
			if c < '0' || c > '9' {
				return false
			}
		}
		return true
	}
	s := tok
	if strings.HasPrefix(s, "-") || strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func parsePreviewSize(tok string) (sizeSpec, error) {
	if strings.HasSuffix(tok, "%") {
		return parseSize(tok, "window size", 99)
	}
	n, err := strconv.Atoi(tok)
	if err != nil {
		return sizeSpec{}, invalidPreviewOpt(tok)
	}
	return sizeSpec{num: float64(n)}, nil
}

func validScrollExpr(s string) bool {
	if len(s) < 2 || s[0] != '+' {
		return false
	}
	rest := s[1:]
	// Optional /DENOM at the end: denominator is a positive integer with
	// no leading zero.
	if idx := strings.LastIndex(rest, "/"); idx >= 0 {
		if strings.Count(rest, "/") != 1 {
			return false
		}
		denom := rest[idx+1:]
		rest = rest[:idx]
		if denom == "" || denom[0] == '0' {
			return false
		}
		n, err := strconv.Atoi(denom)
		if err != nil || n <= 0 {
			return false
		}
		if rest == "" {
			return false
		}
	}
	// rest is term (('+'|'-') term)* where a term is an unsigned integer
	// or a placeholder {N}, {-N} or {n}.
	i := 0
	term := func() bool {
		if i >= len(rest) {
			return false
		}
		if rest[i] == '{' {
			end := strings.IndexByte(rest[i:], '}')
			if end < 0 {
				return false
			}
			content := rest[i+1 : i+end]
			if content == "n" {
				i += end + 1
				return true
			}
			if content == "" {
				return false
			}
			// A single field index: optional '-', then digits.
			c := content
			if strings.HasPrefix(c, "-") {
				c = c[1:]
			}
			if c == "" {
				return false
			}
			for _, ch := range c {
				if ch < '0' || ch > '9' {
					return false
				}
			}
			i += end + 1
			return true
		}
		start := i
		for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
			i++
		}
		return i > start
	}
	if !term() {
		return false
	}
	for i < len(rest) {
		if rest[i] != '+' && rest[i] != '-' {
			return false
		}
		i++
		if !term() {
			return false
		}
	}
	return true
}

// parseChangePreviewWindow parses the argument of a
// change-preview-window(...) action: multiple preview-window specs
// separated by '|'.  Each spec is parsed over the current window.
func parseChangePreviewWindow(arg string, cur previewWindow) ([]previewWindow, error) {
	parts := strings.Split(arg, "|")
	var out []previewWindow
	for _, part := range parts {
		pw, err := parsePreviewWindowValue(part, cur)
		if err != nil {
			return nil, err
		}
		out = append(out, pw)
	}
	return out, nil
}
