		copy(acts, actions)
		for i, a := range acts {
			if a.name == "put" && !a.argSet {
				r := []rune(k)
				if len(r) == 1 {
					acts[i].arg = k
					acts[i].argSet = true
				} else if k == "space" {
					acts[i].arg = " "
					acts[i].argSet = true
				}
			}
		}
		sc.o.bindings = append(sc.o.bindings, parsedBinding{key: k, actions: acts, append: appendMode})
	}
