// the closing delimiter.  The closing delimiter is the first one that is
// followed by '+', ',' or the end of the string.
func extractActionArg(s string, start int) (string, int, bool) {
	open := s[start]
	close := closingDelim(open)
	for i := start + 1; i < len(s); i++ {
		if s[i] != close {
			continue
		}
		if i+1 == len(s) || s[i+1] == '+' || s[i+1] == ',' {
			return s[start+1 : i], i + 1, true
		}
	}
	return "", start, false
}

// extractUnknownActionToken extracts a token to report for an unknown action.
func extractUnknownActionToken(s string, start int) string {
	i := start
	for i < len(s) {
		c := s[i]
		if c == '+' || c == ',' {
			break
		}
		if strings.ContainsRune(argDelimiters, rune(c)) {
			if _, end, ok := extractActionArg(s, i); ok {
				return s[start:end]
			}
			return s[start:]
		}
		i++
	}
	return s[start:i]
}

type bindScanner struct {
	s string
	i int
	o *options
}

// parseAndAddBind parses one --bind argument value and records bindings.
func parseAndAddBind(o *options, spec string) error {
	if spec == "" {
		return fmt.Errorf("key name required")
	}
	sc := &bindScanner{s: spec, o: o}
	for sc.i < len(sc.s) {
		if err := sc.parseOneBinding(); err != nil {
			return err
		}
		// After a binding, a comma separates the next binding; a trailing
		// comma with nothing after it is an error caught by the next
		// parseOneBinding call (empty keys).
		if sc.i < len(sc.s) && sc.s[sc.i] == ',' {
			sc.i++
			if sc.i >= len(sc.s) {
				return fmt.Errorf("key name required")
			}
			continue
		}
		if sc.i < len(sc.s) {
			// Should not happen; treat remainder as another binding.
			continue
		}
	}
	return nil
}

func (sc *bindScanner) parseOneBinding() error {
	start := sc.i
	// Find the colon separating keys from actions.  Keys are a
	// comma-separated list; scan comma-separated tokens until one
	// contains a colon.
	if sc.i >= len(sc.s) {
		return fmt.Errorf("key name required")
	}
	// Special case: the key is a literal comma (spec starts with ",:").
	var keyTokens []string
	colonIdx := -1
	if sc.s[sc.i] == ',' && sc.i+1 < len(sc.s) && sc.s[sc.i+1] == ':' {
		keyTokens = []string{","}
		colonIdx = sc.i + 1
	} else {
		scan := sc.i
		for {
			comma := strings.IndexByte(sc.s[scan:], ',')
			colon := strings.IndexByte(sc.s[scan:], ':')
			if colon < 0 {
				// No colon at all in the rest of this binding segment.
				segEnd := len(sc.s)
				if comma >= 0 {
					segEnd = scan + comma
				}
				return fmt.Errorf("bind action not specified: %s", sc.s[start:segEnd])
			}
			colonAbs := scan + colon
			if comma < 0 || colon < comma {
				keyTokens = append(keyTokens, sc.s[scan:colonAbs])
				colonIdx = colonAbs
				break
			}
			keyTokens = append(keyTokens, sc.s[scan:scan+comma])
			scan = scan + comma + 1
		}
	}
	if len(keyTokens) == 0 {
		return fmt.Errorf("key name required")
	}
	var canonKeys []string
	for _, kt := range keyTokens {
		if kt == "" {
			return fmt.Errorf("key name required")
		}
		canon, err := canonicalKeyName(kt)
		if err != nil {
			return err
		}
		canonKeys = append(canonKeys, canon)
	}
	sc.i = colonIdx + 1
	actions, appendMode, err := sc.parseActions(canonKeys)
	if err != nil {
		return err
	}
	for _, k := range canonKeys {
		// Expand put-without-argument per key (already handled for the
		// action list as a whole in parseActions for the first key; here
		// clone actions and fix put arguments per key).
		acts := make([]action, len(actions))
		copy(acts, actions)
		for i, a := range acts {
			if a.name == "put" && !a.argSet {
				r := []rune(k)
				if len(r) == 1 {
					acts[i].arg = k
					acts[i].argSet = true
				} else if k == "space" {
					acts[i].arg = " "
					acts[i].argSet = true
				}
			}
		}
		sc.o.bindings = append(sc.o.bindings, parsedBinding{key: k, actions: acts, append: appendMode})
	}
	sc.o.bindSpecs = append(sc.o.bindSpecs, sc.s[start:sc.i])
	return nil
}

// parseActions parses the action chain after "KEY:"; it stops at a comma
// that separates the next binding (sc.i is left at that comma).
func (sc *bindScanner) parseActions(keys []string) ([]action, bool, error) {
	var actions []action
	appendMode := false
	if sc.i < len(sc.s) && sc.s[sc.i] == '+' {
		appendMode = true
		sc.i++
	}
	if sc.i >= len(sc.s) || sc.s[sc.i] == ',' {
		return actions, appendMode, nil
	}
	for {
		act, err := sc.parseAction(keys)
		if err != nil {
			return nil, false, err
		}
		actions = append(actions, act)
		if sc.i >= len(sc.s) {
			break
		}
		if sc.s[sc.i] == '+' {
			sc.i++
			if sc.i >= len(sc.s) {
				return nil, false, fmt.Errorf("unknown action: %s", "")
			}
			continue
		}
		if sc.s[sc.i] == ',' {
			break
		}
		// Anything else glued to an action makes the whole token unknown;
		// this is normally caught inside parseAction.
		break
	}
	return actions, appendMode, nil
}

func (sc *bindScanner) parseAction(keys []string) (action, error) {
	start := sc.i
	rest := sc.s[sc.i:]
	lowerRest := strings.ToLower(rest)
	matched := ""
	for _, name := range sortedActionNames {
		if !strings.HasPrefix(lowerRest, name) {
			continue
		}
		afterIdx := len(name)
		if afterIdx < len(rest) {
			c := rest[afterIdx]
			// The name must not continue into a longer identifier.
			if c == '-' || c == '/' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
				continue
			}
		}
		matched = name
		break
	}
	isNoArg := matched != "" && noArgActions[matched]
	isArg := matched != "" && argActions[matched]
	isOptional := matched != "" && optionalArgActions[matched]

	// Determine what follows a candidate name.
	after := ""
	if matched != "" {
		after = rest[len(matched):]
	}
	hasArgSyntax := matched != "" && len(after) > 0 && (strings.ContainsRune(argDelimiters, rune(after[0])) || after[0] == ':')

	if matched != "" && ((isArg && hasArgSyntax) || (isOptional) || (isNoArg && !hasArgSyntax) || matched == "put") {
		sc.i += len(matched)
		if hasArgSyntax {
			open := sc.s[sc.i]
			if open == ':' {
				// Colon form consumes the rest of the whole spec.
				arg := sc.s[sc.i+1:]
				sc.i = len(sc.s)
				// preview-window arguments are validated eagerly.
				if err := validateActionArg(matched, arg); err != nil {
					return action{}, err
				}
				return action{name: matched, arg: arg, argSet: true}, nil
			}
			arg, end, ok := extractActionArg(sc.s, sc.i)
			if !ok {
				return action{}, fmt.Errorf("unknown action: %s", extractUnknownActionToken(sc.s, start))
			}
			sc.i = end
			// What follows must be '+', ',' or the end.
			if sc.i < len(sc.s) && sc.s[sc.i] != '+' && sc.s[sc.i] != ',' {
				return action{}, fmt.Errorf("unknown action: %s", extractUnknownActionToken(sc.s, start))
			}
			if err := validateActionArg(matched, arg); err != nil {
				return action{}, err
			}
			return action{name: matched, arg: arg, argSet: true}, nil
		}
		// No argument syntax.
		if isArg && !isOptional && matched != "put" {
			// e.g. "execute" alone is reported as an unknown action.
			return action{}, fmt.Errorf("unknown action: %s", extractUnknownActionToken(sc.s, start))
		}
		if matched == "put" {
			// Requires every bound key to be a printable character.
			for _, k := range keys {
				if !isPrintableKey(k) {
					return action{}, fmt.Errorf("unable to put non-printable character")
				}
			}
			return action{name: "put"}, nil
		}
		return action{name: matched}, nil
	}
	return action{}, fmt.Errorf("unknown action: %s", extractUnknownActionToken(sc.s, start))
}

func isPrintableKey(canon string) bool {
	if canon == "space" {
		return true
	}
	return len([]rune(canon)) == 1
}

func validateActionArg(name, arg string) error {
	switch name {
	case "change-preview-window":
		if strings.Contains(arg, "|") {
			for _, part := range strings.Split(arg, "|") {
				if part == "" {
					continue
				}
				if _, err := parsePreviewWindowValue(part, defaultPreviewWindow()); err != nil {
					return err
				}
			}
			return nil
		}
		_, err := parsePreviewWindowValue(arg, defaultPreviewWindow())
		return err
	case "unbind", "rebind", "toggle-bind":
		if strings.TrimSpace(arg) == "" {
			return fmt.Errorf("key name required")
		}
		for _, k := range strings.Split(arg, ",") {
			if _, err := canonicalKeyName(k); err != nil {
				return err
			}
		}
		return nil
	}
	return nil
}

// parseActionString parses an action chain (used for transform outputs and
// HTTP POST bodies).  key is a synthetic printable key for `put` checks.
func parseActionString(spec string) ([]action, error) {
	o := &options{}
	sc := &bindScanner{s: spec, o: o}
	// Action chains have no "KEY:" prefix; parse them relative to a
	// synthetic key.
	acts, _, err := sc.parseActions([]string{"x"})
	if err != nil {
		return nil, err
	}
	if sc.i < len(sc.s) {
		// A comma separates bindings in --bind, but in a bare action
		// string a comma can just be skipped between chains sent via
		// HTTP (one action per line is handled by the caller).  Report
		// the remainder as an unknown action.
		return nil, fmt.Errorf("unknown action: %s", strings.TrimLeft(sc.s[sc.i:], ","))
	}
	return acts, nil
}
