	hasArgSyntax := matched != "" && len(after) > 0 && (strings.ContainsRune(argDelimiters, rune(after[0])) || after[0] == ':')

	if matched != "" && ((isArg && hasArgSyntax) || (isOptional) || (isNoArg && !hasArgSyntax) || matched == "put") {
		sc.i += len(matched)
		if hasArgSyntax {
			open := sc.s[sc.i]
			if open == ':' {
				// Colon form consumes the rest of the whole spec.
				arg := sc.s[sc.i+1:]
				sc.i = len(sc.s)
				// preview-window arguments are validated eagerly.
				if err := validateActionArg(matched, arg); err != nil {
					return action{}, err
				}
				return action{name: matched, arg: arg, argSet: true}, nil
			}
			arg, end, ok := extractActionArg(sc.s, sc.i)
			if !ok {
				return action{}, fmt.Errorf("unknown action: %s", extractUnknownActionToken(sc.s, start))
			}
			sc.i = end
			// What follows must be '+', ',' or the end.
			if sc.i < len(sc.s) && sc.s[sc.i] != '+' && sc.s[sc.i] != ',' {
				return action{}, fmt.Errorf("unknown action: %s", extractUnknownActionToken(sc.s, start))
			}
			if err := validateActionArg(matched, arg); err != nil {
				return action{}, err
			}
			return action{name: matched, arg: arg, argSet: true}, nil
		}
		// No argument syntax.
		if isArg && !isOptional && matched != "put" {
			// e.g. "execute" alone is reported as an unknown action.
			return action{}, fmt.Errorf("unknown action: %s", extractUnknownActionToken(sc.s, start))
		}
		if matched == "put" {
			// Requires every bound key to be a printable character.
			for _, k := range keys {
				if !isPrintableKey(k) {
					return action{}, fmt.Errorf("unable to put non-printable character")
				}
			}
			return action{name: "put"}, nil
		}
		return action{name: matched}, nil
	}
	return action{}, fmt.Errorf("unknown action: %s", extractUnknownActionToken(sc.s, start))
}

func isPrintableKey(canon string) bool {
	if canon == "space" {
		return true
	}
	return len([]rune(canon)) == 1
}

func validateActionArg(name, arg string) error {
	switch name {
	case "change-preview-window":
		if strings.Contains(arg, "|") {
			for _, part := range strings.Split(arg, "|") {
				if part == "" {
					continue
				}
				if _, err := parsePreviewWindowValue(part, defaultPreviewWindow()); err != nil {
					return err
				}
			}
			return nil
		}
		_, err := parsePreviewWindowValue(arg, defaultPreviewWindow())
		return err
	case "unbind", "rebind", "toggle-bind":
		if strings.TrimSpace(arg) == "" {
			return fmt.Errorf("key name required")
		}
		for _, k := range strings.Split(arg, ",") {
			if _, err := canonicalKeyName(k); err != nil {
				return err
			}
		}
		return nil
	}
	return nil
}

// parseActionString parses an action chain (used for transform outputs and
// HTTP POST bodies).  key is a synthetic printable key for `put` checks.
func parseActionString(spec string) ([]action, error) {
	o := &options{}
	sc := &bindScanner{s: spec, o: o}
	// Action chains have no "KEY:" prefix; parse them relative to a
	// synthetic key.
	acts, _, err := sc.parseActions([]string{"x"})
	if err != nil {
		return nil, err
	}
	if sc.i < len(sc.s) {
		// A comma separates bindings in --bind, but in a bare action
		// string a comma can just be skipped between chains sent via
		// HTTP (one action per line is handled by the caller).  Report
		// the remainder as an unknown action.
		return nil, fmt.Errorf("unknown action: %s", strings.TrimLeft(sc.s[sc.i:], ","))
	}
	return acts, nil
}
