package main

import (
	"os"
	"strconv"
	"strings"
)

type placeholderContext struct {
	current  *item
	selected []*item
	matched  []*item
	query    string
	delim    delimiter
}

func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func placeholderFieldText(it *item, ranges []fieldRange, preserve bool, d delimiter) string {
	text := it.orig
	toks := tokenize(text, d)
	refs := refsForRanges(toks, ranges)
	if len(refs) == 0 {
		return ""
	}
	var b strings.Builder
	for _, idx := range refs {
		t := toks[idx]
		b.WriteString(text[t.b0:t.b1])
	}
	out := b.String()
	// Strip the trailing delimiter of the last referenced token unless
	// preserving whitespace and the delimiter is whitespace-based (AWK),
	// in which case the whitespace is part of what `s` preserves.
	strip := true
	if preserve && d.awk {
		strip = false
	}
	if strip {
		for i := len(refs) - 1; i >= 0; i-- {
			t := toks[refs[i]]
			if t.b1 == t.b0 {
				continue
			}
			if t.delimB > 0 && len(out) >= t.delimB {
				out = out[:len(out)-t.delimB]
			}
			break
		}
	}
	if !preserve {
		out = strings.TrimSpace(out)
	}
	return out
}

func queryFieldText(query string, ranges []fieldRange, d delimiter) string {
	toks := tokenize(query, d)
	refs := refsForRanges(toks, ranges)
	out := joinTokenRefs(query, toks, refs)
	return strings.TrimSpace(out)
}

type parsedPlaceholder struct {
	source   byte // 0 current, '+', '*'
	raw      bool
	preserve bool
	toFile   bool
	isIndex  bool
	isQuery  bool
	queryRanges []fieldRange
	hasRanges bool
	ranges   []fieldRange
}

func parsePlaceholder(content string) (parsedPlaceholder, bool) {
	var ph parsedPlaceholder
	if content == "" {
		return ph, true
	}
	if content == "q" {
		ph.isQuery = true
		return ph, true
	}
	if strings.HasPrefix(content, "q:") {
		ranges, err := parseRangeList(content[2:])
		if err != nil {
			return ph, false
		}
		ph.isQuery = true
		ph.queryRanges = ranges
		ph.hasRanges = true
		return ph, true
	}
	i := 0
	sourceSeen := false
	for i < len(content) {
		c := content[i]
		if c != '+' && c != '*' && c != 'r' && c != 's' && c != 'f' {
			break
		}
		switch c {
		case '+', '*':
			ph.source = c
			sourceSeen = true
		case 'r':
			ph.raw = true
		case 's':
			ph.preserve = true
		case 'f':
			ph.toFile = true
		}
		i++
	}
	rest := content[i:]
	if rest == "n" {
		// Only a source selector may precede {n}.
		if ph.raw || ph.preserve || ph.toFile {
			return ph, false
		}
		ph.isIndex = true
		return ph, true
	}
	_ = sourceSeen
	if rest == "" {
		return ph, true
	}
	// q may not be preceded by flags.
	if strings.HasPrefix(rest, "q") {
		return ph, false
	}
	ranges, err := parseRangeList(rest)
	if err != nil {
		return ph, false
	}
	ph.ranges = ranges
	ph.hasRanges = true
	return ph, true
}

// expandPlaceholders replaces placeholder expressions in template.
// When quote is true, replacements are shell-quoted (unless the `r` flag
// is present).  It returns temp file paths created for `f` placeholders;
// the caller is responsible for removing them after use.
func expandPlaceholders(template string, ctx placeholderContext, quoteValues bool) (string, []string) {
	var tempFiles []string
	var out strings.Builder
	s := template
	i := 0
	for i < len(s) {
		// Escaped placeholder: \{ -> literal {
		if s[i] == '\\' && i+1 < len(s) && s[i+1] == '{' {
			out.WriteByte('{')
			i += 2
			continue
		}
		if s[i] != '{' {
			out.WriteByte(s[i])
			i++
			continue
