	var params []string
	add := func(v string) { params = append(params, v) }
	if s.attrs&attrBold != 0 {
		add("1")
	}
	if s.attrs&attrDim != 0 {
		add("2")
	}
	if s.attrs&attrItalic != 0 {
		add("3")
	}
	switch s.underline {
	case 1:
		add("4")
	case 2:
		add("4:2")
	case 3:
		add("4:3")
	case 4:
		add("4:4")
	case 5:
		add("4:5")
	}
	if s.attrs&attrReverse != 0 {
		add("7")
	}
	if s.attrs&attrStrikethrough != 0 {
		add("9")
	}
	params = append(params, fgParams(s.fg, false)...)
	params = append(params, fgParams(s.bg, true)...)
	return strings.Join(params, ";")
}

