		}
		return []string{prefix, "5", strconv.Itoa(c.code)}
	case colorRGB:
		return []string{prefix, "2", strconv.Itoa(c.r), strconv.Itoa(c.g), strconv.Itoa(c.b)}
	default:
		return []string{def}
	}
}

