func renderRowANSI(spans []styledSpan, width int, ambidouble bool, tabstop int, noBold bool) string {
	var b strings.Builder
	cur := cellStyle{fg: specColor(999), bg: specColor(999)}
	col := 0
	writeSpan := func(text string, st cellStyle) {
		if noBold {
			st = st.noBold()
		}
		// Truncate to remaining width by runes/display cells.
		var out []rune
		for _, r := range text {
			w := runeDisplayWidth(r, ambidouble)
			if r == '\t' {
				// Row builders expand tabs before rendering; treat as space.
				r = ' '
				w = 1
			}
			if col+w > width {
				break
			}
			out = append(out, r)
			col += w
		}
		if len(out) == 0 {
			return
		}
		if st != cur {
			b.WriteString("\x1b[0m")
			b.WriteString(sgr(st))
			cur = st
		}
		b.WriteString(string(out))
	}
	for _, sp := range spans {
		writeSpan(sp.text, sp.style)
	}
	b.WriteString("\x1b[0m")
	return b.String()
}

