	wheel   int // -1 up, +1 down, 0 none
	shift   bool
	alt     bool
	ctrl    bool
}

type keyEvent struct {
	name  string
	r     rune // for character keys
	mouse *mouseEvent
	paste string
	isPaste bool
}

// decodeKeys decodes as many complete key events as possible from buf.
// It returns the events and the number of bytes consumed.  Incomplete
// escape sequences at the end are left unconsumed (the caller waits for
// more bytes, with a timeout that can call flushEscape).
func decodeKeys(buf []byte) ([]keyEvent, int) {
	var events []keyEvent
	i := 0
	for i < len(buf) {
		ev, n, ok := decodeOneKey(buf[i:])
		if !ok {
			break
		}
		events = append(events, ev)
		i += n
	}
	return events, i
}

// flushEscape decodes a lone ESC (and following bytes that formed no
// complete sequence) as an Esc key.
func flushEscape(buf []byte) []keyEvent {
	if len(buf) == 0 {
		return nil
	}
	// Treat pending bytes as if the escape were standalone, then decode
	// the rest as regular input.
	evs := []keyEvent{{name: "esc"}}
	rest, _ := decodeKeys(buf[1:])
	evs = append(evs, rest...)
	return evs
}

func decodeOneKey(b []byte) (keyEvent, int, bool) {
	if len(b) == 0 {
		return keyEvent{}, 0, false
	}
	c := b[0]
	if c == 0x1b {
		return decodeEscape(b)
	}
	switch c {
	case 0x00:
		return keyEvent{name: "ctrl-space"}, 1, true
	case '\r':
		return keyEvent{name: "enter"}, 1, true
	case '\n':
		return keyEvent{name: "ctrl-j"}, 1, true
	case '\t':
		return keyEvent{name: "tab"}, 1, true
	case 0x7f:
		return keyEvent{name: "backspace"}, 1, true
	case 0x08:
		return keyEvent{name: "ctrl-backspace"}, 1, true
	}
	if c >= 0x01 && c <= 0x1a {
		return keyEvent{name: "ctrl-" + string(rune('a'+c-1))}, 1, true
	}
	switch c {
	case 0x1c:
		return keyEvent{name: `ctrl-\`}, 1, true
	case 0x1d:
		return keyEvent{name: "ctrl-]"}, 1, true
	case 0x1e:
		return keyEvent{name: "ctrl-^"}, 1, true
	case 0x1f:
		return keyEvent{name: "ctrl-/"}, 1, true
	}
	r, size := utf8.DecodeRune(b)
	if r == utf8.RuneError && size <= 1 {
		if !utf8.FullRune(b) {
			return keyEvent{}, 0, false
		}
		return keyEvent{name: string(rune(c)), r: rune(c)}, 1, true
	}
	name := string(r)
	if r == ' ' {
		name = "space"
	}
	return keyEvent{name: name, r: r}, size, true
}

func decodeEscape(b []byte) (keyEvent, int, bool) {
	if len(b) < 2 {
		return keyEvent{}, 0, false
	}
	switch b[1] {
	case '[':
		return decodeCSI(b)
	case 'O':
		if len(b) < 3 {
			return keyEvent{}, 0, false
		}
		switch b[2] {
		case 'A':
			return keyEvent{name: "up"}, 3, true
		case 'B':
			return keyEvent{name: "down"}, 3, true
		case 'C':
			return keyEvent{name: "right"}, 3, true
		case 'D':
			return keyEvent{name: "left"}, 3, true
		case 'H':
			return keyEvent{name: "home"}, 3, true
		case 'F':
			return keyEvent{name: "end"}, 3, true
		case 'P':
			return keyEvent{name: "f1"}, 3, true
		case 'Q':
			return keyEvent{name: "f2"}, 3, true
		case 'R':
			return keyEvent{name: "f3"}, 3, true
		case 'S':
			return keyEvent{name: "f4"}, 3, true
		}
