	case 0x1b:
		return keyEvent{name: "esc"}, 1, true
	case 0x7f:
		return keyEvent{name: "alt-backspace"}, 2, true
	case 0x08:
		return keyEvent{name: "ctrl-alt-backspace"}, 2, true
	case '\r':
		return keyEvent{name: "alt-enter"}, 2, true
	}
