	r, size := utf8.DecodeRune(b[1:])
	if r == utf8.RuneError && size <= 1 {
		if !utf8.FullRune(b[1:]) {
			return keyEvent{}, 0, false
		}
		return keyEvent{name: "alt-" + string(rune(b[1])), r: rune(b[1])}, 2, true
	}
	name := string(r)
	if r == ' ' {
		return keyEvent{name: "alt-space", r: r}, 1 + size, true
	}
	return keyEvent{name: "alt-" + name, r: r}, 1 + size, true
