func modifierPrefix(mod int) string {
	// xterm modifier parameter: 1=none 2=shift 3=alt 4=shift+alt
	// 5=ctrl 6=shift+ctrl 7=alt+ctrl 8=shift+alt+ctrl
	switch mod {
	case 2:
		return "shift-"
	case 3:
		return "alt-"
	case 4:
		return "alt-shift-"
	case 5:
		return "ctrl-"
	case 6:
		return "ctrl-shift-"
	case 7:
		return "ctrl-alt-"
	case 8:
		return "ctrl-alt-shift-"
	}
	return ""
}

func decodeCSI(b []byte) (keyEvent, int, bool) {
	// b[0]=ESC b[1]='['
	j := 2
	// Parameter/intermediate bytes.
	for j < len(b) && b[j] >= 0x20 && b[j] <= 0x3f {
		j++
	}
	if j >= len(b) {
		return keyEvent{}, 0, false
	}
	final := b[j]
	if final < 0x40 || final > 0x7e {
		return keyEvent{name: "esc"}, 1, true
	}
	params := string(b[2:j])
	total := j + 1
	// Mouse SGR: ESC [< b ; x ; y M/m
	if strings.HasPrefix(params, "<") && (final == 'M' || final == 'm') {
		parts := strings.Split(params[1:], ";")
		if len(parts) == 3 {
			btn, _ := strconv.Atoi(parts[0])
			x, _ := strconv.Atoi(parts[1])
			y, _ := strconv.Atoi(parts[2])
			m := &mouseEvent{x: x - 1, y: y - 1, release: final == 'm'}
			m.shift = btn&4 != 0
			m.alt = btn&8 != 0
			m.ctrl = btn&16 != 0
			code := btn & 0x43
			if btn&64 != 0 {
				if code == 0 {
					m.wheel = -1
				} else {
					m.wheel = 1
				}
				m.button = 0
			} else {
				m.button = code
			}
			name := mouseEventName(m)
			return keyEvent{name: name, mouse: m}, total, true
		}
		return keyEvent{name: "ignore"}, total, true
	}
	// Bracketed paste.
	if params == "200" && final == '~' {
		// Find terminator ESC[201~ in the rest; if absent, wait for more.
		rest := string(b[total:])
		end := strings.Index(rest, "\x1b[201~")
		if end < 0 {
			return keyEvent{}, 0, false
		}
		return keyEvent{name: "paste", paste: rest[:end], isPaste: true}, total + end + len("\x1b[201~"), true
	}
	if params == "201" && final == '~' {
		return keyEvent{name: "ignore"}, total, true
	}
	parts := strings.Split(params, ";")
	atoi := func(i int) int {
		if i < len(parts) {
			n, _ := strconv.Atoi(parts[i])
			return n
		}
		return 0
	}
	mod := atoi(1)
	prefix := modifierPrefix(mod)
	switch final {
	case 'A':
		return keyEvent{name: prefix + "up"}, total, true
	case 'B':
		return keyEvent{name: prefix + "down"}, total, true
	case 'C':
		return keyEvent{name: prefix + "right"}, total, true
	case 'D':
		return keyEvent{name: prefix + "left"}, total, true
	case 'E':
		return keyEvent{name: prefix + "end"}, total, true
	case 'F':
		return keyEvent{name: prefix + "end"}, total, true
	case 'H':
		return keyEvent{name: prefix + "home"}, total, true
	case 'Z':
		return keyEvent{name: "shift-tab"}, total, true
	case 'I':
		return keyEvent{name: "ignore"}, total, true // focus in
	case 'O':
		return keyEvent{name: "ignore"}, total, true // focus out
	case 'R':
		return keyEvent{name: "ignore"}, total, true // cursor position report
	case '~':
		switch atoi(0) {
		case 1, 7:
			return keyEvent{name: prefix + "home"}, total, true
		case 2:
			if prefix == "" {
				return keyEvent{name: "insert"}, total, true
			}
			return keyEvent{name: prefix + "insert"}, total, true
		case 3:
			if prefix == "" {
				return keyEvent{name: "delete"}, total, true
			}
			return keyEvent{name: prefix + "delete"}, total, true
		case 4, 8:
			return keyEvent{name: prefix + "end"}, total, true
		case 5:
			return keyEvent{name: prefix + "page-up"}, total, true
		case 6:
			return keyEvent{name: prefix + "page-down"}, total, true
		case 11, 12, 13, 14, 15, 17, 18, 19, 20, 21, 23, 24:
			fn := map[int]int{11: 1, 12: 2, 13: 3, 14: 4, 15: 5, 17: 6, 18: 7, 19: 8, 20: 9, 21: 10, 23: 11, 24: 12}[atoi(0)]
			return keyEvent{name: fmt.Sprintf("%sf%d", prefix, fn)}, total, true
		case 27:
			// modifyOtherKeys: ESC[27;mod;code~
			code := atoi(2)
			if code > 0 {
				r := rune(code)
				nm := string(r)
				if r == ' ' {
					nm = "space"
				}
				return keyEvent{name: prefix + nm, r: r}, total, true
			}
		}
	case 'u':
		// Kitty keyboard protocol: ESC[code;mod u
		code := atoi(0)
		if code > 0 {
			r := rune(code)
			nm := string(r)
			if r == ' ' {
				nm = "space"
			}
			// Common special code points.
			switch code {
			case 27:
				nm = "esc"
			case 13:
				nm = "enter"
			case 9:
				nm = "tab"
			case 127:
				nm = "backspace"
			}
			return keyEvent{name: prefix + nm, r: r}, total, true
		}
	}
	return keyEvent{name: "ignore"}, total, true
}

func mouseEventName(m *mouseEvent) string {
	if m.wheel < 0 {
		if m.shift {
			return "shift-scroll-up"
		}
		return "scroll-up"
	}
	if m.wheel > 0 {
		if m.shift {
			return "shift-scroll-down"
		}
		return "scroll-down"
	}
	if m.release {
		// fzf triggers click events on release of a press at the same
		// cell; the finder layer decides.  Name it by button for the
		// press path and let the finder track press state itself.
		if m.button == 2 {
			if m.shift {
				return "shift-right-click"
			}
			return "right-click"
		}
		if m.shift {
			return "shift-left-click"
		}
		return "left-click"
	}
	// Press events are delivered with names of the click too; the finder
	// decides when to fire.
	if m.button == 2 {
		if m.shift {
			return "shift-right-click"
		}
		return "right-click"
	}
	if m.shift {
		return "shift-left-click"
	}
	return "left-click"
}
