			return keyEvent{}, 0, false
		}
		return keyEvent{name: "paste", paste: rest[:end], isPaste: true}, total + end + len("\x1b[201~"), true
	}
	if params == "201" && final == '~' {
		return keyEvent{name: "ignore"}, total, true
	}
	parts := strings.Split(params, ";")
	atoi := func(i int) int {
		if i < len(parts) {
			n, _ := strconv.Atoi(parts[i])
			return n
		}
		return 0
	}
	mod := atoi(1)
	prefix := modifierPrefix(mod)
	switch final {
	case 'A':
		return keyEvent{name: prefix + "up"}, total, true
	case 'B':
		return keyEvent{name: prefix + "down"}, total, true
	case 'C':
		return keyEvent{name: prefix + "right"}, total, true
	case 'D':
		return keyEvent{name: prefix + "left"}, total, true
	case 'E':
		return keyEvent{name: prefix + "end"}, total, true
	case 'F':
		return keyEvent{name: prefix + "end"}, total, true
	case 'H':
		return keyEvent{name: prefix + "home"}, total, true
	case 'Z':
		return keyEvent{name: "shift-tab"}, total, true
	case 'I':
		return keyEvent{name: "ignore"}, total, true // focus in
	case 'O':
		return keyEvent{name: "ignore"}, total, true // focus out
	case 'R':
		return keyEvent{name: "ignore"}, total, true // cursor position report
	case '~':
		switch atoi(0) {
		case 1, 7:
			return keyEvent{name: prefix + "home"}, total, true
		case 2:
			if prefix == "" {
				return keyEvent{name: "insert"}, total, true
			}
			return keyEvent{name: prefix + "insert"}, total, true
		case 3:
			if prefix == "" {
				return keyEvent{name: "delete"}, total, true
			}
			return keyEvent{name: prefix + "delete"}, total, true
		case 4, 8:
			return keyEvent{name: prefix + "end"}, total, true
		case 5:
			return keyEvent{name: prefix + "page-up"}, total, true
		case 6:
			return keyEvent{name: prefix + "page-down"}, total, true
		case 11, 12, 13, 14, 15, 17, 18, 19, 20, 21, 23, 24:
			fn := map[int]int{11: 1, 12: 2, 13: 3, 14: 4, 15: 5, 17: 6, 18: 7, 19: 8, 20: 9, 21: 10, 23: 11, 24: 12}[atoi(0)]
			return keyEvent{name: fmt.Sprintf("%sf%d", prefix, fn)}, total, true
		case 27:
			// modifyOtherKeys: ESC[27;mod;code~
			code := atoi(2)
			if code > 0 {
				r := rune(code)
				nm := string(r)
				if r == ' ' {
					nm = "space"
				}
				return keyEvent{name: prefix + nm, r: r}, total, true
			}
		}
	case 'u':
		// Kitty keyboard protocol: ESC[code;mod u
		code := atoi(0)
		if code > 0 {
			r := rune(code)
			nm := string(r)
			if r == ' ' {
				nm = "space"
			}
			// Common special code points.
			switch code {
			case 27:
				nm = "esc"
			case 13:
				nm = "enter"
			case 9:
				nm = "tab"
			case 127:
				nm = "backspace"
			}
			return keyEvent{name: prefix + nm, r: r}, total, true
		}
	}
	return keyEvent{name: "ignore"}, total, true
}

func mouseEventName(m *mouseEvent) string {
	if m.wheel < 0 {
		if m.shift {
			return "shift-scroll-up"
		}
		return "scroll-up"
	}
	if m.wheel > 0 {
		if m.shift {
			return "shift-scroll-down"
		}
		return "scroll-down"
	}
	if m.release {
		// fzf triggers click events on release of a press at the same
		// cell; the finder layer decides.  Name it by button for the
		// press path and let the finder track press state itself.
		if m.button == 2 {
			if m.shift {
				return "shift-right-click"
			}
			return "right-click"
		}
		if m.shift {
			return "shift-left-click"
		}
		return "left-click"
	}
	// Press events are delivered with names of the click too; the finder
	// decides when to fire.
	if m.button == 2 {
		if m.shift {
			return "shift-right-click"
		}
		return "right-click"
	}
	if m.shift {
		return "shift-left-click"
	}
	return "left-click"
}
