{"command":"cat > finder.go <<'GO'
package main

import (
	"fmt"
	"os"
	"os/signal"
	"sort"
	"strings"
	"sync"
	"syscall"
	"time"
)

type rect struct{ x, y, w, h int }

func (r rect) right() int  { return r.x + r.w }
func (r rect) bottom() int { return r.y + r.h }

type gridCell struct {
	r     rune
	style cellStyle
	wide  bool // continuation of a wide rune
	set   bool
}

type grid struct {
	w, h  int
	cells []gridCell
}

func newGrid(w, h int, bg cellStyle) *grid {
	if w < 0 {
		w = 0
	}
	if h < 0 {
		h = 0
	}
	g := &grid{w: w, h: h, cells: make([]gridCell, w*h)}
	for i := range g.cells {
		g.cells[i] = gridCell{r: ' ', style: bg, set: true}
	}
	return g
}

func (g *grid) set(x, y int, r rune, st cellStyle, ambidouble bool) int {
	if x < 0 || y < 0 || x >= g.w || y >= g.h {
		return runeDisplayWidth(r, ambidouble)
	}
	w := runeDisplayWidth(r, ambidouble)
	if w == 0 {
		// Attach combining marks to the previous cell by leaving the grid
		// unchanged (the renderer will not show them separately).  This is
		// an approximation; returning 0 keeps the column position stable.
		return 0
	}
	idx := y*g.w + x
	g.cells[idx] = gridCell{r: r, style: st, set: true}
	if w == 2 && x+1 < g.w {
		g.cells[idx+1] = gridCell{r: 0, style: st, wide: true, set: true}
	}
	return w
}

func (g *grid) drawText(x, y, maxX int, text string, st cellStyle, ambidouble bool, tabstop int) int {
	col := x
	for _, r := range text {
		if col >= maxX {
			break
		}
		if r == '\t' {
			if tabstop <= 0 {
				tabstop = 8
			}
			next := x + ((col-x)/tabstop+1)*tabstop
			for col < next && col < maxX {
				g.set(col, y, ' ', st, ambidouble)
				col++
			}
			continue
		}
		if r == '\n' || r == '\r' {
			continue
		}
		w := runeDisplayWidth(r, ambidouble)
		if col+w > maxX {
			break
		}
		g.set(col, y, r, st, ambidouble)
		col += w
	}
	return col
}

// drawStyledRunes draws runes with a per-rune style slice (same length as runes).
func (g *grid) drawStyledRunes(x, y, maxX int, runes []rune, styles []cellStyle, ambidouble bool, tabstop int) int {
	col := x
	for i, r := range runes {
		if col >= maxX {
			break
		}
		st := styles[i]
		if r == '\t' {
			if tabstop <= 0 {
				tabstop = 8
			}
			next := x + ((col-x)/tabstop+1)*tabstop
			for col < next && col < maxX {
				g.set(col, y, ' ', st, ambidouble)
				col++
			}
			continue
		}
		w := runeDisplayWidth(r, ambidouble)
		if col+w > maxX {
			break
		}
		g.set(col, y, r, st, ambidouble)
		col += w
	}
	return col
}

func (g *grid) fillRect(r rect, st cellStyle) {
	for y := r.y; y < r.bottom() && y < g.h; y++ {
		for x := r.x; x < r.right() && x < g.w; x++ {
			if x >= 0 && y >= 0 {
				g.cells[y*g.w+x] = gridCell{r: ' ', style: st, set: true}
			}
		}
	}
}

type borderChars struct {
	tl, tr, bl, br, h, v rune
}

func charsForBorder(style borderStyle, unicode bool) borderChars {
	if !unicode {
		return borderChars{'+', '+', '+', '+', '-', '|'}
	}
	switch style {
	case borderRounded:
		return borderChars{'╭', '╮', '╰', '╯', '─', '│'}
	case borderSharp:
		return borderChars{'┌', '┐', '└', '┘', '─', '│'}
	case borderBold:
		return borderChars{'┏', '┓', '┗', '┛', '━', '┃'}
	case borderBlock:
		return borderChars{'█', '█', '█', '█', '█', '█'}
	case borderThinBlock:
		return borderChars{'▛', '▜', '▙', '▟', '▀', '▌'}
	case borderDouble:
		return borderChars{'╔', '╗', '╚', '╝', '═', '║'}
	default:
		return borderChars{'┌', '┐', '└', '┘', '─', '│'}
	}
}

// borderInsets returns (top,right,bottom,left) cells consumed by a border.
func borderInsets(style borderStyle, present bool) (int, int, int, int) {
	if !present || style == borderNoneStyle {
		return 0, 0, 0, 0
	}
	switch style {
	case borderHorizontal:
		return 1, 0, 1, 0
	case borderVertical:
		return 0, 1, 0, 1
	case borderTop:
		return 1, 0, 0, 0
	case borderBottom:
		return 0, 0, 1, 0
	case borderLeft:
		return 0, 0, 0, 1
	case borderRight:
		return 0, 1, 0, 0
	case borderLine:
		return 1, 0, 0, 0
	default:
		return 1, 1, 1, 1
	}
}

func shrinkRect(r rect, top, right, bottom, left int) rect {
	r.x += left
	r.y += top
	r.w -= left + right
	r.h -= top + bottom
	if r.w < 0 {
		r.w = 0
	}
	if r.h < 0 {
		r.h = 0
	}
	return r
}

// drawBorder draws a border around rect and returns the inner rect.
// label is drawn on the top border (or bottom when labelPos.bottom),
// positioned by labelPos (0 = center).
func (g *grid) drawBorder(r rect, cfg borderConfig, label string, lp labelPos, st cellStyle, labelStyle cellStyle, ambidouble bool, unicode bool) rect {
	if !cfg.present || cfg.style == borderNoneStyle || r.w == 0 || r.h == 0 {
		return r
	}
	top, right, bottom, left := borderInsets(cfg.style, true)
	ch := charsForBorder(cfg.style, unicode)
	hChar := ch.h
	if cfg.style == borderLine {
		hChar = '─'
		if !unicode {
			hChar = '-'
		}
	}
	// Horizontal edges.
	if top > 0 {
		for x := r.x; x < r.right(); x++ {
			g.set(x, r.y, hChar, st, ambidouble)
		}
	}
	if bottom > 0 && r.h > 1 {
		for x := r.x; x < r.right(); x++ {
			g.set(x, r.bottom()-1, hChar, st, ambidouble)
		}
	}
	if left > 0 {
		for y := r.y; y < r.bottom(); y++ {
			g.set(r.x, y, ch.v, st, ambidouble)
		}
	}
	if right > 0 && r.w > 1 {
		for y := r.y; y < r.bottom(); y++ {
			g.set(r.right()-1, y, ch.v, st, ambidouble)
		}
	}
	// Corners for full box styles.
	if top > 0 && left > 0 {
		g.set(r.x, r.y, ch.tl, st, ambidouble)
	}
	if top > 0 && right > 0 && r.w > 1 {
		g.set(r.right()-1, r.y, ch.tr, st, ambidouble)
	}
	if bottom > 0 && left > 0 && r.h > 1 {
		g.set(r.x, r.bottom()-1, ch.bl, st, ambidouble)
	}
	if bottom > 0 && right > 0 && r.w > 1 && r.h > 1 {
		g.set(r.right()-1, r.bottom()-1, ch.br, st, ambidouble)
	}
	if label != "" {
		ly := r.y
		useBottom := lp.bottom && bottom > 0
		if useBottom {
			ly = r.bottom() - 1
		}
		if top > 0 || useBottom {
			// Label is drawn with a leading and trailing space.
			text := " " + label + " "
			lw := stringDisplayWidth(text, ambidouble, 8)
			var lx int
			if lp.pos == 0 {
				lx = r.x + (r.w-lw)/2
			} else if lp.pos > 0 {
				lx = r.x + lp.pos
			} else {
				lx = r.right() + lp.pos - lw + 1
			}
			if lx < r.x {
				lx = r.x
			}
			g.drawText(lx, ly, r.right(), text, labelStyle, ambidouble, 8)
		}
	}
	return shrinkRect(r, top, right, bottom, left)
}

type inputBatch struct {
	lines []string
	done  bool
}

type finder struct {
	o          *options
	tty        *os.File
	savedTerm  *syscall.Termios
	altScreen  bool
	inline     bool
	termW      int
	termH      int
	winH       int // current finder window height (inline mode)
	cursorRow  int // cursor row within window after last draw
	cursorCol  int

	mu          sync.Mutex
	rawPending  []string
	items       []*item
	reading     bool
	inputDone   bool
	spinnerIdx  int

	query       []rune
	qcursor     int
	results     []*result
	current     int // index into results, -1 if none
	vOffset     int // visual scroll offset in display-order entries
	selected    map[int]bool
	excluded    map[int]bool
	searchOff   bool
	inputHidden bool
	sortOn      bool
	rawMode     bool
	trackOn     bool
	trackCur    bool
	headerText  string
	footerText  string
	headerHidden bool
	promptStr   string
	ghostStr    string
	pointerStr  string
	borderLabelStr string
	listLabelStr string
	inputLabelStr string
	headerLabelStr string
	footerLabelStr string
	previewLabelStr string
	nthOverride *[]fieldRange
	nthOverrideStr string
	nthRotateIdx map[string]int
	previewCmd  string
	previewCmdSet bool
	pw          previewWindow
	pwRotate    []previewWindow
	pwRotateIdx int
	pwRotateKey string
	previewHidden bool
	previewLines []previewLine
	previewScroll int
	previewFor   int // item index the preview was generated for, -1 none
	previewGen   int
	printQueue []string
	expectKey  string
	lastKey    string
	lastAction string
	killBuf    string
	historySavedQuery string
	historySavedSet bool
	jumpMode   bool
	jumpLabels map[rune]int // label rune -> visual index
	eventQueue []queuedAction
	inEvent    bool
	exitCode   int
	finished   bool
	acceptItems []*item
	becomeCmd  string
	execMu     sync.Mutex

	keymap      map[string][]action
	unboundStack map[string][]savedBinding
	// For change-nth rotation etc.
	rotateState map[string]int

	reloadCancel func()
	reloadGen    int

	previewCancel func()
	bgTransforms  map[int]func()
	bgGen         int

	mousePressX, mousePressY int
	mousePressValid bool
	lastClickTime time.Time
	lastClickX, lastClickY int
}

type savedBinding struct {
	actions []action
	present bool
}

type queuedAction struct {
	actions []action
	key     string
}

type previewLine struct {
	text string
	// ANSI SGR sequences per rune position are simplified to spans.
	spans []ansiSpan
}

func (f *finder) currentItem() *item {
	if f.current < 0 || f.current >= len(f.results) {
		return nil
	}
	return f.results[f.current].item
}

func (f *finder) selectedItemsInResultOrder() []*item {
	var out []*item
	for _, r := range f.results {
		if f.selected[r.item.index] {
			out = append(out, r.item)
		}
	}
	// Include selected items that are not in current results, in input order.
	if len(out) < len(f.selected) {
		inResults := map[int]bool{}
		for _, it := range out {
			inResults[it.index] = true
		}
		var rest []*item
		for _, it := range f.items {
			if f.selected[it.index] && !inResults[it.index] {
				rest = append(rest, it)
			}
		}
		out = append(out, rest...)
	}
	return out
}

func runTerminal(o *options, stdinIsTTY bool, preloaded []*item) int {
	// --tmux handling is done before the local terminal is opened when
	// we are inside tmux and not in filter mode.
	if o.tmux.present && os.Getenv("TMUX") != "" && os.Getenv("FZF_TMUX_POPUP") == "" {
		return runTmuxPopup(o)
	}
	tty, err := openTTYDevice(o)
	if err != nil {
		fmt.Fprintln(os.Stderr, "inappropriate ioctl for device")
		return 2
	}
	defer tty.Close()
	f := newFinder(o, tty)
	code := f.run(stdinIsTTY, preloaded)
	if f.becomeCmd != "" {
		// Restore the terminal (already done in f.run cleanup) and exec.
		cmd := f.becomeCmd
		shell := os.Getenv("SHELL")
		if shell == "" {
			shell = "sh"
		}
		if o.withShellSet {
			parts, _ := parseShellWords(o.withShell)
