	case borderDouble:
		return borderChars{'╔', '╗', '╚', '╝', '═', '║'}
	default:
		return borderChars{'┌', '┐', '└', '┘', '─', '│'}
	}
}

// borderInsets returns (top,right,bottom,left) cells consumed by a border.
func borderInsets(style borderStyle, present bool) (int, int, int, int) {
	if !present || style == borderNoneStyle {
		return 0, 0, 0, 0
	}
	switch style {
	case borderHorizontal:
		return 1, 0, 1, 0
	case borderVertical:
		return 0, 1, 0, 1
	case borderTop:
		return 1, 0, 0, 0
	case borderBottom:
		return 0, 0, 1, 0
	case borderLeft:
		return 0, 0, 0, 1
	case borderRight:
		return 0, 1, 0, 0
	case borderLine:
		return 1, 0, 0, 0
	default:
		return 1, 1, 1, 1
	}
}

func shrinkRect(r rect, top, right, bottom, left int) rect {
	r.x += left
	r.y += top
	r.w -= left + right
	r.h -= top + bottom
	if r.w < 0 {
		r.w = 0
	}
	if r.h < 0 {
		r.h = 0
	}
	return r
}

// drawBorder draws a border around rect and returns the inner rect.
// label is drawn on the top border (or bottom when labelPos.bottom),
// positioned by labelPos (0 = center).
func (g *grid) drawBorder(r rect, cfg borderConfig, label string, lp labelPos, st cellStyle, labelStyle cellStyle, ambidouble bool, unicode bool) rect {
	if !cfg.present || cfg.style == borderNoneStyle || r.w == 0 || r.h == 0 {
		return r
	}
	top, right, bottom, left := borderInsets(cfg.style, true)
	ch := charsForBorder(cfg.style, unicode)
	hChar := ch.h
	if cfg.style == borderLine {
		hChar = '─'
		if !unicode {
			hChar = '-'
		}
	}
	// Horizontal edges.
	if top > 0 {
		for x := r.x; x < r.right(); x++ {
			g.set(x, r.y, hChar, st, ambidouble)
		}
	}
	if bottom > 0 && r.h > 1 {
		for x := r.x; x < r.right(); x++ {
			g.set(x, r.bottom()-1, hChar, st, ambidouble)
		}
	}
	if left > 0 {
		for y := r.y; y < r.bottom(); y++ {
			g.set(r.x, y, ch.v, st, ambidouble)
		}
	}
	if right > 0 && r.w > 1 {
		for y := r.y; y < r.bottom(); y++ {
			g.set(r.right()-1, y, ch.v, st, ambidouble)
		}
	}
	// Corners for full box styles.
	if top > 0 && left > 0 {
		g.set(r.x, r.y, ch.tl, st, ambidouble)
	}
	if top > 0 && right > 0 && r.w > 1 {
		g.set(r.right()-1, r.y, ch.tr, st, ambidouble)
	}
	if bottom > 0 && left > 0 && r.h > 1 {
		g.set(r.x, r.bottom()-1, ch.bl, st, ambidouble)
	}
	if bottom > 0 && right > 0 && r.w > 1 && r.h > 1 {
		g.set(r.right()-1, r.bottom()-1, ch.br, st, ambidouble)
	}
	if label != "" {
		ly := r.y
		useBottom := lp.bottom && bottom > 0
		if useBottom {
			ly = r.bottom() - 1
		}
		if top > 0 || useBottom {
			// Label is drawn with a leading and trailing space.
			text := " " + label + " "
			lw := stringDisplayWidth(text, ambidouble, 8)
			var lx int
			if lp.pos == 0 {
				lx = r.x + (r.w-lw)/2
			} else if lp.pos > 0 {
				lx = r.x + lp.pos
			} else {
				lx = r.right() + lp.pos - lw + 1
			}
			if lx < r.x {
				lx = r.x
			}
			g.drawText(lx, ly, r.right(), text, labelStyle, ambidouble, 8)
		}
	}
	return shrinkRect(r, top, right, bottom, left)
}

