func (f *finder) currentItem() *item {
	if f.current < 0 || f.current >= len(f.results) {
		return nil
	}
	return f.results[f.current].item
}

func (f *finder) selectedItemsInResultOrder() []*item {
	var out []*item
	for _, r := range f.results {
		if f.selected[r.item.index] {
			out = append(out, r.item)
		}
	}
	// Include selected items that are not in current results, in input order.
	if len(out) < len(f.selected) {
		inResults := map[int]bool{}
		for _, it := range out {
			inResults[it.index] = true
		}
		var rest []*item
		for _, it := range f.items {
			if f.selected[it.index] && !inResults[it.index] {
				rest = append(rest, it)
			}
		}
		out = append(out, rest...)
	}
	return out
}

func runTerminal(o *options, stdinIsTTY bool, preloaded []*item) int {
	// --tmux handling is done before the local terminal is opened when
	// we are inside tmux and not in filter mode.
	if o.tmux.present && os.Getenv("TMUX") != "" && os.Getenv("FZF_TMUX_POPUP") == "" {
		return runTmuxPopup(o)
	}
	tty, err := openTTYDevice(o)
	if err != nil {
		fmt.Fprintln(os.Stderr, "inappropriate ioctl for device")
		return 2
	}
	defer tty.Close()
	f := newFinder(o, tty)
	code := f.run(stdinIsTTY, preloaded)
	if f.becomeCmd != "" {
		// Restore the terminal (already done in f.run cleanup) and exec.
		cmd := f.becomeCmd
		shell := os.Getenv("SHELL")
		if shell == "" {
			shell = "sh"
		}
		if o.withShellSet {
			parts, _ := parseShellWords(o.withShell)
			if len(parts) > 0 {
				argv := append(append([]string{}, parts...), cmd)
				_ = syscall.Exec(argv[0], argv, os.Environ())
				return 126
			}
		}
		_ = syscall.Exec(shell, []string{shell, "-c", cmd}, os.Environ())
		return 126
	}
	return code
}

func newFinder(o *options, tty *os.File) *finder {
	f := &finder{
		o:            o,
		tty:          tty,
		current:      -1,
		selected:     map[int]bool{},
		excluded:     map[int]bool{},
		searchOff:    o.disabled,
		inputHidden:  o.noInput,
		sortOn:       o.sort,
		rawMode:      o.raw,
		trackOn:      o.track,
		headerText:   o.header,
		footerText:   o.footer,
		promptStr:    o.prompt,
		ghostStr:     o.ghost,
		pointerStr:   o.pointer,
		borderLabelStr: o.borderLabel,
		listLabelStr: o.listLabel,
		inputLabelStr: o.inputLabel,
		headerLabelStr: o.headerLabel,
		footerLabelStr: o.footerLabel,
		previewLabelStr: o.previewLabel,
		previewCmd:   o.preview,
		previewCmdSet: o.previewSet,
		pw:           o.previewWindow,
		previewFor:   -2,
		rotateState:  map[string]int{},
		nthRotateIdx: map[string]int{},
		bgTransforms: map[int]func(){},
		mousePressX:  -1,
		mousePressY:  -1,
	}
	f.previewHidden = o.previewWindow.hidden
	f.query = []rune(o.query)
	f.qcursor = len(f.query)
	if o.filter != nil {
		f.query = []rune(*o.filter)
		f.qcursor = len(f.query)
	}
	f.buildKeymap()
	return f
}

func (f *finder) pointer() string {
	if f.pointerStr != "" || f.o.pointerSet {
		return f.pointerStr
	}
	if f.o.unicode {
		return "▌"
	}
	return ">"
}

func (f *finder) gutterChar(raw bool) string {
	if raw {
		if f.o.gutterRawSet {
			return f.o.gutterRaw
		}
		if f.o.unicode {
			return "▖"
		}
		return f.gutterOrDefault()
	}
	return f.gutterOrDefault()
}

func (f *finder) gutterOrDefault() string {
	if f.o.gutterSet {
		return f.o.gutter
	}
	if f.o.unicode {
		return "▌"
	}
	return ">"
}

func (f *finder) markerStr() string {
	if f.o.markerSet {
		return f.o.marker
	}
	if f.o.unicode {
		return "┃"
	}
	return ">"
}

func (f *finder) isReading() bool {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.reading
}

