package main

import (
	"strings"
)

type sections struct {
	outer   rect
	content rect
	list    rect
	preview rect
	hasPreview bool
	input   rect
	hasInput bool
	header  rect
	hasHeader bool
	footer  rect
	hasFooter bool
	// Section border inner rects (after drawing each section's border).
	listInner    rect
	inputInner   rect
	headerInner  rect
	footerInner  rect
	previewInner rect
	// The rects including borders, retained for drawing.
	listBox    rect
	inputBox   rect
	headerBox  rect
	footerBox  rect
	previewBox rect
	infoRow    int // y of the info line within the input section (or -1)
	promptRow  int
	listCapacity int
}

func sizeToCells(spec sizeSpec, total int) int {
	if spec.percent {
		return int(float64(total) * spec.num / 100.0)
	}
	return int(spec.num)
}

func (f *finder) finderHeight(termH int, needed int) int {
	o := f.o
	if !o.heightSet {
		return termH
	}
	h := o.height
	var v int
	if h.percent {
		if h.num >= 0 {
			v = int(float64(termH) * h.num / 100.0)
		} else {
			v = termH - int(float64(termH)*(-h.num)/100.0)
		}
		// Minimum height applies to percentage heights.
		minH := f.effectiveMinHeight()
		if v < minH {
			v = minH
		}
	} else {
		if h.num >= 0 {
			v = int(h.num)
		} else {
			v = termH + int(h.num)
		}
	}
	if h.auto {
		if needed < v {
			v = needed
		}
		if v < 1 {
			v = 1
		}
	}
	if v > termH {
		v = termH
	}
	if v < 1 {
		v = 1
	}
	return v
}

// effectiveMinHeight returns the minimum total window height for a
// percentage --height, including (with '+') the rows taken by sections
// other than the list.
func (f *finder) effectiveMinHeight() int {
	base := f.o.minHeight
	if !f.o.minHeightAuto {
		return base
	}
	extra := f.nonListRows()
	return base + extra
}

func (f *finder) nonListRows() int {
	// Rows outside the list in the finder-main column: info+prompt (or
	// a single input row), header, footer, main border and padding.
	rows := 0
	if !f.inputHidden {
		rows += f.inputSectionRows()
	}
	if f.headerVisible() {
		rows += f.headerRows() + f.headerBorderRows()
	}
	if f.footerText != "" {
		rows += len(strings.Split(strings.TrimRight(f.footerText, "\n"), "\n"))
		t, _, b, _ := borderInsets(f.footerBorderStyle(), true)
		rows += t + b
	}
	t, _, b, _ := borderInsets(f.o.border.style, f.o.border.present)
	rows += t + b
	rows += int(f.o.margin[0].num) + int(f.o.margin[2].num)
	rows += int(f.o.padding[0].num) + int(f.o.padding[2].num)
	// List/input section borders.
	if f.o.listBorder.present {
		t, _, b, _ := borderInsets(f.o.listBorder.style, true)
		rows += t + b
	}
	if f.o.inputBorder.present {
		t, _, b, _ := borderInsets(f.o.inputBorder.style, true)
		rows += t + b
	}
	return rows
}

func (f *finder) footerBorderStyle() borderStyle {
	if f.o.footerBorder.present {
		return f.o.footerBorder.style
	}
	return borderLine
}

func (f *finder) inputSectionRows() int {
	if f.inputHidden {
		return 0
	}
	rows := 1 // prompt
	switch f.o.info {
	case infoDefault:
		rows++
	}
	return rows
}

func (f *finder) headerVisible() bool {
	return !f.headerHidden && (f.headerText != "" || len(f.headerLinesItems()) > 0)
}

func (f *finder) headerLinesItems() []string {
	if f.o.headerLines <= 0 {
		return nil
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if len(f.headerLineTexts) > 0 {
		return f.headerLineTexts
	}
	return nil
}

func (f *finder) headerRows() int {
	n := 0
	if f.headerText != "" {
		n += len(strings.Split(strings.TrimRight(f.headerText, "\n"), "\n"))
	}
	n += len(f.headerLinesItems())
	return n
}

func (f *finder) headerBorderRows() int {
	rows := 0
	if f.o.headerBorder.present {
		t, _, b, _ := borderInsets(f.o.headerBorder.style, true)
		rows += t + b
	}
	if f.o.headerLinesBorderSet {
		t, _, b, _ := borderInsets(f.o.headerLinesBorder.style, f.o.headerLinesBorder.present || f.o.headerLinesBorder.style == borderNoneStyle)
		// "none" still separates the header but without a drawn border.
		rows += t + b
	}
	return rows
}

func (f *finder) neededHeight(termH int) int {
	// For adaptive height: list rows needed plus the rest.
	list := len(f.results)
	if f.rawMode {
		list = len(f.items)
	}
	gapExtra := 0
	if list > 1 {
		gapExtra = (list - 1) * f.o.gap
	}
	needed := list + gapExtra + f.nonListRows()
	if pv := f.previewLayoutEffective(); pv.position == previewUp || pv.position == previewDown {
		// Preview takes a fraction; adaptive height with such previews
		// simply uses the full requested size in the reference, so keep needed high.
		needed = termH
	}
	if needed < 1 {
		needed = 1
	}
	return needed
}

func (f *finder) previewLayoutEffective() previewLayout {
	pw := f.pw
	for _, alt := range pw.alts {
		// An alternative applies when the relevant terminal dimension is
		// below its threshold.  The reference compares width for
		// side layouts and height for stacked ones; we compare both
		// width and height conservatively by position of the *current*
		// (pre-alternative) layout.
		dim := f.termW
		if pw.position == previewUp || pw.position == previewDown {
			dim = f.termH
		}
		if dim < alt.threshold {
			return alt.layout
		}
	}
	return pw.previewLayout
}

func (f *finder) previewActive() bool {
	if f.previewHidden {
		return false
	}
	return f.previewCmdSet || f.previewCmd != "" || f.hasPreviewBinding
}

func (f *finder) computeSections(termW, termH, winH int) sections {
	var s sections
	o := f.o
	outer := rect{0, 0, termW, winH}
	// Margins.
	mt := sizeToCells(o.margin[0], termH)
	mr := sizeToCells(o.margin[1], termW)
	mb := sizeToCells(o.margin[2], termH)
	ml := sizeToCells(o.margin[3], termW)
	outer = shrinkRect(outer, mt, mr, mb, ml)
	s.outer = outer
	content := outer
	// Main border insets are applied when drawing; compute content now.
	bt, br, bb, bl := borderInsets(o.border.style, o.border.present)
	content = shrinkRect(content, bt, br, bb, bl)
	// Padding.
	pt := sizeToCells(o.padding[0], content.h+bt+bb)
	pr := sizeToCells(o.padding[1], content.w+bl+br)
	pb := sizeToCells(o.padding[2], content.h+bt+bb)
	pl := sizeToCells(o.padding[3], content.w+bl+br)
	content = shrinkRect(content, pt, pr, pb, pl)
	s.content = content

	// Reserve preview area.
	mainRect := content
	if f.previewActive() {
		pv := f.previewLayoutEffective()
		switch pv.position {
		case previewRight:
			w := sizeToCells(pv.size, content.w)
			if w < 1 {
				w = 1
			}
			if w >= content.w {
				w = content.w - 1
			}
			s.preview = rect{content.right() - w, content.y, w, content.h}
			mainRect = rect{content.x, content.y, content.w - w, content.h}
			s.hasPreview = true
		case previewLeft:
			w := sizeToCells(pv.size, content.w)
			if w < 1 {
				w = 1
			}
			if w >= content.w {
				w = content.w - 1
			}
			s.preview = rect{content.x, content.y, w, content.h}
			mainRect = rect{content.x + w, content.y, content.w - w, content.h}
			s.hasPreview = true
		case previewUp:
			h := sizeToCells(pv.size, content.h)
			if h < 1 {
				h = 1
			}
			if h >= content.h {
				h = content.h - 1
			}
			s.preview = rect{content.x, content.y, content.w, h}
			mainRect = rect{content.x, content.y + h, content.w, content.h - h}
			s.hasPreview = true
		case previewDown:
			h := sizeToCells(pv.size, content.h)
			if h < 1 {
				h = 1
			}
			if h >= content.h {
				h = content.h - 1
			}
			s.preview = rect{content.x, content.bottom() - h, content.w, h}
			mainRect = rect{content.x, content.y, content.w, content.h - h}
			s.hasPreview = true
		}
	}

	// Within mainRect, allocate bands.
	inputRows := f.inputSectionRows()
	headerRows := 0
	if f.headerVisible() {
		headerRows = f.headerRows()
	}
	headerBorderRows := 0
	if f.headerVisible() {
		headerBorderRows = f.headerBorderRows()
	}
	footerRows := 0
	footerBorderRows := 0
	if f.footerText != "" {
		footerRows = len(strings.Split(strings.TrimRight(f.footerText, "\n"), "\n"))
		t, _, b, _ := borderInsets(f.footerBorderStyle(), true)
		footerBorderRows = t + b
	}
	listBorderT, _, listBorderB, _ := borderInsets(o.listBorder.style, o.listBorder.present)
	inputBorderT, _, inputBorderB, _ := borderInsets(o.inputBorder.style, o.inputBorder.present)
	inputTotal := inputRows + inputBorderT + inputBorderB
	headerTotal := headerRows + headerBorderRows
	footerTotal := footerRows + footerBorderRows

	reverse := o.layout == layoutReverse
	if reverse {
		y := mainRect.y
		if o.headerFirst && headerTotal > 0 {
			s.headerBox = rect{mainRect.x, y, mainRect.w, headerTotal}
			s.hasHeader = true
			y += headerTotal
		}
		if inputTotal > 0 {
			s.inputBox = rect{mainRect.x, y, mainRect.w, inputTotal}
			s.hasInput = true
			y += inputTotal
		}
		if !o.headerFirst && headerTotal > 0 {
			s.headerBox = rect{mainRect.x, y, mainRect.w, headerTotal}
			s.hasHeader = true
			y += headerTotal
		}
		listH := mainRect.bottom() - y - footerTotal
		if listH < 0 {
			listH = 0
		}
		s.listBox = rect{mainRect.x, y, mainRect.w, listH}
		if footerTotal > 0 {
			s.footerBox = rect{mainRect.x, mainRect.bottom() - footerTotal, mainRect.w, footerTotal}
			s.hasFooter = true
		}
	} else {
		// default / reverse-list: input at the bottom.
		yBottom := mainRect.bottom()
		if o.headerFirst && headerTotal > 0 {
			yBottom -= headerTotal
			s.headerBox = rect{mainRect.x, yBottom, mainRect.w, headerTotal}
			s.hasHeader = true
		}
		if inputTotal > 0 {
			yBottom -= inputTotal
			s.inputBox = rect{mainRect.x, yBottom, mainRect.w, inputTotal}
			s.hasInput = true
		}
		if !o.headerFirst && headerTotal > 0 {
			yBottom -= headerTotal
			s.headerBox = rect{mainRect.x, yBottom, mainRect.w, headerTotal}
			s.hasHeader = true
		}
		listTop := mainRect.y + footerTotal
		listH := yBottom - listTop
		if listH < 0 {
			listH = 0
		}
		s.listBox = rect{mainRect.x, listTop, mainRect.w, listH}
		if footerTotal > 0 {
			s.footerBox = rect{mainRect.x, mainRect.y, mainRect.w, footerTotal}
			s.hasFooter = true
		}
	}

	// Inner rects after section borders.
	s.listInner = shrinkRect(s.listBox, listBorderT, sectionBorderSide(o.listBorder, true), listBorderB, sectionBorderSide(o.listBorder, false))
	s.list = s.listInner
	s.inputInner = shrinkRect(s.inputBox, inputBorderT, sectionBorderSide(o.inputBorder, true), inputBorderB, sectionBorderSide(o.inputBorder, false))
	s.input = s.inputInner
	if s.hasHeader {
		ht, _, hb, _ := borderInsets(o.headerBorder.style, o.headerBorder.present)
		s.headerInner = shrinkRect(s.headerBox, ht, sectionBorderSide(o.headerBorder, true), hb, sectionBorderSide(o.headerBorder, false))
		s.header = s.headerInner
	}
	if s.hasFooter {
		ft, _, fb, _ := borderInsets(f.footerBorderStyle(), true)
		s.footerInner = shrinkRect(s.footerBox, ft, 0, fb, 0)
		s.footer = s.footerInner
	}
	if s.hasPreview {
		pv := f.previewLayoutEffective()
		s.previewBox = s.preview
		pt2, pr2, pb2, pl2 := borderInsets(pv.border, true)
		if !pv.borderSet && pv.border == borderNoneStyle {
			pt2, pr2, pb2, pl2 = 0, 0, 0, 0
		}
		s.previewInner = shrinkRect(s.preview, pt2, pr2, pb2, pl2)
	}
	// Prompt/info rows inside the input inner rect.
	s.infoRow = -1
	s.promptRow = -1
	if s.hasInput {
		if reverse {
			s.promptRow = s.inputInner.y
			if f.o.info == infoDefault && inputRows > 1 {
				s.infoRow = s.inputInner.y + 1
			}
		} else {
			s.promptRow = s.inputInner.bottom() - 1
			if f.o.info == infoDefault && inputRows > 1 {
				s.infoRow = s.inputInner.bottom() - 2
			}
		}
	}
	s.listCapacity = f.listCapacityFor(s.listInner.h)
	return s
}

func sectionBorderSide(cfg borderConfig, right bool) int {
	_, r, _, l := borderInsets(cfg.style, cfg.present)
	if right {
		return r
	}
	return l
}

func (f *finder) listCapacityFor(heightRows int) int {
	if heightRows <= 0 {
		return 0
	}
	if f.o.gap <= 0 {
		return heightRows
	}
	// Items are separated by gap rows: n items take n + (n-1)*gap rows.
	n := (heightRows + f.o.gap) / (1 + f.o.gap)
	return n
}
