package main

import (
	"fmt"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"
)

func (f *finder) run(stdinIsTTY bool, preloaded []*item) int {
	o := f.o
	// Dimension query first.
	w, h, err := getWinsize(f.tty.Fd())
	if err != nil {
		fmt.Fprintln(os.Stderr, "inappropriate ioctl for device")
		return 2
	}
	f.termW, f.termH = w, h
	saved, err := getTermios(f.tty.Fd())
	if err != nil {
		fmt.Fprintln(os.Stderr, "inappropriate ioctl for device")
		return 2
	}
	f.savedTerm = saved
	raw := *saved
	makeRaw(&raw)
	if err := setTermios(f.tty.Fd(), &raw); err != nil {
		fmt.Fprintln(os.Stderr, "inappropriate ioctl for device")
		return 2
	}
	restored := false
	restore := func() {
		if restored {
			return
		}
		restored = true
		f.leaveScreen()
		_ = setTermios(f.tty.Fd(), saved)
	}
	defer restore()

	f.enterScreen()
	f.mu.Lock()
	f.reading = preloaded == nil
	f.mu.Unlock()

	// Channels.
	itemCh := make(chan string, 4096)
	itemDone := make(chan struct{})
	keyBytes := make(chan []byte, 64)
	keyErr := make(chan struct{})
	previewCh := make(chan previewResult, 16)
	f.previewCh = previewCh
	sigCh := make(chan os.Signal, 8)
	signal.Notify(sigCh, syscall.SIGWINCH, syscall.SIGTERM, syscall.SIGINT)
	defer signal.Stop(sigCh)

	// Input producer.
	var inputWait func()
	if preloaded != nil {
		f.items = preloaded
		f.refilter(true)
		close(itemDone)
	} else {
		ch, wait := startInput(o, stdinIsTTY)
		inputWait = wait
		f.reloadCancel = func() {}
		go func() {
			headerLeft := o.headerLines
			for line := range ch {
				if headerLeft > 0 {
					headerLeft--
					f.mu.Lock()
					txt := line
					if o.ansi {
						txt, _ = stripAnsi(line)
					}
					f.headerLineTexts = append(f.headerLineTexts, txt)
					f.mu.Unlock()
					continue
				}
				itemCh <- line
			}
			close(itemDone)
		}()
		_ = inputWait
	}

	// Key reader goroutine.
	go func() {
		buf := make([]byte, 4096)
		for {
			n, err := f.tty.Read(buf)
			if n > 0 {
				cp := make([]byte, n)
				copy(cp, buf[:n])
				keyBytes <- cp
			}
			if err != nil {
				close(keyErr)
				return
			}
		}
	}()

	// Optional HTTP listen server.
	var httpCh chan []action
	if o.listen.present {
		httpCh = make(chan []action, 16)
		f.startHTTPServer(httpCh)
	}

	f.refilter(true)
	f.fireEvent("start")
	if f.processQueuedEvents() {
		return f.finish(restore)
	}
	f.draw()

	// If the input was already complete at start (preloaded), the load
	// event fires after the first draw.
	loaded := false
	if preloaded != nil {
		loaded = true
		f.fireEvent("load")
		if f.processQueuedEvents() {
			return f.finish(restore)
		}
		f.draw()
	}

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	var decodeBuf []byte
	var escTimer *time.Timer
	var escTimerCh <-chan time.Time
	stopEscTimer := func() {
		if escTimer != nil {
			escTimer.Stop()
			escTimer = nil
			escTimerCh = nil
		}
	}
	resultFired := false
	maybeFireResult := func() {
		if resultFired {
			return
		}
		// `result` fires after the initial filtering completes.
	}
	_ = maybeFireResult
	for !f.finished {
		select {
		case line, ok := <-itemCh:
			if !ok {
				itemCh = nil
				continue
			}
			f.addRawItem(line)
			// Drain available items without blocking to batch refilters.
			drained := false
			for !drained {
				select {
				case l2 := <-itemCh:
					f.addRawItem(l2)
				default:
					drained = true
				}
			}
			f.refilter(false)
			f.maybeFireOneZero()
			if f.processQueuedEvents() {
				break
			}
			f.draw()
		case <-itemDone:
			itemDone = nil
			f.mu.Lock()
			f.reading = false
			f.inputDone = true
			f.mu.Unlock()
			// Apply tail limiting once at the end as well (addRawItem
			// already enforces it incrementally).
			f.refilter(false)
			if !loaded {
				loaded = true
				f.fireEvent("load")
			}
			f.maybeFireOneZero()
			if f.processQueuedEvents() {
				break
			}
			f.draw()
			// With --sync, start/load/result/focus actions have been
			// processed above before any terminal interaction was
			// possible (they run in this same goroutine).
			resultFired = true
		case data := <-keyBytes:
			decodeBuf = append(decodeBuf, data...)
			events, consumed := decodeKeys(decodeBuf)
			decodeBuf = decodeBuf[consumed:]
			if len(decodeBuf) > 0 {
				stopEscTimer()
				escTimer = time.NewTimer(40 * time.Millisecond)
				escTimerCh = escTimer.C
			} else {
				stopEscTimer()
			}
			for _, ev := range events {
				f.handleKey(ev)
				if f.finished {
					break
				}
			}
			if !f.finished {
				f.draw()
			}
		case <-escTimerCh:
			escTimer = nil
			escTimerCh = nil
			if len(decodeBuf) > 0 {
				for _, ev := range flushEscape(decodeBuf) {
					f.handleKey(ev)
					if f.finished {
						break
					}
				}
				decodeBuf = nil
			}
			if !f.finished {
				f.draw()
			}
		case pr := <-previewCh:
			f.applyPreviewResult(pr)
			f.draw()
		case acts := <-httpChOrNil(httpCh):
			f.executeActions(acts, "")
			if !f.finished {
				f.draw()
			}
		case sig := <-sigCh:
			if sig == syscall.SIGWINCH {
				nw, nh, err := getWinsize(f.tty.Fd())
				if err == nil {
					f.termW, f.termH = nw, nh
				}
				f.fireEvent("resize")
				if f.processQueuedEvents() {
					break
				}
				f.draw()
			} else {
				f.exitCode = 130
				f.finished = true
			}
		case <-keyErr:
			f.exitCode = 130
			f.finished = true
		case <-ticker.C:
			if f.isReading() {
				f.spinnerIdx++
				f.draw()
			}
			if f.o.infoCommand != "" {
				f.draw()
			}
		}
	}
	return f.finish(restore)
}

func httpChOrNil(ch chan []action) chan []action { return ch }

func (f *finder) finish(restore func()) int {
	// Print the accept output after leaving the screen.
	selected := f.acceptItems
	code := f.exitCode
	become := f.becomeCmd
	restore()
	if become != "" {
		return code
	}
	if code == 0 {
		printAcceptOutput(f.o, string(f.query), true, f.expectKey, selected)
		if f.o.history != nil {
			f.o.history.append(string(f.query), f.o.historySize)
		}
	} else if code == 1 {
		// No-match style exits still honor --print-query/--expect lines
		// when they come from accept-or-print-query / exit-0 style
		// paths; abort (130) does not print anything.
		if f.printOnNoMatch {
			printAcceptOutput(f.o, string(f.query), true, f.expectKey, selected)
		}
	}
	return code
}

func (f *finder) addRawItem(raw string) {
	f.mu.Lock()
	idx := f.nextIndex
	f.nextIndex++
	f.mu.Unlock()
	orig := raw
	var spans []ansiSpan
	if f.o.ansi {
		orig, spans = stripAnsi(raw)
	}
	text := orig
	if f.o.withNth != nil {
		text = transformBySpec(orig, idx, f.o.delim, f.o.withNth)
	}
	it := &item{orig: orig, rawOrig: raw, text: text, index: idx, ansiColors: spans}
	f.mu.Lock()
	f.items = append(f.items, it)
	if f.o.tail > 0 && len(f.items) > f.o.tail {
		f.items = append([]*item{}, f.items[len(f.items)-f.o.tail:]...)
	}
	f.mu.Unlock()
}

func (f *finder) maybeFireOneZero() {
	// one/zero events fire when the count transitions into 1 / 0.
	n := len(f.results)
	if f.o.raw {
		cnt := 0
		for _, r := range f.results {
			if r.matched {
				cnt++
			}
		}
		n = cnt
	}
	if n == 1 && !f.firedOne {
		f.firedOne = true
		f.firedZero = false
		f.fireEvent("one")
	} else if n == 0 && !f.firedZero {
		f.firedZero = true
		f.firedOne = false
		f.fireEvent("zero")
	} else if n > 1 {
		f.firedOne = false
		f.firedZero = false
	}
}

func (f *finder) fireEvent(name string) {
	if acts, ok := f.keymap[name]; ok && len(acts) > 0 {
		f.eventQueue = append(f.eventQueue, queuedAction{actions: append([]action{}, acts...), key: name})
	}
}

// processQueuedEvents runs queued event actions; returns true if finished.
func (f *finder) processQueuedEvents() bool {
	if f.inEvent {
		return f.finished
	}
	f.inEvent = true
	for len(f.eventQueue) > 0 && !f.finished {
		q := f.eventQueue[0]
		f.eventQueue = f.eventQueue[1:]
		f.executeActions(q.actions, q.key)
	}
	f.inEvent = false
	return f.finished
}

func (f *finder) enterScreen() {
	o := f.o
	fullscreen := !o.heightSet && !o.tmux.present
	f.altScreen = fullscreen && o.clearOnExit
	f.inline = !f.altScreen
	var b strings.Builder
	if f.altScreen {
		b.WriteString("\x1b[?1049h")
	}
	b.WriteString("\x1b[?7l")
	b.WriteString("\x1b[?25l")
	if o.mouse {
		b.WriteString("\x1b[?1000h\x1b[?1002h\x1b[?1006h")
	}
	b.WriteString("\x1b[?2004h")
	if f.inline && !fullscreen {
		// Height mode: reserve lines below the cursor.
		f.winH = f.finderHeight(f.termH, f.neededHeight(f.termH))
		if f.winH > 1 {
			b.WriteString(strings.Repeat("\n", f.winH-1))
			b.WriteString(fmt.Sprintf("\x1b[%dA", f.winH-1))
		}
		b.WriteString("\r")
	} else if f.inline && fullscreen {
		// Fullscreen without alternate screen (--no-clear): clear.
		b.WriteString("\x1b[2J\x1b[H")
		f.winH = f.termH
	} else {
		f.winH = f.termH
	}
	_, _ = f.tty.WriteString(b.String())
}

func (f *finder) leaveScreen() {
	var b strings.Builder
	if f.altScreen {
		b.WriteString("\x1b[1;1H")
		// Mouse off, bracketed paste off happen after leaving alt.
	}
	if f.o.clearOnExit && f.inline {
		// Move to the top of the window and clear it.
		if f.cursorRow > 0 {
			b.WriteString(fmt.Sprintf("\x1b[%dA", f.cursorRow))
		}
		b.WriteString("\r\x1b[J")
	}
	if !f.o.clearOnExit && f.inline && f.o.heightSet {
		// Move back to the top of the inline window.
		if f.cursorRow > 0 {
			b.WriteString(fmt.Sprintf("\x1b[%dA", f.cursorRow))
		}
		b.WriteString("\r")
	}
	b.WriteString("\x1b[?1000l\x1b[?1002l\x1b[?1006l\x1b[?2004l")
	if f.altScreen {
		b.WriteString("\x1b[?1049l")
	}
	b.WriteString("\x1b[?25h\x1b[?7h")
	_, _ = f.tty.WriteString(b.String())
}

func (f *finder) suspendScreen() {
	// Used before running an interactive execute() command.
	var b strings.Builder
	b.WriteString("\x1b[?25h")
	if f.altScreen {
		b.WriteString("\x1b[?1049l")
	} else if f.inline {
		// Move below the window.
		down := f.winH - 1 - f.cursorRow
		if down > 0 {
			b.WriteString(fmt.Sprintf("\x1b[%dB", down))
		}
		b.WriteString("\r\n")
	}
	b.WriteString("\x1b[?1000l\x1b[?1002l\x1b[?1006l\x1b[?2004l\x1b[?7h")
	_, _ = f.tty.WriteString(b.String())
	_ = setTermios(f.tty.Fd(), f.savedTerm)
}

func (f *finder) resumeScreen() {
	raw := *f.savedTerm
	makeRaw(&raw)
	_ = setTermios(f.tty.Fd(), &raw)
	var b strings.Builder
	if f.altScreen {
		b.WriteString("\x1b[?1049h")
	}
	b.WriteString("\x1b[?7l\x1b[?25l")
	if f.o.mouse {
		b.WriteString("\x1b[?1000h\x1b[?1002h\x1b[?1006h")
	}
	b.WriteString("\x1b[?2004h")
	if f.inline && !f.altScreen {
		if f.winH > 1 {
			b.WriteString(strings.Repeat("\n", f.winH-1))
			b.WriteString(fmt.Sprintf("\x1b[%dA", f.winH-1))
		}
		b.WriteString("\r")
	}
	_, _ = f.tty.WriteString(b.String())
	f.cursorRow = 0
	f.cursorCol = 0
}
