func (f *finder) themeBase() string {
	t := f.o.theme
	if t != nil && t.base != "" {
		return t.base
	}
	// (Actual selection happens in resolveThemeBase at draw time.)
	return ""
}

func (f *finder) resolvedTheme() *theme {
	th := f.o.theme
	if th == nil {
		th = defaultTheme()
		f.o.theme = th
	}
	if th.base == "" {
		th.base = f.defaultBaseScheme()
	}
	return th
}

func (f *finder) defaultBaseScheme() string {
	if f.o.noColorSet {
		return "bw"
	}
	if _, ok := lookupEnvNoColor(); ok {
		return "bw"
	}
	term := getEnv("TERM")
	ct := getEnv("COLORTERM")
	if is256Term(term) || ct == "truecolor" || ct == "24bit" {
		return "dark"
	}
	return "base16"
}

func getEnv(k string) string {
	return envValue(k)
}

func (f *finder) draw() {
	if f.tty == nil {
		return
	}
	// Keep the adaptive height window size current in inline mode.
	if f.o.heightSet && f.o.height.auto {
		need := f.neededHeight(f.termH)
		nh := f.finderHeight(f.termH, need)
		if nh != f.winH {
			f.adjustInlineHeight(nh)
		}
	}
	winH := f.winH
	if !f.inline || !f.o.heightSet {
		winH = f.termH
		f.winH = winH
	}
	rows, curX, curY := f.buildFrame(f.termW, winH)
	var b strings.Builder
	b.WriteString("\x1b[?25l")
	// Move to window top-left.
	if f.altScreen {
		b.WriteString("\x1b[1;1H")
	} else {
		if f.cursorRow > 0 {
			b.WriteString(fmt.Sprintf("\x1b[%dA", f.cursorRow))
		}
		b.WriteString("\r")
	}
	for i, row := range rows {
		if i > 0 {
			b.WriteString("\x1b[1B\r")
		}
		b.WriteString("\x1b[2K")
		b.WriteString(renderRowANSI(row.spans, f.termW, f.o.ambidouble, f.o.tabstop, f.o.noBold))
	}
	// Move to cursor position.
	lastRow := len(rows) - 1
	if lastRow < 0 {
		lastRow = 0
	}
	if curY < lastRow {
		b.WriteString(fmt.Sprintf("\x1b[%dA", lastRow-curY))
	} else if curY > lastRow {
		b.WriteString(fmt.Sprintf("\x1b[%dB", curY-lastRow))
	}
	b.WriteString("\r")
	if curX > 0 {
		b.WriteString(fmt.Sprintf("\x1b[%dC", curX))
	}
	b.WriteString("\x1b[?25h")
	_, _ = f.tty.WriteString(b.String())
	f.cursorRow = curY
	f.cursorCol = curX
	// Trigger a preview update for the current item.
	f.maybeUpdatePreview()
}

func (f *finder) adjustInlineHeight(newH int) {
	oldH := f.winH
	if newH == oldH {
		return
	}
	var b strings.Builder
	// Move to the bottom of the current window first.
	if f.cursorRow < oldH-1 {
		b.WriteString(fmt.Sprintf("\x1b[%dB", oldH-1-f.cursorRow))
	}
	if newH > oldH {
		b.WriteString(strings.Repeat("\n", newH-oldH))
	}
	// Cursor is at the bottom line of the (possibly extended) window.
	if newH > 1 {
		b.WriteString(fmt.Sprintf("\x1b[%dA", newH-1))
	}
	b.WriteString("\r")
	_, _ = f.tty.WriteString(b.String())
	f.winH = newH
	f.cursorRow = 0
	f.cursorCol = 0
}

func (f *finder) buildFrame(w, h int) ([]screenRow, int, int) {
	th := f.resolvedTheme()
	bg := th.elementStyle("fg", "bg")
	if f.o.black {
		bg.bg = colorValue{kind: colorANSI, code: 0}
	}
	g := newGrid(w, h, bg)
	// Fill background styles are the grid default.
	secs := f.computeSections(w, h, h)
	f.currentSections = secs
	// Main border.
	if f.o.border.present {
		bs := th.elementStyle("border", "bg")
		ls := th.elementStyle("label", "bg")
		g.drawBorder(secs.outer, f.o.border, f.borderLabelStr, f.o.borderLabelPos, bs, ls, f.o.ambidouble, f.o.unicode)
	}
	// Section borders.
	if f.o.listBorder.present {
		g.drawBorder(secs.listBox, f.o.listBorder, f.listLabelStr, f.o.listLabelPos, th.elementStyle("list-border", "bg"), th.elementStyle("list-label", "bg"), f.o.ambidouble, f.o.unicode)
	}
	if f.o.inputBorder.present && secs.hasInput {
		g.drawBorder(secs.inputBox, f.o.inputBorder, f.inputLabelStr, f.o.inputLabelPos, th.elementStyle("input-border", "bg"), th.elementStyle("input-label", "bg"), f.o.ambidouble, f.o.unicode)
	}
	if secs.hasHeader && f.o.headerBorder.present {
		g.drawBorder(secs.headerBox, f.o.headerBorder, f.headerLabelStr, f.o.headerLabelPos, th.elementStyle("header-border", "bg"), th.elementStyle("header-label", "bg"), f.o.ambidouble, f.o.unicode)
	}
	if secs.hasPreview {
		pv := f.previewLayoutEffective()
		if pv.borderSet || f.previewCmdSet || f.hasPreviewBinding {
			cfg := borderConfig{style: pv.border, present: true}
			g.drawBorder(secs.previewBox, cfg, f.previewLabelStr, f.o.previewLabelPos, th.elementStyle("preview-border", "preview-bg"), th.elementStyle("preview-label", "preview-bg"), f.o.ambidouble, f.o.unicode)
		}
		f.drawPreview(g, secs.previewInner, th)
	}
	if secs.hasFooter {
		f.drawFooter(g, secs, th)
	}
	if secs.hasHeader {
		f.drawHeader(g, secs, th)
	}
	curX, curY := f.drawInput(g, secs, th)
	f.drawList(g, secs, th)
	rows := make([]screenRow, h)
	for y := 0; y < h; y++ {
		rows[y] = g.rowSpans(y)
	}
	return rows, curX, curY
}

func (g *grid) rowSpans(y int) screenRow {
	var spans []styledSpan
	var cur strings.Builder
	var curStyle cellStyle
	have := false
	for x := 0; x < g.w; x++ {
		c := g.cells[y*g.w+x]
		if c.wide {
			continue
		}
		st := c.style
		r := c.r
		if r == 0 {
			r = ' '
		}
		if !have {
			have = true
			curStyle = st
			cur.WriteRune(r)
			continue
		}
		if st != curStyle {
			spans = append(spans, styledSpan{text: cur.String(), style: curStyle})
			cur.Reset()
			curStyle = st
		}
		cur.WriteRune(r)
	}
	if have {
		spans = append(spans, styledSpan{text: cur.String(), style: curStyle})
	}
	return screenRow{spans: spans}
}

func (f *finder) drawFooter(g *grid, secs sections, th *theme) {
	// Footer border (line style by default): a horizontal line on the
	// side facing the list, and the text indented by two spaces.
	if f.o.footerBorder.present {
		g.drawBorder(secs.footerBox, f.o.footerBorder, f.footerLabelStr, f.o.footerLabelPos, th.elementStyle("footer-border", "bg"), th.elementStyle("footer-label", "bg"), f.o.ambidouble, f.o.unicode)
	} else {
		// Default footer border is a line facing the list.
		st := th.elementStyle("footer-border", "bg")
		ch := '─'
		if !f.o.unicode {
			ch = '-'
		}
		reverse := f.o.layout == layoutReverse
		ly := secs.footerBox.y + secs.footerBox.h - 1
		if reverse {
			ly = secs.footerBox.y
		}
		if f.footerBorderStyle() == borderLine {
			for x := secs.footerBox.x; x < secs.footerBox.right(); x++ {
				g.set(x, ly, ch, st, f.o.ambidouble)
			}
		}
	}
	st := th.elementStyle("footer", "footer-bg")
	lines := strings.Split(strings.TrimRight(f.footerText, "\n"), "\n")
	y := secs.footerInner.y
	reverse := f.o.layout == layoutReverse
	if !f.o.footerBorder.present && !reverse {
		y = secs.footerBox.y
	}
	if !f.o.footerBorder.present && reverse {
		y = secs.footerBox.y + 1
	}
	x := secs.footerBox.x
	for _, line := range lines {
		g.drawText(x+2, y, secs.footerBox.right(), line, st, f.o.ambidouble, f.o.tabstop)
		y++
	}
}

func (f *finder) drawHeader(g *grid, secs sections, th *theme) {
	st := th.elementStyle("header", "header-bg")
	y := secs.headerInner.y
	x := secs.headerBox.x
	// Indent depends on list indent: two columns for the gutter/marker.
	indent := 2
	if f.o.headerBorder.present || f.o.listBorder.present {
		x = secs.headerInner.x
		indent = 0
		if f.o.headerBorder.present {
			indent = 0
			x = secs.headerInner.x + 1
		}
	}
	var lines []string
	if f.headerText != "" {
		lines = append(lines, strings.Split(strings.TrimRight(f.headerText, "\n"), "\n")...)
	}
	lines = append(lines, f.headerLinesItems()...)
	for _, line := range lines {
		if y >= secs.headerInner.bottom() && f.o.headerBorder.present {
			break
		}
		g.drawText(x+indent, y, secs.headerBox.right(), line, st, f.o.ambidouble, f.o.tabstop)
		y++
	}
}

func (f *finder) infoText() string {
	matched := 0
	for _, r := range f.results {
		if r.matched {
			matched++
		}
	}
	if !f.rawMode {
		matched = len(f.results)
	}
	total := len(f.items)
	s := fmt.Sprintf("%d/%d", matched, total)
	if f.o.multi != 0 {
		s += fmt.Sprintf(" (%d)", len(f.selected))
	}
	return s
}

func (f *finder) drawInput(g *grid, secs sections, th *theme) (int, int) {
	if !secs.hasInput {
		return 0, 0
	}
	promptStyle := th.elementStyle("prompt", "input-bg")
	queryStyle := th.elementStyle("query", "input-bg")
	if f.searchOff {
		queryStyle = th.elementStyle("disabled", "input-bg")
	}
	ghostStyle := th.elementStyle("ghost", "input-bg")
	infoStyle := th.elementStyle("info", "input-bg")
	sepStyle := th.elementStyle("separator", "input-bg")

	// Background for input section.
	inputBg := th.elementStyle("fg", "input-bg")
	g.fillRect(secs.inputInner, inputBg)

	prompt := f.promptStr
	x := secs.inputInner.x
	promptRow := secs.promptRow
	// The prompt's first rune is colored; the rest as prompt text in the
	// reference (only '>' is colored for the default prompt, the space
	// keeps the prompt color).  We color the whole prompt.
	px := g.drawText(x, promptRow, secs.inputInner.right(), prompt, promptStyle, f.o.ambidouble, f.o.tabstop)
	// Ghost text.
	if len(f.query) == 0 && f.ghostStr != "" && !f.searchOff {
		g.drawText(px, promptRow, secs.inputInner.right(), f.ghostStr, ghostStyle, f.o.ambidouble, f.o.tabstop)
	}
	// Query text with horizontal scrolling if needed.
	queryRunes := f.query
	cursorPos := f.qcursor
	avail := secs.inputInner.right() - px
	// Reserve space for right-side info in right/inline-right styles.
	infoRightText := ""
	if f.o.info == infoRight {
		infoRightText = f.infoText()
		avail -= stringDisplayWidth(infoRightText, f.o.ambidouble, f.o.tabstop) + 1
	}
	inlineText := ""
	if f.o.info == infoInline || f.o.info == infoInlineRight {
		prefix := f.o.infoPrefix
		if prefix == "" {
			prefix = " "
		}
		// The reference shows e.g. " <spinner> 2/3" style inline info
		// after the query; the prefix is given by :PREFIX.
		_ = prefix
	}
	startIdx := 0
	// Compute the display width of the query up to the cursor.
	widthToCursor := 0
	for i := 0; i < cursorPos && i < len(queryRunes); i++ {
		widthToCursor += runeDisplayWidth(queryRunes[i], f.o.ambidouble)
	}
	for widthToCursor >= avail && startIdx < cursorPos {
		widthToCursor -= runeDisplayWidth(queryRunes[startIdx], f.o.ambidouble)
		startIdx++
	}
	qx := g.drawText(px, promptRow, px+avail, string(queryRunes[startIdx:]), queryStyle, f.o.ambidouble, f.o.tabstop)
	curX := px + widthToCursor
	_ = qx
	if inlineText != "" {
		g.drawText(qx, promptRow, secs.inputInner.right(), inlineText, infoStyle, f.o.ambidouble, f.o.tabstop)
	}
	if f.o.info == infoInline {
		txt := f.o.infoPrefix
		if txt == "" {
			txt = " "
		}
		if f.isReading() {
			txt += spinnerFrame(f.spinnerIdx, f.o.unicode) + " "
		}
		txt += f.infoText()
		g.drawText(qx, promptRow, secs.inputInner.right(), txt, infoStyle, f.o.ambidouble, f.o.tabstop)
	}
	if f.o.info == infoInlineRight || f.o.info == infoRight {
		txt := f.infoText()
		if f.o.info == infoInlineRight {
			p := f.o.infoPrefix
			txt = p + txt
		}
		if f.isReading() {
			txt = spinnerFrame(f.spinnerIdx, f.o.unicode) + " " + txt
		}
		tw := stringDisplayWidth(txt, f.o.ambidouble, f.o.tabstop)
		rx := secs.inputInner.right() - tw
		g.drawText(rx, promptRow, secs.inputInner.right(), txt, infoStyle, f.o.ambidouble, f.o.tabstop)
	}
	// Info command preview-style line replaces the info text if set; its
	// output was captured when set/executed.  (Handled by draw below via
	// f.infoCommandOutput.)
	if secs.infoRow >= 0 {
		y := secs.infoRow
		ix := secs.listBox.x + 2
		if f.o.listBorder.present {
			ix = secs.inputInner.x + 1
		} else if f.o.inputBorder.present {
			ix = secs.inputInner.x
		}
		if f.isReading() {
			spin := spinnerFrame(f.spinnerIdx, f.o.unicode)
			ss := th.elementStyle("spinner", "input-bg")
			spinX := secs.inputInner.x
			if f.o.inputBorder.present {
				spinX = secs.inputInner.x
			}
			// Spinner occupies the first cell of the info row in the
			// indent area.
			if f.o.listBorder.present || f.o.inputBorder.present {
				spinX = secs.inputInner.x
			} else {
				spinX = secs.listBox.x
			}
			g.drawText(spinX, y, secs.inputInner.right(), spin, ss, f.o.ambidouble, f.o.tabstop)
		}
		info := f.infoText()
		if f.o.infoCommand != "" && f.infoCommandOutput != "" {
			info = firstLine(f.infoCommandOutput)
		}
		endX := g.drawText(ix, y, secs.inputInner.right(), info, infoStyle, f.o.ambidouble, f.o.tabstop)
		// Separator.
		if !f.o.noSeparator {
			sep := f.o.separator
			if !f.o.separatorSet {
				if f.o.unicode {
					sep = "─"
				} else {
					sep = "-"
				}
			}
			if sep != "" {
				g.drawText(endX+1, y, secs.inputInner.right(), strings.Repeat(sep, maxInt(0, secs.inputInner.right()-endX-1)), sepStyle, f.o.ambidouble, f.o.tabstop)
			}
		}
	}
	return curX, promptRow
}

