		hlStyle = th.elementStyle("current-hl", "current-bg")
		gutterStyle = th.elementStyle("pointer", "current-bg")
	} else if isSelected {
		textStyle = th.elementStyle("selected-fg", "selected-bg")
		hlStyle = th.elementStyle("selected-hl", "selected-bg")
		gutterStyle = th.elementStyle("gutter", "list-bg")
	} else {
		textStyle = th.elementStyle("list-fg", "list-bg")
		hlStyle = th.elementStyle("hl", "list-bg")
		gutterStyle = th.elementStyle("gutter", "list-bg")
		if !res.matched && f.rawMode {
			textStyle = th.elementStyle("nomatch", "list-bg")
			hlStyle = textStyle
		}
	}
	if f.o.highlightLine && isCurrent {
		bg := th.elementStyle("fg", "current-bg")
		for yy := y; yy < y+height; yy++ {
			for xx := x; xx < right; xx++ {
				g.set(xx, yy, ' ', cellStyle{fg: bg.fg, bg: bg.bg}, f.o.ambidouble)
			}
		}
	}
	// Alternate background (striped) based on input index parity.
	altBg := false
	if _, ok := f.o.theme.colors["alt-bg"]; ok {
		if it.index%2 == 1 {
			altBg = true
		}
	}
	// Build sub-lines.
	text := it.text
	if !f.o.multiLine {
		text = strings.ReplaceAll(text, "\n", " ")
	}
	subLines := strings.Split(text, "\n")
	// Rune offset of each sub-line start within the item text.
	offset := 0
	marker := " "
	if isSelected {
		marker = f.markerStr()
	}
	textX := x + 2
	if f.o.multi == 0 && !f.o.markerSet {
		// Single-select mode still has a one-column marker slot in the
		// reference (a space), giving text at column 2 from the gutter.
		textX = x + 2
	}
	row := y
	for li, seg := range subLines {
		if row >= y+height {
			break
		}
		// Gutter / pointer column.
		gch := f.gutterOrDefault()
		if isCurrent {
			gch = f.pointer()
		} else if !res.matched && f.rawMode {
			gch = f.gutterChar(true)
		}
		gs := gutterStyle
		g.drawText(x, row, right, gch, gs, f.o.ambidouble, f.o.tabstop)
		// Marker column (multi-select).  For multi-line entries use the
		// multi-line markers when selected.
		mk := marker
		if isSelected && (len(subLines) > 1 || height > 1) {
			mk = f.multiLineMarker(li, len(subLines))
		}
		ms := th.elementStyle("marker", "list-bg")
		if isCurrent {
			ms = th.elementStyle("marker", "current-bg")
		}
		g.drawText(x+1, row, right, mk, ms, f.o.ambidouble, f.o.tabstop)
		// Item text with per-rune styles.
		runes := []rune(seg)
		styles := make([]cellStyle, len(runes))
		for i := range runes {
			st := textStyle
			if altBg && !isCurrent {
				st.bg = th.elementStyle("fg", "alt-bg").bg
			}
			if matchedPos[offset+i] {
				st = hlStyle
			}
			styles[i] = f.applyANSI(it, offset+i, st, matchedPos[offset+i])
		}
		endX := g.drawStyledRunes(textX, row, right, runes, styles, f.o.ambidouble, f.o.tabstop)
		// With wrapping, long segments need to continue on following rows.
		if f.o.wrap {
			avail := right - textX
			if avail < 1 {
				avail = 1
			}
			remaining := runes
			remainingStyles := styles
			consumedWidth := 0
			_ = endX
			// Compute chars drawn on the first row.
			drawn := 0
			wsum := 0
			for drawn < len(remaining) {
				w := runeDisplayWidth(remaining[drawn], f.o.ambidouble)
				if remaining[drawn] == '\t' {
					w = 1
				}
				if wsum+w > avail {
					break
				}
				wsum += w
				drawn++
			}
			consumedWidth = wsum
			_ = consumedWidth
			remaining = remaining[drawn:]
			remainingStyles = remainingStyles[drawn:]
			baseOffset := offset + drawn
			_ = baseOffset
			for len(remaining) > 0 && row+1 < y+height {
				row++
				// Wrap indicator replaces the gutter/marker area.
				sign := f.o.wrapSign
				if !f.o.wrapSignSet {
					if f.o.unicode {
						sign = "↳ "
					} else {
						sign = "> "
					}
				}
				g.drawText(x, row, right, sign, gutterStyle, f.o.ambidouble, f.o.tabstop)
				d2 := 0
				wsum = 0
				avail2 := right - textX
				for d2 < len(remaining) {
					w := runeDisplayWidth(remaining[d2], f.o.ambidouble)
					if wsum+w > avail2 {
						break
					}
					wsum += w
					d2++
				}
				if d2 == 0 {
					d2 = 1
				}
				g.drawStyledRunes(textX, row, right, remaining[:d2], remainingStyles[:d2], f.o.ambidouble, f.o.tabstop)
				remaining = remaining[d2:]
				remainingStyles = remainingStyles[d2:]
			}
		} else if f.shouldEllipsis(runes, right-textX) {
			f.drawEllipsis(g, right, row, th, textStyle)
		}
		offset += len(runes) + 1 // newline
		row++
	}
}

func (f *finder) shouldEllipsis(runes []rune, avail int) bool {
	if avail <= 0 {
		return false
	}
	return stringDisplayWidth(string(runes), f.o.ambidouble, f.o.tabstop) > avail
}

func (f *finder) drawEllipsis(g *grid, right, row int, th *theme, st cellStyle) {
	ell := f.o.ellipsis
	if !f.o.ellipsisSet {
		if f.o.unicode {
			ell = "··"
		} else {
			ell = ".."
		}
	}
	w := stringDisplayWidth(ell, f.o.ambidouble, f.o.tabstop)
	x := right - w
	if x < 0 {
		return
	}
	g.drawText(x, row, right, ell, st, f.o.ambidouble, f.o.tabstop)
}

func (f *finder) multiLineMarker(li, total int) string {
	if f.o.markerMultiLineSet && f.o.markerMultiLine != "" {
		rs := []rune(f.o.markerMultiLine)
		if len(rs) >= 3 {
			if total <= 1 {
				return f.markerStr()
			}
			if li == 0 {
				return string(rs[0])
			}
			if li == total-1 {
				return string(rs[2])
			}
			return string(rs[1])
		}
	}
	if total <= 1 {
		return f.markerStr()
	}
	if !f.o.unicode {
		return f.markerStr()
	}
	if li == 0 {
		return "╻"
	}
	if li == total-1 {
		return "╹"
	}
	return "┃"
}

// applyANSI applies the item's own ANSI SGR styling (from --ansi items) on
// top of / underneath the element style.  Matched characters keep the
// highlight foreground.
func (f *finder) applyANSI(it *item, runeIdx int, st cellStyle, matched bool) cellStyle {
	if !f.o.ansi || len(it.ansiColors) == 0 {
		return st
	}
	// Walk SGR events up to this rune and fold them into a style.  This is
	// O(events) per rune; items are normally short.
	ast := cellStyle{fg: specColor(-1), bg: specColor(-1)}
	active := false
	for _, sp := range it.ansiColors {
		if sp.pos > runeIdx {
			break
		}
		applySGR(&ast, sp.code)
		active = true
	}
	if !active {
		return st
	}
	out := st
	if ast.fg.kind != colorUnset && ast.fg.kind != colorDefault {
		if !matched {
			out.fg = ast.fg
		}
	}
	if ast.bg.kind != colorUnset && ast.bg.kind != colorDefault {
		out.bg = ast.bg
	}
	out.attrs |= ast.attrs
	if ast.underline != 0 {
		out.underline = ast.underline
	}
	return out
}

func applySGR(st *cellStyle, seq string) {
	// seq is ESC [ params m
	if len(seq) < 3 {
		return
	}
	params := seq[2 : len(seq)-1]
	if params == "" {
		params = "0"
	}
	parts := strings.Split(params, ";")
	for i := 0; i < len(parts); i++ {
		p := parts[i]
		n := 0
		if p != "" {
			v, err := parseDigits(p)
			if err != nil {
				continue
			}
			n = v
		}
		switch {
		case n == 0:
			*st = cellStyle{fg: specColor(-1), bg: specColor(-1)}
		case n == 1:
			st.attrs |= attrBold
		case n == 2:
			st.attrs |= attrDim
		case n == 3:
			st.attrs |= attrItalic
		case n == 4:
			st.underline = 1
		case n == 7:
			st.attrs |= attrReverse
		case n == 9:
			st.attrs |= attrStrikethrough
		case n >= 30 && n <= 37:
			st.fg = colorValue{kind: colorANSI, code: n - 30}
		case n == 39:
			st.fg = specColor(-1)
		case n >= 40 && n <= 47:
			st.bg = colorValue{kind: colorANSI, code: n - 40}
		case n == 49:
			st.bg = specColor(-1)
		case n >= 90 && n <= 97:
			st.fg = colorValue{kind: colorANSI, code: n - 90 + 8}
		case n >= 100 && n <= 107:
			st.bg = colorValue{kind: colorANSI, code: n - 100 + 8}
		case n == 38 || n == 48:
			// Extended color: 38;5;N or 38;2;R;G;B (colon forms are
			// already split into separate params by ';' only when the
			// sequence uses semicolons).
			if i+1 < len(parts) {
				mode, _ := parseDigits(parts[i+1])
				if mode == 5 && i+2 < len(parts) {
					code, _ := parseDigits(parts[i+2])
					cv := colorValue{kind: colorANSI, code: code}
					if n == 38 {
						st.fg = cv
					} else {
						st.bg = cv
					}
					i += 2
				} else if mode == 2 && i+4 < len(parts) {
					r, _ := parseDigits(parts[i+2])
					gc, _ := parseDigits(parts[i+3])
					bc, _ := parseDigits(parts[i+4])
					cv := colorValue{kind: colorRGB, r: r, g: gc, b: bc}
					if n == 38 {
						st.fg = cv
					} else {
						st.bg = cv
					}
					i += 4
				}
			}
		}
	}
}

func parseDigits(s string) (int, error) {
	n := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, errString("not a number")
		}
		n = n*10 + int(c-'0')
	}
	return n, nil
}
