// visualOrder returns results in display (top-to-bottom) order.
func (f *finder) visualOrder() []*result {
	if f.o.layout == layoutDefault {
		out := make([]*result, len(f.results))
		for i, r := range f.results {
			out[len(f.results)-1-i] = r
		}
		return out
	}
	return f.results
}

func (f *finder) visualIndexOfCurrent() int {
	if f.current < 0 {
		return -1
	}
	if f.o.layout == layoutDefault {
		return len(f.results) - 1 - f.current
	}
	return f.current
}

func (f *finder) resultIndexOfVisual(v int) int {
	if f.o.layout == layoutDefault {
		return len(f.results) - 1 - v
	}
	return v
}

// row heights per result (physical lines in the item plus wrapping).
func (f *finder) itemRowHeight(r *result, width int) int {
	text := r.item.text
	lines := 1
	if f.o.multiLine {
		lines = strings.Count(text, "\n") + 1
	}
	if f.o.wrap && width > 0 {
		// Approximate wrapped height after the 2-column gutter.
		avail := width - 2
		if avail < 1 {
			avail = 1
		}
		total := 0
		for _, seg := range strings.Split(text, "\n") {
			w := stringDisplayWidth(seg, f.o.ambidouble, f.o.tabstop)
			n := (w + avail - 1) / avail
			if n < 1 {
				n = 1
			}
			total += n
		}
		if !f.o.multiLine {
			// Without multi-line, newlines were not counted above.
		} else {
			lines = total
		}
		if !f.o.multiLine {
			seg := strings.ReplaceAll(text, "\n", " ")
			w := stringDisplayWidth(seg, f.o.ambidouble, f.o.tabstop)
			lines = (w + avail - 1) / avail
			if lines < 1 {
				lines = 1
			}
		}
	}
	return lines
}

func (f *finder) ensureVisible(listH int) {
	vis := f.visualOrder()
	if len(vis) == 0 {
		f.vOffset = 0
		return
	}
	cur := f.visualIndexOfCurrent()
	if cur < 0 {
		return
	}
	// Work in item units translated through gap-aware capacity: we first
	// compute how many entries fit, then adjust vOffset minimally.
	capacity := f.listCapacityFor(listH)
	if capacity <= 0 {
		return
	}
	off := f.o.scrollOff
	if cur < f.vOffset+off {
		f.vOffset = cur - off
	}
	if cur >= f.vOffset+capacity-off {
		f.vOffset = cur - capacity + 1 + off
	}
	maxOff := len(vis) - capacity
	if maxOff < 0 {
		maxOff = 0
	}
	if f.vOffset > maxOff {
		f.vOffset = maxOff
	}
	if f.vOffset < 0 {
		f.vOffset = 0
	}
}

func (f *finder) drawList(g *grid, secs sections, th *theme) {
	r := secs.listInner
	if r.w <= 0 || r.h <= 0 {
		return
	}
	f.ensureVisible(r.h)
	vis := f.visualOrder()
	// Scrollbar reservation: the reference shows a scrollbar in the last
	// column of the list section when items overflow (also a blank column
	// may be reserved).  We reserve it only when it would be drawn.
	showScrollbar := !f.o.noScrollbar && len(vis) > f.listCapacityFor(r.h)
	textRight := r.right()
	if showScrollbar {
		textRight--
	}
	// Build the sequence of visual entries to display, skipping entries
	// above the current page when anchored to the bottom in default
	// layout.  The anchoring for default layout is handled by choosing
	// the start row after collecting rows.
	type entry struct {
		res *result
		vi  int
	}
	var entries []entry
	usedRows := 0
	for vi := f.vOffset; vi < len(vis); vi++ {
		res := vis[vi]
		h := f.itemRowHeight(res, textRight-r.x)
		add := h
		if vi > f.vOffset {
			add += f.o.gap
		}
		if usedRows+add > r.h && len(entries) > 0 {
			break
		}
		entries = append(entries, entry{res: res, vi: vi})
		usedRows += add
		if usedRows >= r.h {
			break
		}
	}
	// Store rows for mouse hit-testing.
	f.listRows = nil
	y := r.y
	if f.o.layout == layoutDefault {
		// Anchor to the bottom of the list area.
		y = r.bottom() - usedRows
		if y < r.y {
			y = r.y
		}
	}
	curVis := f.visualIndexOfCurrent()
	for ei, e := range entries {
		if ei > 0 && f.o.gap > 0 {
			for gy := 0; gy < f.o.gap; gy++ {
				if f.o.gapLineSet {
					sep := f.o.gapLine
					if sep == "" {
						if f.o.unicode {
							sep = "┈"
						} else {
							sep = "-"
						}
					}
					st := th.elementStyle("gap-line", "list-bg")
					g.drawText(r.x, y+gy, textRight, strings.Repeat(sep, maxInt(0, textRight-r.x)), st, f.o.ambidouble, f.o.tabstop)
				}
			}
			y += f.o.gap
		}
		isCurrent := e.vi == curVis
		h := f.itemRowHeight(e.res, textRight-r.x)
		f.drawItem(g, r.x, y, textRight, h, e.res, isCurrent, th)
		for row := 0; row < h; row++ {
			f.listRows = append(f.listRows, listRowInfo{y: y + row, visual: e.vi})
		}
		y += h
	}
	if showScrollbar {
		f.drawScrollbar(g, secs.listBox, r, len(vis), th)
	}
}

type listRowInfo struct {
	y      int
	visual int
}

func (f *finder) drawScrollbar(g *grid, box, inner rect, total int, th *theme) {
	h := inner.h
	if h <= 0 || total <= 0 {
		return
	}
	capacity := f.listCapacityFor(h)
	if capacity >= total {
		return
	}
	st := th.elementStyle("scrollbar", "list-bg")
	ch := scrollbarChar(f, 0)
	x := inner.right() - 1
	// A simple proportional thumb.
	thumbSize := h * capacity / total
	if thumbSize < 1 {
		thumbSize = 1
	}
	maxOff := total - capacity
	thumbPos := 0
	if maxOff > 0 {
		thumbPos = (h - thumbSize) * f.vOffset / maxOff
	}
	for i := 0; i < thumbSize; i++ {
		g.set(x, inner.y+thumbPos+i, ch, st, f.o.ambidouble)
	}
}

func scrollbarChar(f *finder, which int) rune {
	if f.o.scrollbarSet && f.o.scrollbar != "" {
		rs := []rune(f.o.scrollbar)
		if which < len(rs) {
			return rs[which]
		}
		return rs[0]
	}
	if f.o.unicode {
		return '█'
	}
	return '#'
}

