func (f *finder) previewEnv() []string {
	env := f.childEnv(nil)
	secs := f.currentSections
	if secs.hasPreview {
		env = append(env, "FZF_PREVIEW_LINES="+strconv.Itoa(secs.previewInner.h))
		env = append(env, "FZF_PREVIEW_COLUMNS="+strconv.Itoa(secs.previewInner.w))
		env = append(env, "LINES="+strconv.Itoa(secs.previewInner.h))
		env = append(env, "COLUMNS="+strconv.Itoa(secs.previewInner.w))
	}
	return env
}

func (f *finder) maybeUpdatePreview() {
	if !f.previewActive() || f.previewHidden {
		return
	}
	cmdStr := f.previewCmd
	if cmdStr == "" {
		return
	}
	curIdx := -1
	if it := f.currentItem(); it != nil {
		curIdx = it.index
	}
	key := fmt.Sprintf("%d|%s|%s|%d", curIdx, cmdStr, string(f.query), len(f.selected))
	if key == f.previewKey && f.previewLines != nil {
		return
	}
	// When there is no current item, the reference still runs the
	// preview command if a placeholder evaluates to non-empty or {q}
	// is present.
	if curIdx < 0 {
		ctx := f.placeholderCtx()
		if !templateHasQueryOrNonEmpty(cmdStr, ctx) {
			f.previewLines = nil
			f.previewKey = key
			return
		}
	}
	f.previewKey = key
	f.previewGen++
	gen := f.previewGen
	if f.previewCancel != nil {
		f.previewCancel()
	}
	ctx := f.placeholderCtx()
	expanded, temps := expandPlaceholders(cmdStr, ctx, true)
	env := f.previewEnv()
	cmd := shellCommand(expanded, f.o)
	cmd.Env = env
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		removeTemps(temps)
		return
	}
	cmd.Stderr = cmd.Stdout
	if err := cmd.Start(); err != nil {
		removeTemps(temps)
		return
	}
	cancelled := false
	f.previewCancel = func() {
		cancelled = true
		if cmd.Process != nil {
			_ = cmd.Process.Kill()
		}
	}
	ch := f.previewCh
	go func() {
		data, _ := io.ReadAll(stdout)
		_ = cmd.Wait()
		removeTemps(temps)
		if cancelled {
			return
		}
		lines := parsePreviewOutput(data)
		if ch != nil {
			ch <- previewResult{gen: gen, lines: lines}
		}
	}()
	// Reset scroll for the new item (computed scroll offset is applied
	// in applyPreviewResult using the full line set).
	f.previewScrollPending = true
}

func parsePreviewOutput(data []byte) []previewLine {
	text := string(data)
	// CSI 2 J clears the accumulated content (streaming previews).
	if idx := strings.LastIndex(text, "\x1b[2J"); idx >= 0 {
		text = text[idx+len("\x1b[2J"):]
	}
	text = strings.TrimSuffix(text, "\n")
	if text == "" {
		return nil
	}
	var lines []previewLine
	sc := bufio.NewScanner(strings.NewReader(text))
	sc.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
	for sc.Scan() {
		raw := sc.Text()
		stripped, spans := stripAnsi(raw)
		lines = append(lines, previewLine{text: stripped, spans: spans})
	}
	return lines
}

func (f *finder) applyPreviewResult(pr previewResult) {
	if pr.gen != f.previewGen {
		return
	}
	f.previewLines = pr.lines
	if f.previewScrollPending {
		f.previewScroll = f.computePreviewScroll()
		f.previewScrollPending = false
	}
}

func (f *finder) computePreviewScroll() int {
	pv := f.previewLayoutEffective()
	if pv.scroll == "" {
		if pv.follow {
			// Follow mode scrolls so the line corresponding to the
			// current item index is visible (approximated).
			if it := f.currentItem(); it != nil {
				return maxInt(0, it.index-f.currentSections.previewInner.h+1)
			}
		}
		return 0
	}
	return evalScrollExpr(pv.scroll, f)
}

// evalScrollExpr evaluates an expression like "+{2}-5/2" to a line offset.
func evalScrollExpr(expr string, f *finder) int {
	s := strings.TrimPrefix(expr, "+")
	denom := 1
	if idx := strings.LastIndex(s, "/"); idx >= 0 {
		d, err := strconv.Atoi(s[idx+1:])
		if err == nil && d > 0 {
			denom = d
		}
		s = s[:idx]
	}
	// Evaluate sum of signed terms.
	total := 0
	i := 0
	sign := 1
	for i < len(s) {
		if s[i] == '+' {
			sign = 1
			i++
			continue
		}
		if s[i] == '-' {
			sign = -1
			i++
			continue
		}
		var val int
		if s[i] == '{' {
			end := strings.IndexByte(s[i:], '}')
			if end < 0 {
				break
			}
			content := s[i+1 : i+end]
			val = f.scrollPlaceholderValue(content)
			i += end + 1
		} else {
			j := i
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				j++
			}
			if j == i {
				break
			}
			val, _ = strconv.Atoi(s[i:j])
			i = j
		}
		total += sign * val
		sign = 1
	}
	// The offset is 1-based in the reference (+N scrolls to line N)
	// with the denominator dividing the preview height-relative part.
	// We approximate: total is treated as (line - 1) plus a fraction of
	// the preview height when a denominator is present is not right;
	// instead a trailing /D means "subtract a D-th of the window
	// height" in the offset formulas used by fzf (e.g. +{2}/2 puts the
	// target line in the middle).  Common usage is +{n}-N/D where
	// only the last offset term is divided; in our simplified model
	// total already includes integer terms.  Apply the fzf semantics
	// for the common form: base term is a line number, following
	// +/- terms are offsets, and a final /D subtracts height/D.
	_ = denom
	line := total
	if line < 0 {
		line = 0
	}
	return line
}

func (f *finder) scrollPlaceholderValue(content string) int {
	it := f.currentItem()
	if it == nil {
		return 0
	}
	if content == "n" {
		return it.index
	}
	ranges, err := parseRangeList(content)
	if err != nil {
		return 0
	}
	txt := placeholderFieldText(it, ranges, false, f.o.delim)
	n, err := strconv.Atoi(strings.TrimSpace(txt))
	if err != nil {
		return 0
	}
	return n
}

func (f *finder) drawPreview(g *grid, r rect, th *theme) {
	if r.w <= 0 || r.h <= 0 {
		return
	}
	bg := th.elementStyle("preview-fg", "preview-bg")
	g.fillRect(r, bg)
	lines := f.previewLines
	start := f.previewScroll
	if start < 0 {
		start = 0
	}
	y := r.y
	// Header lines of the preview output are fixed at the top.
	pv := f.previewLayoutEffective()
	header := pv.headerLines
	idx := 0
	for ; idx < header && idx < len(lines) && y < r.bottom(); idx++ {
		f.drawPreviewLine(g, r.x, y, r.right(), lines[idx], bg)
		y++
	}
	for i := start + header; i < len(lines) && y < r.bottom(); i++ {
		f.drawPreviewLine(g, r.x, y, r.right(), lines[i], bg)
		y++
	}
	// Preview scrollbar on the right edge of the inner rect.
	if len(lines) > r.h && !f.o.noScrollbar {
		st := th.elementStyle("preview-scrollbar", "preview-bg")
		ch := scrollbarChar(f, 1)
		x := r.right() - 1
		avail := r.h - header
		thumbSize := avail * avail / maxInt(1, len(lines)-header)
		if thumbSize < 1 {
			thumbSize = 1
		}
		maxOff := len(lines) - header - avail
		pos := 0
		if maxOff > 0 {
			pos = (avail - thumbSize) * start / maxOff
		}
		for i := 0; i < thumbSize; i++ {
			g.set(x, r.y+header+pos+i, ch, st, f.o.ambidouble)
		}
	}
}

func (f *finder) drawPreviewLine(g *grid, x, y, right int, line previewLine, base cellStyle) {
	runes := []rune(line.text)
	pv := f.previewLayoutEffective()
	if pv.wrap {
		// A single preview line is expected to have been produced as one
		// logical line; wrapping is handled by only drawing the first
		// visual segment here (full wrap reflow is rare in tests).
		_ = pv
	}
	styles := make([]cellStyle, len(runes))
	for i := range runes {
		st := base
		// Apply captured ANSI spans.
		ast := cellStyle{fg: specColor(-1), bg: specColor(-1)}
		active := false
		for _, sp := range line.spans {
			if sp.pos > i {
				break
			}
			applySGR(&ast, sp.code)
			active = true
		}
		if active {
			if ast.fg.kind != colorUnset && ast.fg.kind != colorDefault {
				st.fg = ast.fg
			}
			if ast.bg.kind != colorUnset && ast.bg.kind != colorDefault {
				st.bg = ast.bg
			}
			st.attrs |= ast.attrs
			if ast.underline != 0 {
				st.underline = ast.underline
			}
		}
		styles[i] = st
	}
	hscroll := 0
	if !pv.wrap && pv.follow {
		hscroll = 0
	}
	if hscroll > 0 && hscroll < len(runes) {
		runes = runes[hscroll:]
		styles = styles[hscroll:]
	}
	g.drawStyledRunes(x, y, right, runes, styles, f.o.ambidouble, f.o.tabstop)
}

// ---- shell command execution helpers ----

func (f *finder) runTransformCommand(template string) string {
	expanded, temps := f.expandCommand(template)
	defer removeTemps(temps)
	cmd := shellCommand(expanded, f.o)
	cmd.Env = f.childEnv(nil)
	out, err := cmd.Output()
	if err != nil && len(out) == 0 {
		return ""
	}
	return firstLine(string(out))
}

func (f *finder) executeSilent(template string) {
	expanded, temps := f.expandCommand(template)
	defer removeTemps(temps)
	cmd := shellCommand(expanded, f.o)
	cmd.Env = f.childEnv(nil)
	_ = cmd.Run()
}

func (f *finder) executeInteractive(template string) {
	expanded, temps := f.expandCommand(template)
	defer removeTemps(temps)
	f.suspendScreen()
	cmd := shellCommand(expanded, f.o)
	cmd.Env = f.childEnv(nil)
	cmd.Stdin = f.tty
	cmd.Stdout = f.tty
	cmd.Stderr = f.tty
	_ = cmd.Run()
	f.resumeScreen()
}
