		}
		return
	}
	if (f.trackOn || f.trackCur) && oldItem != nil {
		for i, r := range results {
			if r.item == oldItem {
				f.current = i
				return
			}
		}
	}
	if oldIdx < 0 {
		f.current = 0
		return
	}
	if oldIdx >= len(results) {
		f.current = len(results) - 1
		return
	}
	f.current = oldIdx
}

func (f *finder) setCurrentResult(idx int, fireEvents bool) {
	if len(f.results) == 0 {
		f.current = -1
		return
	}
	if f.o.cycle {
		n := len(f.results)
		idx = ((idx % n) + n) % n
	} else {
		if idx < 0 {
			idx = 0
		}
		if idx >= len(f.results) {
			idx = len(f.results) - 1
		}
	}
	if idx != f.current {
		f.current = idx
		f.previewKey = ""
		if fireEvents {
			f.fireEvent("focus")
		}
		// Focusing a different item disables track-current (but not
		// global --track).
		if f.trackCur {
			// track-current stays until untracked per the docs ("automatically
			// disabled if focus changes" applies to track-current set by
			// a focus event loop; keep it simple and do not clear here).
		}
	}
}

// moveVisual moves the cursor by delta in visual (display) order:
// -1 is physically up, +1 is physically down.
func (f *finder) moveVisual(delta int, matchedOnly bool, selectedOnly bool) {
	if len(f.results) == 0 {
		return
	}
	vis := f.visualOrder()
	cur := f.visualIndexOfCurrent()
	if cur < 0 {
		cur = 0
	}
	step := 1
	if delta < 0 {
		step = -1
	}
	remaining := delta
	if remaining < 0 {
		remaining = -remaining
	}
	target := cur
	for remaining > 0 {
		next := target + step
		if f.o.cycle {
			n := len(vis)
			next = ((next % n) + n) % n
			if next == cur && (matchedOnly || selectedOnly) {
				break
			}
		} else if next < 0 || next >= len(vis) {
			break
		}
		target = next
		r := vis[target]
		if matchedOnly && !r.matched {
			continue
		}
		if selectedOnly && !f.selected[r.item.index] {
			continue
		}
		remaining--
	}
	f.setCurrentResult(f.resultIndexOfVisual(target), true)
}

func (f *finder) queryString() string { return string(f.query) }

func (f *finder) setQueryRunes(q []rune, cursor int) {
	if string(q) == string(f.query) {
		f.qcursor = cursor
		if f.qcursor > len(q) { f.qcursor = len(q) }
		if f.qcursor < 0 { f.qcursor = 0 }
		return
	}
	f.query = q
	f.qcursor = cursor
	if f.qcursor > len(q) { f.qcursor = len(q) }
	if f.qcursor < 0 { f.qcursor = 0 }
	f.historySavedSet = false
	f.refilter(true)
	f.fireEvent("change")
	f.maybeFireOneZero()
}

func wordChar(r rune, filepath bool) bool {
	if filepath {
		// Word characters are those up to path separators / spaces.
		return r != '/' && r != '\\' && r != ' ' && r != '\t'
	}
	return r == '_' || isAlnumRune(r)
}

func isAlnumRune(r rune) bool {
	return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r > 127
}

func prevWordBoundary(q []rune, pos int, filepath bool) int {
	i := pos
	for i > 0 && !wordChar(q[i-1], filepath) {
		i--
	}
	for i > 0 && wordChar(q[i-1], filepath) {
		i--
	}
	return i
}

func nextWordBoundary(q []rune, pos int, filepath bool) int {
	i := pos
	for i < len(q) && wordChar(q[i], filepath) {
		i++
	}
	for i < len(q) && !wordChar(q[i], filepath) {
		i++
	}
	return i
}

func isSubwordBoundary(q []rune, i int) bool {
	if i <= 0 || i >= len(q) {
		return true
	}
	prev, cur := q[i-1], q[i]
	if prev == '_' || prev == '-' || prev == ' ' || prev == '/' {
		return true
	}
	if isLower(prev) && isUpper(cur) {
		return true
	}
	if isDigit(prev) != isDigit(cur) {
		return true
	}
	if !isAlnumRune(prev) || !isAlnumRune(cur) {
		return prev != cur
	}
	return false
}

func isLower(r rune) bool { return r >= 'a' && r <= 'z' }
func isUpper(r rune) bool { return r >= 'A' && r <= 'Z' }
func isDigit(r rune) bool { return r >= '0' && r <= '9' }

func prevSubwordBoundary(q []rune, pos int) int {
	i := pos - 1
	for i > 0 && !isSubwordBoundary(q, i) {
		i--
	}
	if i < 0 {
		i = 0
	}
	return i
}

func nextSubwordBoundary(q []rune, pos int) int {
	i := pos + 1
	for i < len(q) && !isSubwordBoundary(q, i) {
		i++
	}
	if i > len(q) {
		i = len(q)
	}
	return i
}

