cat > actions.go <<'GO'
package main

import (
	"os"
	"strconv"
	"strings"
	"time"
)

func (f *finder) handleKey(ev keyEvent) {
	if ev.name == "ignore" {
		return
	}
	if ev.isPaste {
		f.insertText(ev.paste)
		f.afterUserAction()
		return
	}
	if ev.mouse != nil {
		if f.handleMouse(ev) {
			f.afterUserAction()
			return
		}
	}
	if f.jumpMode {
		if f.handleJumpKey(ev) {
			f.afterUserAction()
			return
		}
	}
	f.lastKey = ev.name
	acts, bound := f.keymap[ev.name]
	if !bound {
		// Unbound printable characters are inserted into the query.
		if ev.r != 0 && !f.inputHidden {
			f.insertText(string(ev.r))
		} else if ev.name == "space" && !f.inputHidden {
			f.insertText(" ")
		}
		f.afterUserAction()
		return
	}
	f.executeActions(acts, ev.name)
	f.afterUserAction()
}

// afterUserAction processes events queued by the actions just run.
func (f *finder) afterUserAction() {
	f.processQueuedEvents()
}

func (f *finder) insertText(text string) {
	if f.inputHidden {
		return
	}
	// Newlines in pasted text are stripped by the reference (the prompt
	// is single-line).
	text = strings.ReplaceAll(text, "\n", "")
	text = strings.ReplaceAll(text, "\r", "")
	runes := []rune(text)
	if len(runes) == 0 {
		return
	}
	newQ := make([]rune, 0, len(f.query)+len(runes))
	newQ = append(newQ, f.query[:f.qcursor]...)
	newQ = append(newQ, runes...)
	newQ = append(newQ, f.query[f.qcursor:]...)
	f.setQueryRunes(newQ, f.qcursor+len(runes))
}

func (f *finder) executeActions(acts []action, keyName string) {
	for _, a := range acts {
		if f.finished {
			return
		}
		f.lastAction = a.name
		f.executeAction(a, keyName)
	}
}

func (f *finder) acceptWith(items []*item, code int) {
	f.acceptItems = items
	f.exitCode = code
	f.finished = true
}

func (f *finder) doAccept() {
	var items []*item
	if len(f.selected) > 0 {
		items = f.selectedItemsInResultOrder()
	} else if it := f.currentItem(); it != nil {
		items = []*item{it}
	}
	code := 0
	if len(items) == 0 && len(f.printQueue) == 0 {
		code = 1
	}
	if len(f.printQueue) > 0 && len(items) == 0 {
		// Printed strings are emitted instead of a selection.
		code = 0
		items = nil
	}
	f.acceptWith(items, code)
}

func (f *finder) executeAction(a action, keyName string) {
	o := f.o
	switch a.name {
	case "ignore":
	case "abort":
		f.exitCode = 130
		f.finished = true
	case "cancel":
		if len(f.query) > 0 {
			f.setQueryRunes(nil, 0)
		} else {
			f.exitCode = 130
			f.finished = true
		}
	case "accept":
		if o.expectSet && o.expect[keyName] {
			f.expectKey = keyName
		}
		f.doAccept()
	case "accept-non-empty":
		if len(f.results) == 0 || (len(f.selected) == 0 && f.currentItem() == nil) {
			return
		}
		if o.expectSet && o.expect[keyName] {
			f.expectKey = keyName
		}
		f.doAccept()
	case "accept-or-print-query":
		if o.expectSet && o.expect[keyName] {
			f.expectKey = keyName
		}
		if len(f.results) == 0 && len(f.selected) == 0 {
			f.printOnNoMatch = true
			f.printQueryForced = true
			f.acceptWith(nil, 0)
			f.forcePrintQuery = true
			return
		}
		f.doAccept()
	case "bell":
		_, _ = f.tty.WriteString("\a")
	// ---- query editing ----
	case "backward-char":
		if f.qcursor > 0 {
			f.qcursor--
		}
	case "forward-char":
		if f.qcursor < len(f.query) {
			f.qcursor++
		}
	case "backward-delete-char", "backward-delete-char/eof":
		if len(f.query) == 0 {
			f.fireEvent("backward-eof")
			if a.name == "backward-delete-char/eof" {
				// The event may override; if it doesn't finish, abort.
				if !f.finished && len(f.eventQueue) == 0 {
					f.exitCode = 130
					f.finished = true
				}
			}
			return
		}
		if f.qcursor > 0 {
			q := append(append([]rune{}, f.query[:f.qcursor-1]...), f.query[f.qcursor:]...)
			f.setQueryRunes(q, f.qcursor-1)
		}
	case "delete-char", "delete-char/eof":
		if len(f.query) == 0 && a.name == "delete-char/eof" {
			f.exitCode = 130
			f.finished = true
			return
		}
		if f.qcursor < len(f.query) {
			q := append(append([]rune{}, f.query[:f.qcursor]...), f.query[f.qcursor+1:]...)
			f.setQueryRunes(q, f.qcursor)
		}
	case "beginning-of-line":
		f.qcursor = 0
	case "end-of-line":
		f.qcursor = len(f.query)
	case "backward-word":
		f.qcursor = prevWordBoundary(f.query, f.qcursor, o.filepathWord)
	case "forward-word":
		f.qcursor = nextWordBoundary(f.query, f.qcursor, o.filepathWord)
	case "backward-subword":
		f.qcursor = prevSubwordBoundary(f.query, f.qcursor)
	case "forward-subword":
		f.qcursor = nextSubwordBoundary(f.query, f.qcursor)
	case "backward-kill-word":
		start := prevWordBoundary(f.query, f.qcursor, o.filepathWord)
		f.killBuf = string(f.query[start:f.qcursor])
		q := append(append([]rune{}, f.query[:start]...), f.query[f.qcursor:]...)
		f.setQueryRunes(q, start)
	case "backward-kill-subword":
		start := prevSubwordBoundary(f.query, f.qcursor)
		f.killBuf = string(f.query[start:f.qcursor])
		q := append(append([]rune{}, f.query[:start]...), f.query[f.qcursor:]...)
		f.setQueryRunes(q, start)
	case "kill-word":
		end := nextWordBoundary(f.query, f.qcursor, o.filepathWord)
		f.killBuf = string(f.query[f.qcursor:end])
		q := append(append([]rune{}, f.query[:f.qcursor]...), f.query[end:]...)
		f.setQueryRunes(q, f.qcursor)
	case "kill-subword":
		end := nextSubwordBoundary(f.query, f.qcursor)
		f.killBuf = string(f.query[f.qcursor:end])
		q := append(append([]rune{}, f.query[:f.qcursor]...), f.query[end:]...)
		f.setQueryRunes(q, f.qcursor)
	case "kill-line":
		f.killBuf = string(f.query[f.qcursor:])
		f.setQueryRunes(append([]rune{}, f.query[:f.qcursor]...), f.qcursor)
	case "unix-line-discard":
		f.killBuf = string(f.query[:f.qcursor])
		f.setQueryRunes(append([]rune{}, f.query[f.qcursor:]...), 0)
	case "unix-word-rubout":
		// Delete back to whitespace (like shell Ctrl-W).
		i := f.qcursor
		for i > 0 && (f.query[i-1] == ' ' || f.query[i-1] == '\t') {
			i--
		}
		for i > 0 && f.query[i-1] != ' ' && f.query[i-1] != '\t' {
			i--
		}
		f.killBuf = string(f.query[i:f.qcursor])
		q := append(append([]rune{}, f.query[:i]...), f.query[f.qcursor:]...)
		f.setQueryRunes(q, i)
	case "yank":
		f.insertText(f.killBuf)
	case "clear-query":
		f.setQueryRunes(nil, 0)
	case "replace-query":
		if it := f.currentItem(); it != nil {
			txt := it.text
			f.setQueryRunes([]rune(txt), len([]rune(txt)))
		}
	case "clear-screen":
		// Force a full redraw on the next draw (our draws are full).
	// ---- cursor / list movement ----
	case "up":
		f.moveVisual(-1, false, false)
	case "down":
		f.moveVisual(1, false, false)
	case "up-match":
		f.moveVisual(-1, true, false)
	case "down-match":
		f.moveVisual(1, true, false)
	case "up-selected", "prev-selected":
		f.moveVisual(-1, false, true)
	case "down-selected", "next-selected":
		f.moveVisual(1, false, true)
	case "first":
		f.setCurrentResult(0, true)
	case "best":
		idx := 0
		for i, r := range f.results {
			if r.matched {
				idx = i
				break
			}
		}
		f.setCurrentResult(idx, true)
	case "last":
		f.setCurrentResult(len(f.results)-1, true)
	case "pos":
		n, err := strconv.Atoi(strings.TrimSpace(a.arg))
		if err == nil && n != 0 {
			idx := n - 1
			if n < 0 {
				idx = len(f.results) + n
			}
			f.setCurrentResult(idx, true)
		}
	case "page-up":
		f.moveVisual(-f.pageSize(), false, false)
	case "page-down":
		f.moveVisual(f.pageSize(), false, false)
	case "half-page-up":
		f.moveVisual(-f.pageSize()/2, false, false)
	case "half-page-down":
		f.moveVisual(f.pageSize()/2, false, false)
	case "offset-up":
		f.vOffset--
		if f.vOffset < 0 {
			f.vOffset = 0
		}
	case "offset-down":
		f.vOffset++
		maxOff := len(f.results) - 1
		if f.vOffset > maxOff && maxOff >= 0 {
			f.vOffset = maxOff
		}
	case "offset-middle":
		cur := f.visualIndexOfCurrent()
		f.vOffset = cur - f.listCapacityFor(f.currentSections.listInner.h)/2
		if f.vOffset < 0 {
			f.vOffset = 0
		}
	case "jump":
		f.enterJumpMode()
	// ---- selection ----
	case "select":
		if it := f.currentItem(); it != nil && o.multi != 0 {
			f.selectItem(it, true)
		}
	case "deselect":
		if it := f.currentItem(); it != nil {
			f.selectItem(it, false)
		}
	case "toggle":
		if it := f.currentItem(); it != nil && o.multi != 0 {
			f.selectItem(it, !f.selected[it.index])
		}
	case "toggle-all":
		if o.multi != 0 {
			allSel := len(f.results) > 0
			for _, r := range f.results {
				if !f.selected[r.item.index] {
					allSel = false
					break
				}
			}
			for _, r := range f.results {
				f.selectItem(r.item, !allSel)
			}
		}
	case "select-all":
		if o.multi != 0 {
			for _, r := range f.results {
				f.selectItem(r.item, true)
			}
		}
	case "deselect-all":
		for _, r := range f.results {
			delete(f.selected, r.item.index)
		}
		f.fireEvent("multi")
	case "clear-multi":
		f.selected = map[int]bool{}
		f.fireEvent("multi")
	case "toggle-in":
		if it := f.currentItem(); it != nil && o.multi != 0 {
			f.selectItem(it, !f.selected[it.index])
		}
		if f.current+1 < len(f.results) {
			f.setCurrentResult(f.current+1, true)
		} else if o.cycle && len(f.results) > 0 {
			f.setCurrentResult(0, true)
		}
	case "toggle-out":
		if it := f.currentItem(); it != nil && o.multi != 0 {
			f.selectItem(it, !f.selected[it.index])
		}
		if f.current > 0 {
			f.setCurrentResult(f.current-1, true)
		} else if o.cycle && len(f.results) > 0 {
			f.setCurrentResult(len(f.results)-1, true)
		}
	case "exclude":
		if it := f.currentItem(); it != nil {
			f.excluded[it.index] = true
			delete(f.selected, it.index)
			f.refilter(false)
		}
	case "exclude-multi":
		targets := f.selectedItemsInResultOrder()
		if len(targets) == 0 {
			if it := f.currentItem(); it != nil {
				targets = []*item{it}
			}
		}
		for _, it := range targets {
			f.excluded[it.index] = true
			delete(f.selected, it.index)
		}
		f.refilter(false)
	case "change-multi":
		if !a.argSet {
			o.multi = -1
		} else {
			n, err := strconv.Atoi(strings.TrimSpace(a.arg))
			if err == nil {
				o.multi = n
				if n == 0 {
					f.selected = map[int]bool{}
				}
			}
		}
	// ---- toggles & state ----
	case "toggle-sort":
		f.sortOn = !f.sortOn
		f.refilter(false)
	case "toggle-search":
		f.searchOff = !f.searchOff
		f.refilter(true)
	case "disable-search":
		f.searchOff = true
		f.refilter(true)
	case "enable-search":
		f.searchOff = false
		f.refilter(true)
	case "search":
		f.searchString = f.expandString(a.arg)
		f.searchOff = false
		f.refilter(true)
	case "transform-search":
		out := f.runTransformCommand(a.arg)
		f.searchString = out
		f.searchOff = false
		f.refilter(true)
	case "toggle-raw":
		f.rawMode = !f.rawMode
		f.refilter(true)
	case "enable-raw":
		f.rawMode = true
		f.refilter(true)
	case "disable-raw":
		f.rawMode = false
		f.refilter(true)
	case "toggle-track":
		f.trackOn = !f.trackOn
	case "toggle-track-current":
		f.trackCur = !f.trackCur
	case "track-current":
		f.trackCur = true
	case "untrack-current":
		if !f.trackOn {
			f.trackCur = false
		}
	case "toggle-hscroll":
		o.hscroll = !o.hscroll
	case "toggle-wrap":
		o.wrap = !o.wrap
	case "toggle-multi-line":
		o.multiLine = !o.multiLine
	case "toggle-preview":
		f.previewHidden = !f.previewHidden
	case "hide-preview":
		f.previewHidden = true
	case "show-preview":
		f.previewHidden = false
	case "close":
		if f.previewActive() && !f.previewHidden {
			f.previewHidden = true
		} else {
			f.exitCode = 130
			f.finished = true
		}
	case "toggle-preview-wrap":
		f.pw.wrap = !f.pw.wrap
	case "hide-header":
		f.headerHidden = true
	case "show-header":
		f.headerHidden = false
	case "toggle-header":
		f.headerHidden = !f.headerHidden
	case "hide-input":
		f.inputHidden = true
	case "show-input":
		f.inputHidden = false
	case "toggle-input":
		f.inputHidden = !f.inputHidden
	case "preview-up":
		f.previewScroll--
		if f.previewScroll < 0 {
			f.previewScroll = 0
		}
		f.previewScrollPending = false
	case "preview-down":
		f.previewScroll++
		f.previewScrollPending = false
	case "preview-page-up":
		f.previewScroll -= f.currentSections.previewInner.h
		if f.previewScroll < 0 {
			f.previewScroll = 0
		}
		f.previewScrollPending = false
	case "preview-page-down":
		f.previewScroll += f.currentSections.previewInner.h
		f.previewScrollPending = false
	case "preview-half-page-up":
		f.previewScroll -= f.currentSections.previewInner.h / 2
		if f.previewScroll < 0 {
			f.previewScroll = 0
		}
		f.previewScrollPending = false
	case "preview-half-page-down":
		f.previewScroll += f.currentSections.previewInner.h / 2
		f.previewScrollPending = false
	case "preview-top":
		f.previewScroll = 0
		f.previewScrollPending = false
	case "preview-bottom":
		f.previewScroll = len(f.previewLines)
		f.previewScrollPending = false
	case "refresh-preview":
		f.previewKey = ""
	case "preview":
		f.previewCmd = a.arg
		f.previewCmdSet = true
		f.previewHidden = false
		f.previewKey = ""
	// ---- change-* ----
	case "change-query":
		txt := f.expandString(a.arg)
		f.setQueryRunes([]rune(txt), len([]rune(txt)))
	case "change-prompt":
		f.promptStr = f.expandString(a.arg)
	case "change-ghost":
		f.ghostStr = f.expandString(a.arg)
	case "change-header":
		f.headerText = f.expandString(a.arg)
	case "change-footer":
		f.footerText = f.expandString(a.arg)
	case "change-border-label":
		f.borderLabelStr = f.expandString(a.arg)
	case "change-list-label":
		f.listLabelStr = f.expandString(a.arg)
	case "change-input-label":
		f.inputLabelStr = f.expandString(a.arg)
	case "change-header-label":
		f.headerLabelStr = f.expandString(a.arg)
	case "change-footer-label":
		f.footerLabelStr = f.expandString(a.arg)
	case "change-preview-label":
		f.previewLabelStr = f.expandString(a.arg)
	case "change-pointer":
		f.pointerStr = f.expandString(a.arg)
		f.o.pointerSet = true
	case "change-preview":
		f.previewCmd = a.arg
		f.previewCmdSet = true
		f.previewHidden = false
		f.previewKey = ""
	case "change-preview-window":
		f.applyChangePreviewWindow(a.arg)
	case "change-nth":
		f.applyChangeNth(a.arg)
	case "print":
		f.printQueue = append(f.printQueue, f.expandString(a.arg))
	case "put":
		if a.argSet {
			f.insertText(f.expandString(a.arg))
		}
	// ---- transform-* ----
	case "transform-query":
		out := f.runTransformCommand(a.arg)
		f.setQueryRunes([]rune(out), len([]rune(out)))
	case "transform-prompt":
		f.promptStr = f.runTransformCommand(a.arg)
	case "transform-ghost":
		f.ghostStr = f.runTransformCommand(a.arg)
	case "transform-header":
		f.headerText = f.runTransformCommand(a.arg)
	case "transform-footer":
		f.footerText = f.runTransformCommand(a.arg)
	case "transform-border-label":
		f.borderLabelStr = f.runTransformCommand(a.arg)
	case "transform-list-label":
		f.listLabelStr = f.runTransformCommand(a.arg)
	case "transform-input-label":
		f.inputLabelStr = f.runTransformCommand(a.arg)
	case "transform-header-label":
		f.headerLabelStr = f.runTransformCommand(a.arg)
	case "transform-footer-label":
		f.footerLabelStr = f.runTransformCommand(a.arg)
	case "transform-preview-label":
		f.previewLabelStr = f.runTransformCommand(a.arg)
	case "transform-pointer":
		f.pointerStr = f.runTransformCommand(a.arg)
		f.o.pointerSet = true
	case "transform-nth":
		out := f.runTransformCommand(a.arg)
		f.setNthFromString(out)
	case "transform":
		out := f.runTransformCommand(a.arg)
		f.dispatchTransformedActions(out)
	default:
		if strings.HasPrefix(a.name, "bg-transform") {
			f.runBgTransform(a)
			return
		}
		switch a.name {
		case "execute":
			f.executeInteractive(a.arg)
		case "execute-silent":
			f.executeSilent(a.arg)
			f.refilter(false)
		case "become":
			expanded, _ := f.expandCommand(a.arg)
			f.becomeCmd = expanded
			f.exitCode = 0
			f.finished = true
		case "reload":
			f.startReload(a.arg, false)
		case "reload-sync":
			f.startReload(a.arg, true)
		case "unbind":
			f.unbindKeys(a.arg)
		case "rebind":
			f.rebindKeys(a.arg)
		case "toggle-bind":
			f.toggleBindKeys(a.arg)
		case "trigger":
			for _, name := range strings.Split(a.arg, ",") {
				name = strings.TrimSpace(name)
				if name == "" {
					continue
				}
				if canon, err := canonicalKeyName(name); err == nil {
					if acts, ok := f.keymap[canon]; ok {
						f.executeActions(append([]action{}, acts...), canon)
					} else if isEventName(canon) {
						f.fireEvent(canon)
					}
				}
			}
		case "bg-cancel":
			for _, cancel := range f.bgTransforms {
				if cancel != nil {
					cancel()
				}
			}
			f.bgTransforms = map[int]func(){}
		case "next-history":
			f.historyMove(1)
		case "prev-history":
			f.historyMove(-1)
		}
	}
}

func (f *finder) dispatchTransformedActions(out string) {
	out = strings.TrimSpace(out)
	if out == "" {
		return
	}
	// The output can be a chain of actions separated by '+' and may
	// contain newlines separating whole chains.
	for _, line := range strings.Split(out, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		acts, err := parseActionString(line)
		if err != nil {
			continue
		}
		f.executeActions(acts, f.lastKey)
		if f.finished {
			return
		}
	}
}

type bgTransformResult struct {
	gen    int
	target string
	value  string
}

func (f *finder) runBgTransform(a action) {
	target := strings.TrimPrefix(a.name, "bg-")
	f.bgGen++
	gen := f.bgGen
	f.bgTransforms[gen] = func() {}
	done := make(chan bgTransformResult, 1)
	if f.bgCh == nil {
		f.bgCh = make(chan bgTransformResult, 16)
	}
	ch := f.bgCh
	go func() {
		out := f.runTransformCommand(a.arg)
		done <- bgTransformResult{gen: gen, target: target, value: out}
		select {
		case ch <- (<-done):
		default:
		}
	}()
	// The result is applied by the main loop through a lightweight
	// polling goroutine bridge: we apply it lazily in draw via drainBg.
	f.bgPending = append(f.bgPending, ch)
}

func (f *finder) historyMove(dir int) {
	h := f.o.history
	if h == nil {
		return
	}
	if !h.savedSet {
		h.saved = string(f.query)
		h.savedSet = true
		h.pos = len(h.lines)
	}
	pos := h.pos + dir
	if pos < 0 {
		pos = 0
	}
	if pos > len(h.lines) {
		pos = len(h.lines)
	}
	h.pos = pos
	var q string
	if pos == len(h.lines) {
		q = h.saved
	} else {
		q = h.lines[pos]
	}
	f.setQueryRunes([]rune(q), len([]rune(q)))
}

func (f *finder) selectItem(it *item, on bool) {
	if on {
		if f.o.multi > 0 && !f.selected[it.index] && len(f.selected) >= f.o.multi {
			return
		}
		if !f.selected[it.index] {
			f.selected[it.index] = true
			f.fireEvent("multi")
		}
	} else {
		if f.selected[it.index] {
			delete(f.selected, it.index)
			f.fireEvent("multi")
		}
	}
}

func (f *finder) pageSize() int {
	n := f.listCapacityFor(f.currentSections.listInner.h)
	if n <= 0 {
		return 1
	}
	return n
}

func (f *finder) enterJumpMode() {
	if len(f.results) == 0 {
		return
	}
	f.jumpMode = true
	f.jumpLabels = map[rune]int{}
	labels := f.o.jumpLabels
	if !f.o.jumpLabelsSet {
		labels = "abcdefghijklmnopqrstuvwxyz"
	}
	vis := f.visualOrder()
	capacity := f.listCapacityFor(f.currentSections.listInner.h)
	runes := []rune(labels)
	for i := 0; i < capacity && f.vOffset+i < len(vis); i++ {
		if i < len(runes) {
			f.jumpLabels[runes[i]] = f.vOffset + i
		}
	}
}

func (f *finder) handleJumpKey(ev keyEvent) bool {
	f.jumpMode = false
	if ev.r != 0 {
		if vi, ok := f.jumpLabels[ev.r]; ok {
			f.setCurrentResult(f.resultIndexOfVisual(vi), true)
			f.fireEvent("jump")
			return true
		}
	}
	if ev.name == "esc" || ev.name == "ctrl-c" || ev.name == "ctrl-g" {
		f.fireEvent("jump-cancel")
		return true
	}
	f.fireEvent("jump-cancel")
	return true
}

func (f *finder) applyChangePreviewWindow(arg string) {
	argExpanded := arg
	key := argExpanded
	windows, err := parseChangePreviewWindow(argExpanded, f.pw)
	if err != nil || len(windows) == 0 {
		return
	}
	idx := f.rotateState[key]
	f.pw = windows[idx%len(windows)]
	f.rotateState[key] = idx + 1
	f.previewHidden = f.pw.hidden
}

func (f *finder) applyChangeNth(arg string) {
	parts := strings.Split(arg, "|")
	argExpanded := arg
	idx := f.rotateState["nth:"+argExpanded]
	part := parts[idx%len(parts)]
	f.rotateState["nth:"+argExpanded] = idx + 1
	f.setNthFromString(strings.TrimSpace(part))
	f.refilter(true)
}

func (f *finder) setNthFromString(s string) {
	s = strings.TrimSpace(s)
	if s == "" {
		empty := []fieldRange{}
		f.nthOverride = &empty
		f.nthOverrideStr = ""
		return
	}
	ranges, err := parseRangeList(s)
	if err != nil {
		return
	}
	f.nthOverride = &ranges
	f.nthOverrideStr = s
}

func (f *finder) unbindKeys(arg string) {
	for _, k := range strings.Split(arg, ",") {
		k = strings.TrimSpace(k)
		if k == "" {
			continue
		}
		canon, err := canonicalKeyName(k)
		if err != nil {
			continue
		}
		if existing, ok := f.keymap[canon]; ok {
			f.unboundStack[canon] = append(f.unboundStack[canon], savedBinding{actions: existing, present: true})
		} else {
			f.unboundStack[canon] = append(f.unboundStack[canon], savedBinding{present: false})
		}
		delete(f.keymap, canon)
	}
}

func (f *finder) rebindKeys(arg string) {
	for _, k := range strings.Split(arg, ",") {
		k = strings.TrimSpace(k)
		if k == "" {
			continue
		}
		canon, err := canonicalKeyName(k)
		if err != nil {
			continue
		}
		stack := f.unboundStack[canon]
		if len(stack) == 0 {
			continue
		}
		saved := stack[len(stack)-1]
		f.unboundStack[canon] = stack[:len(stack)-1]
		if saved.present {
			f.keymap[canon] = saved.actions
		} else {
			delete(f.keymap, canon)
		}
	}
}

func (f *finder) toggleBindKeys(arg string) {
	for _, k := range strings.Split(arg, ",") {
		k = strings.TrimSpace(k)
		if k == "" {
			continue
		}
		canon, err := canonicalKeyName(k)
		if err != nil {
			continue
		}
		if _, ok := f.keymap[canon]; ok {
			f.unbindKeys(canon)
		} else {
			f.rebindKeys(canon)
		}
	}
}

func (f *finder) handleMouse(ev keyEvent) bool {
	m := ev.mouse
	if m == nil {
		return false
	}
	secs := f.currentSections
	// Wheel scrolls the list (or preview when over it).
	if m.wheel != 0 {
		if secs.hasPreview && m.x >= secs.preview.x && m.x < secs.preview.right() && m.y >= secs.preview.y && m.y < secs.preview.bottom() {
			name := "preview-scroll-down"
			if m.wheel < 0 {
				name = "preview-scroll-up"
			}
			if acts, ok := f.keymap[name]; ok {
				f.executeActions(acts, name)
			} else {
				f.previewScroll += m.wheel
				if f.previewScroll < 0 {
					f.previewScroll = 0
				}
			}
			return true
		}
		if acts, ok := f.keymap[ev.name]; ok {
			f.executeActions(acts, ev.name)
			return true
		}
		// Default: move the cursor by the wheel direction (physical).
		if m.wheel > 0 {
			f.moveVisual(1, false, false)
		} else {
			f.moveVisual(-1, false, false)
		}
		return true
	}
	// Determine the target item from the clicked row.
	targetVisual := -1
	for _, row := range f.listRows {
		if row.y == m.y {
			targetVisual = row.visual
			break
		}
	}
	if !m.release {
		f.mousePressX, f.mousePressY = m.x, m.y
		f.mousePressValid = true
		if targetVisual >= 0 {
			f.setCurrentResult(f.resultIndexOfVisual(targetVisual), true)
		}
		return true
	}
	// Release: a click fires when released on the same cell.
	if !f.mousePressValid || f.mousePressX != m.x || f.mousePressY != m.y {
		f.mousePressValid = false
		return true
	}
	f.mousePressValid = false
	// Header / footer clicks fire their events.
	if secs.hasHeader && m.y >= secs.headerBox.y && m.y < secs.headerBox.bottom() && m.x >= secs.headerBox.x && m.x < secs.headerBox.right() {
		f.clickExtra = map[string]string{
			"FZF_CLICK_HEADER_LINE":   itoa(m.y - secs.headerBox.y + 1),
			"FZF_CLICK_HEADER_COLUMN": itoa(m.x - secs.headerBox.x + 1),
		}
		f.fireEvent("click-header")
		return true
	}
	if secs.hasFooter && m.y >= secs.footerBox.y && m.y < secs.footerBox.bottom() && m.x >= secs.footerBox.x && m.x < secs.footerBox.right() {
		f.clickExtra = map[string]string{
			"FZF_CLICK_FOOTER_LINE":   itoa(m.y - secs.footerBox.y + 1),
			"FZF_CLICK_FOOTER_COLUMN": itoa(m.x - secs.footerBox.x + 1),
		}
		f.fireEvent("click-footer")
		return true
	}
	now := time.Now()
	isDouble := now.Sub(f.lastClickTime) < 400*time.Millisecond && f.lastClickX == m.x && f.lastClickY == m.y
	f.lastClickTime = now
	f.lastClickX, f.lastClickY = m.x, m.y
	name := ev.name
	if isDouble && m.button == 0 {
		name = "double-click"
	}
	if acts, ok := f.keymap[name]; ok {
		f.executeActions(acts, name)
		return true
	}
	return true
}

func itoa(n int) string { return strconv.Itoa(n) }
