	case "backward-delete-char", "backward-delete-char/eof":
		if len(f.query) == 0 {
			f.fireEvent("backward-eof")
			if a.name == "backward-delete-char/eof" {
				// The event may override; if it doesn't finish, abort.
				if !f.finished && len(f.eventQueue) == 0 {
					f.exitCode = 130
					f.finished = true
				}
			}
			return
		}
		if f.qcursor > 0 {
			q := append(append([]rune{}, f.query[:f.qcursor-1]...), f.query[f.qcursor:]...)
			f.setQueryRunes(q, f.qcursor-1)
		}
	case "delete-char", "delete-char/eof":
