package main

import (
	"strings"
	"sync/atomic"
)

type reloadLine struct {
	gen       int
	line      string
	done      bool
	syncLines []string
	header    []string
	isHeader  bool
}

func (f *finder) startReload(template string, syncMode bool) {
	expanded, temps := f.expandCommand(template)
	f.reloadGen++
	gen := f.reloadGen
	if f.reloadCancel != nil {
		f.reloadCancel()
	}
	f.inputSuperseded = true
	cmd := shellCommand(expanded, f.o)
	cmd.Env = f.childEnv(nil)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		removeTemps(temps)
		return
	}
	if err := cmd.Start(); err != nil {
		removeTemps(temps)
		return
	}
	var killed atomic.Bool
	f.reloadCancel = func() {
		killed.Store(true)
		if cmd.Process != nil {
			_ = cmd.Process.Kill()
		}
	}
	if f.reloadLineCh == nil {
		f.reloadLineCh = make(chan reloadLine, 4096)
	}
	ch := f.reloadLineCh
	if syncMode {
		go func() {
			var lines []string
			var headers []string
			headerLeft := f.o.headerLines
			streamItems(stdout, f.o.read0, func(s string) {
				if headerLeft > 0 {
					headerLeft--
					txt := s
					if f.o.ansi {
						txt, _ = stripAnsi(s)
					}
					headers = append(headers, txt)
					return
				}
				lines = append(lines, s)
			})
			_ = cmd.Wait()
			removeTemps(temps)
			if killed.Load() {
				return
			}
			ch <- reloadLine{gen: gen, done: true, syncLines: lines, header: headers}
		}()
		return
	}
	// Asynchronous reload: clear the list now.
	f.mu.Lock()
	f.items = nil
	f.headerLineTexts = nil
	f.reading = true
	f.inputDone = false
	f.mu.Unlock()
	f.nextIndex = 0
	f.selected = map[int]bool{}
	f.excluded = map[int]bool{}
	f.current = -1
	f.vOffset = 0
	f.reloadHeaderLeft = f.o.headerLines
	go func() {
		streamItems(stdout, f.o.read0, func(s string) {
			if killed.Load() {
				return
			}
			ch <- reloadLine{gen: gen, line: s}
		})
		_ = cmd.Wait()
		removeTemps(temps)
		if killed.Load() {
			return
		}
		ch <- reloadLine{gen: gen, done: true}
	}()
}

func (f *finder) handleReloadLine(rl reloadLine) {
	if rl.gen != f.reloadGen {
		return
	}
	if rl.syncLines != nil {
		// Atomic replacement.
		f.mu.Lock()
		f.items = nil
		f.headerLineTexts = rl.header
		f.mu.Unlock()
		f.nextIndex = 0
		f.selected = map[int]bool{}
		f.excluded = map[int]bool{}
		for _, line := range rl.syncLines {
			f.addRawItem(line)
		}
		f.mu.Lock()
		f.reading = false
		f.inputDone = true
		f.mu.Unlock()
		f.refilter(true)
		f.fireEvent("load")
		f.maybeFireOneZero()
		return
	}
	if rl.done {
		f.mu.Lock()
		f.reading = false
		f.inputDone = true
		f.mu.Unlock()
		f.refilter(false)
		f.fireEvent("load")
		f.maybeFireOneZero()
		return
	}
	if f.reloadHeaderLeft > 0 {
		f.reloadHeaderLeft--
		txt := rl.line
		if f.o.ansi {
			txt, _ = stripAnsi(rl.line)
		}
		f.mu.Lock()
		f.headerLineTexts = append(f.headerLineTexts, txt)
		f.mu.Unlock()
		return
	}
	f.addRawItem(rl.line)
	f.refilter(false)
	f.maybeFireOneZero()
}

func (f *finder) applyBgResult(res bgTransformResult) {
	// transform target names are e.g. "transform-header".
	target := res.target
	val := strings.TrimRight(res.value, "\n")
	switch target {
	case "transform":
		f.dispatchTransformedActions(val)
	case "transform-query":
		f.setQueryRunes([]rune(val), len([]rune(val)))
	case "transform-search":
		f.searchString = val
		f.searchOff = false
		f.refilter(true)
	case "transform-prompt":
		f.promptStr = val
	case "transform-ghost":
		f.ghostStr = val
	case "transform-header":
		f.headerText = val
	case "transform-footer":
		f.footerText = val
	case "transform-border-label":
		f.borderLabelStr = val
	case "transform-list-label":
		f.listLabelStr = val
	case "transform-input-label":
		f.inputLabelStr = val
	case "transform-header-label":
		f.headerLabelStr = val
	case "transform-footer-label":
		f.footerLabelStr = val
	case "transform-preview-label":
		f.previewLabelStr = val
	case "transform-pointer":
		f.pointerStr = val
		f.o.pointerSet = true
	case "transform-nth":
		f.setNthFromString(val)
		f.refilter(true)
	}
}
