					w.WriteHeader(http.StatusBadRequest)
					_, _ = w.Write([]byte("remote process execution is not allowed\n"))
					return
				}
				allActs = append(allActs, acts...)
			}
			ch <- allActs
			w.WriteHeader(http.StatusOK)
		default:
			w.WriteHeader(http.StatusMethodNotAllowed)
		}
	})
	go func() {
		_ = http.Serve(ln, mux)
	}()
	f.httpListener = ln
}

func isRemoteAddr(addr string) bool {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return false
	}
	ip := net.ParseIP(host)
	if ip == nil {
		return host != "localhost"
	}
	return !ip.IsLoopback()
}

func containsExecAction(acts []action) bool {
	for _, a := range acts {
		switch a.name {
		case "execute", "execute-silent", "become", "reload", "reload-sync", "preview", "transform", "change-preview":
			return true
		}
		if strings.HasPrefix(a.name, "transform") || strings.HasPrefix(a.name, "bg-transform") {
			return true
		}
	}
	return false
}

func (f *finder) serveState(w http.ResponseWriter, r *http.Request) {
	limit := 100
	offset := 0
	if v := r.URL.Query().Get("limit"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			limit = n
		}
	}
	if v := r.URL.Query().Get("offset"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			offset = n
		}
	}
	type itemJSON struct {
		Index int    `json:"index"`
		Text  string `json:"text"`
	}
	matched := 0
	for _, res := range f.results {
		if res.matched {
			matched++
		}
	}
	if !f.rawMode {
		matched = len(f.results)
	}
	var matches []itemJSON
	for i, res := range f.results {
		if i < offset {
			continue
		}
		if len(matches) >= limit && limit >= 0 {
			break
		}
		matches = append(matches, itemJSON{Index: res.item.index, Text: res.item.orig})
	}
	if matches == nil {
		matches = []itemJSON{}
	}
	var selected []itemJSON
	for _, it := range f.selectedItemsInResultOrder() {
		selected = append(selected, itemJSON{Index: it.index, Text: it.orig})
	}
	if selected == nil {
		selected = []itemJSON{}
	}
	progress := 100
	if f.isReading() {
		progress = 0
		// fzf reports a percentage while candidates are still arriving only if
		// the total is known; with streams it stays at 100 in practice once
		// the first batch is ready.  Keep 100 unless we just started.
		if len(f.items) == 0 {
			progress = 0
		} else {
			progress = 100
		}
	}
	state := map[string]any{
		"reading":    f.isReading(),
		"progress":   progress,
		"query":      string(f.query),
		"position":   maxInt(0, f.current),
		"sort":       f.sortOn,
		"totalCount": len(f.items),
		"matchCount": matched,
		"matches":    matches,
		"selected":   selected,
	}
	if it := f.currentItem(); it != nil {
		state["current"] = itemJSON{Index: it.index, Text: it.orig}
	}
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(state)
}
