package main

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

func shellQuoteArg(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func runTmuxPopup(o *options) int {
	// Drain piped stdin to a temp file if needed.
	var inputFile string
	stdinIsTTY := isTerminalFD(int(os.Stdin.Fd()))
	if !stdinIsTTY {
		f, err := os.CreateTemp("", "fzf-tmux-input-")
		if err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			return 2
		}
		inputFile = f.Name()
		_, _ = io.Copy(f, os.Stdin)
		_ = f.Close()
		defer os.Remove(inputFile)
	}
	outFile, err := os.CreateTemp("", "fzf-tmux-output-")
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return 2
	}
	outName := outFile.Name()
	_ = outFile.Close()
	defer os.Remove(outName)

	args := filterTmuxArgs(os.Args[1:])
	var cmdParts []string
	self, _ := os.Executable()
	if self == "" {
		self = os.Args[0]
	}
	cmdParts = append(cmdParts, shellQuoteArg(self))
	for _, a := range args {
		cmdParts = append(cmdParts, shellQuoteArg(a))
	}
	inner := strings.Join(cmdParts, " ")
	if inputFile != "" {
		inner += " < " + shellQuoteArg(inputFile)
	}
	inner += " > " + shellQuoteArg(outName)

	tc := o.tmux
	width := tmuxSizeArg(tc.width)
	height := tmuxSizeArg(tc.height)
	tmuxArgs := []string{"display-popup", "-E"}
	if width != "" {
		tmuxArgs = append(tmuxArgs, "-w", width)
	}
	if height != "" {
		tmuxArgs = append(tmuxArgs, "-h", height)
	}
	switch tc.position {
	case "top":
		tmuxArgs = append(tmuxArgs, "-x", "C", "-y", "0")
	case "bottom":
		tmuxArgs = append(tmuxArgs, "-x", "C", "-y", "100%")
	case "left":
		tmuxArgs = append(tmuxArgs, "-x", "0", "-y", "C")
	case "right":
		tmuxArgs = append(tmuxArgs, "-x", "100%", "-y", "C")
	}
	if tc.borderNative {
		// Native tmux border: let tmux draw it (default popup border).
	} else {
		tmuxArgs = append(tmuxArgs, "-B")
	}
	tmuxArgs = append(tmuxArgs, "-e", "FZF_TMUX_POPUP=1")
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "sh"
	}
	tmuxArgs = append(tmuxArgs, shell, "-c", inner)
	cmd := exec.Command("tmux", tmuxArgs...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	 runErr := cmd.Run()
	data, _ := os.ReadFile(outName)
	_, _ = os.Stdout.Write(data)
	if runErr != nil {
		if exitErr, ok := runErr.(*exec.ExitError); ok {
			return exitErr.ExitCode()
		}
		return 2
	}
	// display-popup exits 0 regardless; the inner command's output file
	// emptiness approximates no-match in simple cases.  Stores from the
	//
	// inner process are not available through tmux itself, so fall back to
	// emptiness.
	if len(data) == 0 && o.filter == nil {
		// An aborted popup produces no output; the reference propagates
		// the inner exit via a status file which we do not use here.
		return 130
	}
	return 0
}

func tmuxSizeArg(s sizeSpec) string {
	if s.percent {
		return strconv.Itoa(int(s.num)) + "%"
	}
	if s.num == 0 {
		return ""
	}
	return strconv.Itoa(int(s.num))
}

func filterTmuxArgs(args []string) []string {
	var out []string
	for _, a := range args {
		if a == "--tmux" || strings.HasPrefix(a, "--tmux=") {
			continue
		}
		out = append(out, a)
	}
	return out
}
