func runInteractive(o *options, stdinIsTTY bool) int {
	if o.select1 || o.exit0 {
		raw := readAllInput(o, stdinIsTTY)
		items := buildItems(raw, o)
		p := o.buildPatternFor(o.query)
		if o.disabled {
			p = buildPattern("", o.caseMode, o.fuzzy, o.extended, true, o.algoV1)
		}
		// A throwaway options-based filter to evaluate the pre-check
		// without mutating a real finder.
		tmp := &finder{o: o, selected: map[int]bool{}, excluded: map[int]bool{}, sortOn: o.sort, searchOff: o.disabled, query: []rune(o.query), previewFor: -2}
		_ = tmp
		results := o.filterItems(items, p, false)
		if o.exit0 && len(results) == 0 {
			sep := outputSeparator(o)
			if o.printQuery {
				printString(o.query + sep)
			}
			if o.expectSet {
				printString(sep)
			}
			return 1
		}
		if o.select1 && len(results) == 1 {
			sep := outputSeparator(o)
			if o.printQuery {
				printString(o.query + sep)
			}
			if o.expectSet {
				printString(sep)
			}
			printString(o.transformForOutput(results[0].item) + sep)
			if o.history != nil {
				o.history.append(o.query, o.historySize)
			}
			return 0
		}
		return runTerminal(o, stdinIsTTY, items)
	}
	return runTerminal(o, stdinIsTTY, nil)
}
