new=r'''// evalScrollExpr evaluates an expression like "+{2}-5/2" to the
// zero-based body scroll offset (used as previewScroll).
func evalScrollExpr(expr string, f *finder) int {
	s := strings.TrimPrefix(expr, "+")
	denom := 0
	if idx := strings.LastIndex(s, "/"); idx >= 0 {
		if d, err := strconv.Atoi(s[idx+1:]); err == nil && d > 0 {
			denom = d
		}
		s = s[:idx]
	}
	total := 0
	i := 0
	sign := 1
	for i < len(s) {
		if s[i] == '+' {
			sign = 1
			i++
			continue
		}
		if s[i] == '-' {
			sign = -1
			i++
			continue
		}
		var val int
		if s[i] == '{' {
			end := strings.IndexByte(s[i:], '}')
			if end < 0 {
				break
			}
			content := s[i+1 : i+end]
			val = f.scrollPlaceholderValue(content)
			i += end + 1
		} else {
			j := i
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				j++
			}
			if j == i {
				break
			}
			val, _ = strconv.Atoi(s[i:j])
			i = j
		}
		total += sign * val
		sign = 1
	}
	pv := f.previewLayoutEffective()
	innerH := f.currentSections.previewInner.h
	bodyH := innerH - pv.headerLines
	if bodyH < 0 {
		bodyH = 0
	}
	firstLine := total // 1-based line to show first in the body
	if denom > 0 {
		firstLine -= bodyH / denom
	}
	scroll := firstLine - 1 - pv.headerLines
	if scroll < 0 {
		scroll = 0
	}
	return scroll
}

'''
s=s[:start]+new+s[end:]
# Clamp preview scroll in drawPreview
s=s.replace("""	lines := f.previewLines
	start := f.previewScroll
	if start < 0 {
		start = 0
	}""", """	lines := f.previewLines
	start := f.previewScroll
	if start < 0 {
		start = 0
	}
	if maxStart := len(lines) - r.h; maxStart >= 0 && start > maxStart {
		// Keep the last line at the bottom rather than scrolling past it,
		// while still allowing the scroll offset to name the first line
		// when fewer lines remain in a taller window.
		if len(lines) > r.h {
			start = maxStart
		}
	}""")
p.write_text(s)
# --- result event helper in finder_run.go
p=pathlib.Path("finder_run.go"); s=p.read_text()
s=s.replace("""	resultFired := false
	maybeFireResult := func() {
		if resultFired {
			return
		}
		// `result` fires after the initial filtering completes.
	}
	_ = maybeFireResult""", """	_ = 0""")
s=s.replace("""			f.refilter(false)
			f.maybeFireOneZero()
			if f.processQueuedEvents() {
				break
			}
			f.draw()
		case <-itemDone:""", """			f.refilter(false)
			f.maybeFireOneZero()
			f.fireResultIfNeeded()
			if f.processQueuedEvents() {
				break
			}
			f.draw()
		case <-itemDone:""")
s=s.replace("""			f.maybeFireOneZero()
			if f.processQueuedEvents() {
				break
			}
			f.draw()
			// With --sync, start/load/result/focus actions have been
			// processed above before any terminal interaction was
			// possible (they run in this same goroutine).
			resultFired = true""", """			f.maybeFireOneZero()
			f.fireResultIfNeeded()
			if f.processQueuedEvents() {
				break
			}
			f.draw()""")
# append helper methods at end
s += r'''
func (f *finder) fireResultIfNeeded() {
	if f.resultVersion != f.lastResultFired {
		f.lastResultFired = f.resultVersion
		f.fireEvent("result")
	}
}
'''
p.write_text(s)
# state.go: fire result from applyPending (after change)
p=pathlib.Path("state.go"); s=p.read_text()
s=s.replace("""	f.refilter(reset)
	f.fireEvent("change")
	f.maybeFireOneZero()""", """	f.refilter(reset)
	f.fireEvent("change")
	f.maybeFireOneZero()
	f.fireResultIfNeeded()""")
p.write_text(s)
PY
