# Add drainInitialInput method before runInteractive at end of file
s += r'''
func (f *finder) drainInitialInput(itemCh chan string, itemDone chan struct{}, syncMode bool) bool {
	drainBuffered := func() {
		for {
			select {
			case line := <-itemCh:
				if !f.inputSuperseded {
					f.addRawItem(line)
				}
			default:
				return
			}
		}
	}
	if syncMode {
		for {
			select {
			case line := <-itemCh:
				if !f.inputSuperseded {
					f.addRawItem(line)
				}
			case <-itemDone:
				drainBuffered()
				f.mu.Lock()
				f.reading = false
				f.inputDone = true
				f.mu.Unlock()
				return true
			}
		}
	}
	// Non-sync: give the producer a brief chance to deliver the first
	// batch (and the whole input when it is a fast pipe).
	deadline := time.NewTimer(60 * time.Millisecond)
	defer deadline.Stop()
	idle := time.NewTimer(30 * time.Millisecond)
	defer idle.Stop()
	gotAny := false
	for {
		select {
		case line := <-itemCh:
			if !f.inputSuperseded {
				f.addRawItem(line)
			}
			gotAny = true
			if !idle.Stop() {
				select {
				case <-idle.C:
				default:
				}
			}
			idle.Reset(5 * time.Millisecond)
		case <-itemDone:
			drainBuffered()
			f.mu.Lock()
			f.reading = false
			f.inputDone = true
			f.mu.Unlock()
			return true
		case <-idle.C:
			if gotAny {
				return false
			}
			// Keep waiting until the overall deadline for the first item.
			idle.Reset(30 * time.Millisecond)
		case <-deadline.C:
			return false
		}
	}
}
'''
p.write_text(s)
