			// cannot be stat'ed, is emitted as a file below.
			if lst, lerr := os.Lstat(root); lerr == nil && !lst.IsDir() {
				if o.walkerFile {
					emit(root)
				}
			}
			return
		}
		if !st.IsDir() {
			if o.walkerFile {
				emit(root)
			}
			return
		}
		display := root
		if root == "." {
			display = ""
		}
		queue = append(queue, dirTask{fs: root, display: display})
	}
	for _, root := range roots {
		appendRoot(root)
	}
	for len(queue) > 0 {
