			isDir := e.IsDir()
			if isSymlink {
				if st, err := os.Stat(fsPath); err == nil && st.IsDir() {
					if !o.walkerFollow {
						continue
					}
					isDir = true
				}
			}
			if isDir {
				if skip[name] {
					continue
				}
				if !o.walkerHidden && strings.HasPrefix(name, ".") {
					continue
				}
				if o.walkerDir {
					emit(display + "/")
