	// Header lines of the preview output are fixed at the top.
	pv := f.previewLayoutEffective()
	header := pv.headerLines
	// Build visual (wrapped) rows for header and body separately.
	type vrow struct {
		lineIdx int
		start   int
		end     int
		cont    bool
	}
	buildRows := func(from, to int) []vrow {
		var rows []vrow
		width := r.w
		signW := 0
		if pv.wrap {
			sign := "↳ "
			if !f.o.unicode {
				sign = "> "
			}
			signW = stringDisplayWidth(sign, f.o.ambidouble, f.o.tabstop)
		}
		for li := from; li < to && li < len(lines); li++ {
			runes := []rune(lines[li].text)
			if !pv.wrap || width <= 0 {
				rows = append(rows, vrow{lineIdx: li, start: 0, end: len(runes)})
				continue
			}
			if len(runes) == 0 {
				rows = append(rows, vrow{lineIdx: li, start: 0, end: 0})
				continue
			}
			pos := 0
			first := true
