				if !first {
					capacity = width - signW
					if capacity < 1 {
						capacity = 1
					}
				}
				end := pos
				wsum := 0
				for end < len(runes) {
					w := runeDisplayWidth(runes[end], f.o.ambidouble)
					if runes[end] == '\\t' {
						w = f.o.tabstop - (wsum % maxInt(1, f.o.tabstop))
					}
					if wsum+w > capacity {
						break
					}
					wsum += w
					end++
				}
				if end == pos {
					end = pos + 1
				}
				rows = append(rows, vrow{lineIdx: li, start: pos, end: end, cont: !first})
				pos = end
				first = false
			}
		}
		return rows
	}
