package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"os"
	"strconv"
	"strings"
)

func createListener(o *options) (net.Listener, string) {
	if o.listen.socket == "" {
		addr := o.listen.addr
		isLocal := addr == "" || addr == "localhost" || addr == "127.0.0.1"
		if !isLocal && os.Getenv("FZF_API_KEY") == "" {
			return nil, "FZF_API_KEY is required to allow remote access"
		}
	}
	var ln net.Listener
	var err error
	if o.listen.socket != "" {
		_ = os.Remove(o.listen.socket)
		ln, err = net.Listen("unix", o.listen.socket)
		if err != nil {
			return nil, fmt.Sprintf("failed to listen on %s", o.listen.socket)
		}
	} else {
		host := o.listen.addr
		ln, err = net.Listen("tcp", fmt.Sprintf("%s:%d", host, o.listen.port))
		if err != nil {
			display := fmt.Sprintf("%s:%d", host, o.listen.port)
			return nil, fmt.Sprintf("failed to listen on %s", display)
		}
	}
	return ln, ""
}

func (f *finder) startHTTPServer(ch chan []action) {
	ln := f.preListener
	if ln == nil {
		var msg string
		ln, msg = createListener(f.o)
		if msg != "" {
			return
		}
	}
	if tcp, ok := ln.Addr().(*net.TCPAddr); ok {
		f.listenPort = tcp.Port
	}
	f.httpListener = ln
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			go f.handleHTTPConn(conn, ch)
		}
	}()
}

func writeHTTPResponse(conn net.Conn, code int, contentType string, body []byte) {
	text := map[int]string{200: "OK", 400: "Bad Request", 401: "Unauthorized"}[code]
	var b strings.Builder
	b.WriteString(fmt.Sprintf("HTTP/1.1 %d %s\r\n", code, text))
	if code == 200 && len(body) == 0 {
		b.WriteString("\r\n")
		_, _ = conn.Write([]byte(b.String()))
		return
	}
	if contentType != "" {
		b.WriteString("Content-Type: " + contentType + "\r\n")
	}
	b.WriteString(fmt.Sprintf("Content-Length: %d\r\n\r\n", len(body)))
	_, _ = conn.Write([]byte(b.String()))
	_, _ = conn.Write(body)
}

func (f *finder) handleHTTPConn(conn net.Conn, ch chan []action) {
	defer conn.Close()
	br := bufio.NewReader(conn)
	requestLine, err := br.ReadString('\n')
	if err != nil && len(requestLine) == 0 {
		return
	}
	requestLine = strings.TrimRight(requestLine, "\r\n")
	fields := strings.Fields(requestLine)
	// Read headers.
	headers := map[string]string{}
	for {
		line, err := br.ReadString('\n')
		if err != nil {
			break
		}
		line = strings.TrimRight(line, "\r\n")
		if line == "" {
			break
		}
		if idx := strings.Index(line, ":"); idx >= 0 {
			headers[strings.ToLower(strings.TrimSpace(line[:idx]))] = strings.TrimSpace(line[idx+1:])
		}
	}
	method := ""
	path := ""
	if len(fields) >= 1 {
		method = fields[0]
	}
	if len(fields) >= 2 {
		path = fields[1]
	}
	pathname := path
	queryStr := ""
	if idx := strings.Index(path, "?"); idx >= 0 {
		pathname = path[:idx]
		queryStr = path[idx+1:]
	}
	isValid := (method == "GET" || method == "POST") && pathname == "/"
	if !isValid {
		writeHTTPResponse(conn, 400, "", []byte("invalid request method\n"))
		return
	}
	var body []byte
	if method == "POST" {
		clStr, ok := headers["content-length"]
		cl, cerr := strconv.Atoi(clStr)
		if !ok || cerr != nil || cl <= 0 {
			writeHTTPResponse(conn, 400, "", []byte("invalid content length\n"))
			return
		}
		body = make([]byte, cl)
		if _, err := io.ReadFull(br, body); err != nil {
			writeHTTPResponse(conn, 400, "", []byte("invalid content length\n"))
			return
		}
	}
	if key := os.Getenv("FZF_API_KEY"); key != "" {
		if headers["x-api-key"] != key {
			writeHTTPResponse(conn, 401, "", []byte("invalid api key\n"))
			return
		}
	}
	if method == "GET" {
		// Request the state from the finder loop.
		if f.stateReqCh != nil {
			reply := make(chan []byte, 1)
			f.stateReqCh <- stateRequest{query: queryStr, reply: reply}
			data := <-reply
			writeHTTPResponse(conn, 200, "application/json", data)
			return
		}
		writeHTTPResponse(conn, 200, "application/json", f.stateJSON(queryStr))
		return
	}
	// POST actions.
	acts, perr := parseActionString(string(body))
	if perr != nil {
		writeHTTPResponse(conn, 400, "", []byte(perr.Error()+"\n"))
		return
	}
	if !f.o.listen.unsafe && isRemoteConn(conn) && containsExecAction(acts) {
		writeHTTPResponse(conn, 400, "", []byte("remote process execution is not allowed\n"))
		return
	}
	ch <- acts
	writeHTTPResponse(conn, 200, "", nil)
}

func isRemoteConn(conn net.Conn) bool {
	addr := conn.RemoteAddr()
	if addr == nil {
		return false
	}
	if _, ok := addr.(*net.UnixAddr); ok {
		return false
	}
	host, _, err := net.SplitHostPort(addr.String())
	if err != nil {
		return false
	}
	ip := net.ParseIP(host)
	if ip == nil {
		return host != "localhost"
	}
	return !ip.IsLoopback()
}

func containsExecAction(acts []action) bool {
	for _, a := range acts {
		switch a.name {
		case "execute", "execute-silent", "become", "reload", "reload-sync", "preview", "transform", "change-preview":
			return true
		}
		if strings.HasPrefix(a.name, "transform") || strings.HasPrefix(a.name, "bg-transform") {
			return true
		}
	}
	return false
}

type stateRequest struct {
	query string
	reply chan []byte
}

func (f *finder) stateJSON(queryStr string) []byte {
	limit := 100
	offset := 0
	for _, part := range strings.Split(queryStr, "&") {
		if part == "" {
			continue
		}
		kv := strings.SplitN(part, "=", 2)
		if len(kv) != 2 {
			continue
		}
		if kv[0] == "limit" {
			if n, err := strconv.Atoi(kv[1]); err == nil {
				limit = n
			}
		}
		if kv[0] == "offset" {
			if n, err := strconv.Atoi(kv[1]); err == nil {
				offset = n
			}
		}
	}
	type itemJSON struct {
		Index int    `json:"index"`
		Text  string `json:"text"`
	}
	matched := 0
	for _, res := range f.results {
		if res.matched {
			matched++
		}
	}
	if !f.rawMode {
		matched = len(f.results)
	}
	var matches []itemJSON
	for i, res := range f.results {
		if i < offset {
			continue
		}
		if len(matches) >= limit && limit >= 0 {
			break
		}
		matches = append(matches, itemJSON{Index: res.item.index, Text: res.item.orig})
	}
	if matches == nil {
		matches = []itemJSON{}
	}
	var selected []itemJSON
	for _, it := range f.selectedItemsInResultOrder() {
		selected = append(selected, itemJSON{Index: it.index, Text: it.orig})
	}
	if selected == nil {
		selected = []itemJSON{}
	}
	progress := 100
	if f.isReading() && len(f.items) == 0 {
		progress = 0
	}
	type stateJSON struct {
		Reading    bool       `json:"reading"`
		Progress   int        `json:"progress"`
		Query      string     `json:"query"`
		Position   int        `json:"position"`
		Sort       bool       `json:"sort"`
		TotalCount int        `json:"totalCount"`
		MatchCount int        `json:"matchCount"`
		Current    *itemJSON  `json:"current,omitempty"`
		Matches    []itemJSON `json:"matches"`
		Selected   []itemJSON `json:"selected"`
	}
	state := stateJSON{
		Reading: f.isReading(), Progress: progress, Query: string(f.query),
		Position: maxInt(0, f.current), Sort: f.sortOn, TotalCount: len(f.items),
		MatchCount: matched, Matches: matches, Selected: selected,
	}
	if it := f.currentItem(); it != nil {
		state.Current = &itemJSON{Index: it.index, Text: it.orig}
	}
	data, _ := json.Marshal(state)
	return append(data, '\n')
}
