import pathlib
p=pathlib.Path("input.go"); s=p.read_text(); start=s.index("func walkInputs"); new=r'''func walkInputs(o *options, emit func(string)) {
	roots := o.walkerRoots
	if len(roots) == 0 {
		roots = []string{"."}
	}
	skip := map[string]bool{}
	for _, s := range o.walkerSkip {
		skip[s] = true
	}
	type dirTask struct {
		fs      string
		display string
		isRoot  bool
	}
	var queue []dirTask
	for _, root := range roots {
		st, err := os.Stat(root)
		if err != nil {
			if lst, lerr := os.Lstat(root); lerr == nil && !lst.IsDir() && o.walkerFile {
				emit(root)
			}
			continue
		}
		if !st.IsDir() {
			if o.walkerFile {
				emit(root)
			}
			continue
		}
		display := root
		if root == "." {
			display = ""
		}
		queue = append(queue, dirTask{fs: root, display: display, isRoot: true})
	}
	for len(queue) > 0 {
		task := queue[0]
		queue = queue[1:]
		if !task.isRoot && o.walkerDir {
			emit(task.display + "/")
		}
		entries, err := os.ReadDir(task.fs)
		if err != nil {
			continue
		}
		sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
		var subdirs []dirTask
		var others []os.DirEntry
		emitFile := func(e os.DirEntry) {
			name := e.Name()
			display := name
			if task.display != "" {
				display = filepath.Join(task.display, name)
			}
			if o.walkerFile {
				emit(display)
			}
		}
		for _, e := range entries {
			name := e.Name()
			fsPath := filepath.Join(task.fs, name)
			display := name
			if task.display != "" {
				display = filepath.Join(task.display, name)
			}
			isSymlink := e.Type()&os.ModeSymlink != 0
			isDir := e.IsDir()
			if isSymlink {
				if st, err := os.Stat(fsPath); err == nil && st.IsDir() {
					if !o.walkerFollow {
						continue
					}
					isDir = true
				}
			}
			if isDir {
				if skip[name] {
					continue
				}
				if !o.walkerHidden && strings.HasPrefix(name, ".") {
					continue
				}
				subdirs = append(subdirs, dirTask{fs: fsPath, display: display})
				continue
			}
			if e.Type().IsRegular() {
				emitFile(e)
			} else {
				others = append(others, e)
			}
		}
		for _, e := range others {
			emitFile(e)
		}
		queue = append(queue, subdirs...)
	}
}
'''
s=s[:start]+new; p.write_text(s)
